window.__D("text/torat-shmuel/c046",{"p":[[2000480088,"ישכיל ויתבונן בגדולת הבורא כנ\"ל באריכות<sup data-n=\"165\">164</sup> שעי\"ז יוליד האהבה ברשפי אש, הנה שמן זה הוא נמשך אחר הפתילה היא עצם הנשמה שהיא המחברת חכ' שבנה\"ב להאיר באור המאיר להיות מוסיף אור על בחי' נר הוי' הוא בחי' נה\"א מצד עצמה כו', והכח הזה שיש בנה\"ב להוסיף אור בנה\"א בחי' נר ה' זהו לפי ששרשה מעולם התהו<sup data-n=\"166\">165</sup> שקדם לתיקון<sup data-n=\"167\">166</sup> וע\"י בירור נה\"ב נמשך תוס' אורות מאורות דתהו לבוא לידי גילוי בבחי' התיקון, שמעקודים נקודים נעשה ברודים<sup data-n=\"168\">167</sup> כו', ונמשך ע\"י הפתילה היא הנה\"א יעקב חבל נחלתו שע\"י הנענוע מאיר ראש העליון שהוא בחי' ראשית הק\"ו מבחי' מל' דא\"ס, לבוא בגילוי בעולם האצי' עד הנשמות דאצי' וכל נשמה גם דבי\"ע יש בה מבחי' חכ' דאצי' כמ\"ש בסש\"ב<sup data-n=\"169\">168</sup>, ולכן עי\"ז מאיר בחי' הנר ה' דנה\"א כו', וזהו נר ה' נשמת אדם שהנשמה היא הנה\"א היא בחי' נר הוי' כו', וע\"י שנתלבשה באדם א' דם<sup data-n=\"170\">169</sup> שהדם הוא הנפש המחיה את הגוף ונה\"ב שיבא לבחי' אלף הוא בחי' אלופו ש\"ע<sup data-n=\"171\">170</sup>, וזהו שמסיים חופש כל חדרי בטן<sup data-n=\"172\">171</sup> פי' ע\"ד צדיק אוכל לשובע נפשו<sup data-n=\"173\">172</sup>, שיהי' אכילתו לש\"ש בכדי שיוכל ללמוד ולהתפלל, משא\"כ בטן רשעים כשאוכל לתאוות נפשו למלאות כו' תחסר כמ\"ש בד\"ה ראשי המטות<sup data-n=\"174\">173</sup>, וכשנשמת אדם חופש כל חדרי בטן שהדם שמאכו\"ש יהי' הדם בטל לבחי' הא' כו', הנה עי\"ז מתוסף תוס' אור בנר הוי' שיאיר אותה באור זך ורב ע\"י בחי' שמן זך הוא בירור החכ' דנה\"ב שנעשה זך שגם הוא יבין גדולת הבורא שז\"ע זכות הדבר והתבררותו כו' כמו שהזכות הוא כשנברר מהפסולת כו' כמ\"ש במ\"א כו', וזהו ואהבת ב\"פ אור<sup data-n=\"175\">174</sup> אור הא' זהו האור דנר ה' נשמת הוא הנה\"א מצד עצמה, והב' הוא אור הנוסף מבירור דנה\"ב שהיא תוס' וריבוי שלא בערך להיותו מבירור דתהו ששם ריבוי הוא, שאינו אור זה עצמו רק שהוא בריבוי אלא שהוא אור אחר לגמרי והראי' מאור שנברא ביום ראשון<sup data-n=\"176\">175</sup> כמ\"ש מזה בביאור לד\"ה אם בחוקתי (ך\"ו)<sup data-n=\"177\">176</sup>,",[["165","164","<b>כנ\"ל באריכות</b>: פ\"ו."],["166","165","<b>בנה\"ב. . שרשה מעולם התהו</b>: ראה תו\"ח נח ס, ג ובהנסמן במ\"מ לשם. סה\"מ תרע\"ח ע' רפ."],["167","166","<b>התהו שקדם לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ. ראה גם לקמן מאמר ד\"ה ביום השמיני עצרת הערה 51."],["168","167","<b>דתהו. . התיקון שמעקודים נקודים. . ברודים</b>: ויצא לא, י. יב. ראה גם הגהת מהרנ\"ש על ע\"ח דרוש העקודים פ\"א מ\"ת אות כד. תו\"א מקץ לט, ג. תו\"ח נח סד, ב ובהנסמן במ\"מ לשם."],["169","168","<b>וכל נשמה. . דאצי' כמ\"ש בסש\"ב</b>: תניא פי\"ח. ראה גם לקמן מאמר ד\"ה וזהו שרש יונתי על יד הערה 23. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים על יד הערה 10 ואילך."],["170","169","<b>באדם א' דם</b>: ראה מבו\"ש ש\"ה ח\"ב פ\"ה. של\"ה (בהקדמת ב\"י ב\"ד) כא, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תמב. תו\"ח בראשית לה, א ובהנסמן במ\"מ לשם. אוה\"ת (יהל אור) תהלים ריש ע' שנח."],["171","170","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["172","171","<b>חופש כל חדרי בטן</b>: סיום הכתוב נר ה' נשמת אדם — משלי כ, כז."],["173","172","<b>צדיק אוכל לשובע נפשו</b>: משלי יג, כה. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואמנם יש עוד בחי' חולה ובהערה 13."],["174","173","<b>צדיק. . בטן רשעים. . בד\"ה ראשי המטות</b>: ראה סה\"מ תרל\"ח ריש ע' קסו. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרפח."],["175","174","<b>ואהבת ב\"פ אור</b>: ראה פע\"ח שער הק\"ש ש\"ח, פכ\"ג. פכ\"ה. מאמרי אדה\"א שמות ח\"ב ע' שנא. וש\"נ. דברים ח\"ד ע' א'תקה ואילך. וש\"נ. תו\"ח וארא ח\"א סה, ג. וש\"נ."],["176","175","<b>מאור שנברא ביום ראשון</b>: ראה חגיגה יב, א. ב\"ר פי\"ב, ו. פי\"א, ב."],["177","176","<b>בביאור לד\"ה אם בחוקתי (ך\"ו)</b>: ראה סה\"מ תר\"ל ע' קנ<sup data-n=\"e57\">ט</sup>. תרכ\"ז ע' קיט. וש\"נ. ע' שעד. תרכ\"ט ע' תט. וש\"נ. תרל\"ב ח\"א ע' קסג. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת נח כרך ו ע' 2136. לקמן מאמר ד\"ה ביום השמיני עצרת פיסקא וענין בחי' ריבוי האור.\n\n<b>ט</b>  שהוא ביאור לד\"ה אם בחוקתי הנ\"ל בתוס' התחלה וסיום."]]],[2000480089,"ובעבודה בבחי' &lt;10&gt;\nּ האהבה זהו ההפרש בין בכל נפשך לבכל מאדך, בכל נפשך זהו האהבה דנה\"א, שהוא לפי\"ע הכלי, אבל בכל מאדך זהו בלי גבול למעלה מהגבלת הכלי זהו ע\"י בירור דנה\"ב ששרשו מבחי' התהו שהם בל\"ג שהרי הכלים לא סבלו אותם כו'.\n<b></b>קיצור. שע\"י בירור נה\"ב נעשה תוס' אור בנר ה' נשמת אדם, וז\"ע ואהבת ב\"פ אור בכל נפשך ובכל מאדך שנעשה ע\"י בכל לבבך בשני יצריך כו'.",[]],[2000480090,"<h3>[יפה שעה אחת] ועפ\"ז כו' נרי בידך</h3>\n<b>פ' ראה</b>\nח) <b>ועפ\"ז</b><sup data-n=\"178\">177</sup> יובן דרז\"ל במד\"ר ראה, נרי בידך ונרך בידי<sup data-n=\"179\">178</sup>, אם שמרתם ד\"ת הריני משמר אתכם, והענין דהנה ארז\"ל במשנה דאבות יפה שעה א'<sup data-n=\"180\">179</sup> בתשו' ומעש\"ט בעוה\"ז מכל חיי העוה\"ב, אשר לכאו' אינו מובן הלא עוה\"ב הוא הג\"ע הוא תשלום שכר על עשיית התומ\"צ וא\"כ האיך העבודה שעה א' בתשומע\"ט בעוה\"ז יפה מכל חיי העוה\"ב, וגם אומרו מכל חיי העוה\"ב באפשר לפרש שכולל גם עולם התחיה ג\"כ, הגם שבסתם דרז\"ל במשנה ברוב המקומות כוונתם באמרם עוה\"ב הוא ג\"ע כמו כל ישראל יש להם חלק לעוה\"ב<sup data-n=\"181\">180</sup> הכוונה על ג\"ע שהרי מביא הפסוק לעולם ירשו ארץ<sup data-n=\"182\">181</sup> שמפרשים זה על ג\"ע התחתון, ונודע הפלוגתא שיש בזה מגדולי הראשונים הרמב\"ם והרמב\"ן ז\"ל<sup data-n=\"183\">182</sup>, אמנם אומרם מכל חיי העוה\"ב לכאו' י\"ל שכולל גם עולם התחיה, שזהו כל חיי היינו חיי הנפש בג\"ע",[["178","177","<b>ועפ\"ז כו' נרי בידך</b>: מכאן מתחיל מאמר הג' מהמשך יונתי (הכולל פרקים ח-יו\"ד).\nממאמר זה ישנם עוד שני הנחות והפתיחא בהם היא : יפה שעה אחת. ההנחות הם: א) הנחת<sup data-n=\"e58\">*</sup> כ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן (בחלק הנחותיו). ב) הנחה אחרת נדפסה לקמן (בחלק ההנחות)."],["179","178","<b>במד\"ר ראה נרי בידך ונרך בידי</b>: ראה דב\"ר פ\"ד, ד. ראה גם סה\"מ תרכ\"ט ע' רלד ובהנסמן שם."],["180","179","<b>יפה שעה א'</b>: אבות פ\"ד, מי\"ז. ראה גם המשך וככה תרל\"ז רפ\"ט."],["181","180","<b>כל ישראל. . לעוה\"ב</b>: סנהדרין ר\"פ חלק (צ, א)."],["182","181","<b>לעולם ירשו ארץ</b>: ישעי' ס, כא [שם ובהמשך יונתי הנדפס: יירשו]. ראה לקו\"ת ואתחנן ט, א."],["183","182","<b>הפלוגתא. . הרמב\"ם והרמב\"ן ז\"ל</b>: ראה רמב\"ם הל' תשובה פ\"ח, ה\"ב. פיה\"מ ר\"פ חלק. (אגרת) מאמר תחיית המתים. רמב\"ן בסוף שער הגמול. תשובות וביאורים (קה\"ת תשל\"ד) סי\"א ע' 57 הערה 23."],["e58","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000480091,"בלתי גוף, וחיי עולם התחי' שתשוב הנפש להחיות הגוף ונחי' חיי רוחני' בגוף דוקא, וכמשנ\"ת מזה באריכות בד\"ה אלה תולדות נח בסופו<sup data-n=\"184\">183</sup> ע\"ש, ולפ\"ז לכאו' יפלא מאד היתכן שהקב\"ה יקפח שכר ברי'<sup data-n=\"185\">184</sup>, ואיך עשיית המצוה יפה יותר מקיבול שכרה, והלא לא מצינו יותר גדול מעולם התחי' כו'. ויובן זה בהקדם שרש ענין ירידת הנשמה בגוף שלכאו' הוא ירידה גדולה ועצומה מאד שאין כמוה שהרי הנשמה קודם התלבשותה בגוף היתה עומדת באהוי\"ר כמ\"ש חי ה' אשר עמדתי לפניו<sup data-n=\"186\">185</sup>, ועמידתה לפניו ז\"ע האוי\"ר שהי' לה, ע\"ד המלאכי' שנק' עומדים כמ\"ש שרפים עומדים<sup data-n=\"187\">186</sup>, ויעמידם לעד לעולם<sup data-n=\"188\">187</sup> שא' בסיפור הילולם כו', וא\"כ למה היתה כזאת מלפניו ית' שתרד הנפש כ\"כ פלאים למטה מטה להתלבש בגוף ונה\"ב גשמי שנק' בשם יצה\"ר גם כשכבר פעל בו הביטול כנ\"ל<sup data-n=\"189\">188</sup> משום אל תאמין בעצמך<sup data-n=\"190\">189</sup>, אלא ע\"כ בהכרח לומר שיש איזהו יתרון בירידתה זו, וצ\"ל מהו, והענין הוא כמ\"ש במ\"א באריכות שעיקר מכוון בברה\"ע, הוא בשביל התומ\"צ וכמ\"ש בראשית ברא וארז\"ל בשביל ישראל שנק' ראשית ובשביל התורה<sup data-n=\"191\">190</sup> שנק' ראשית, וכן דרז\"ל ע\"פ עשרה עשרה הכף<sup data-n=\"192\">191</sup> שעשה\"ד הם כנגד עש\"מ<sup data-n=\"193\">192</sup>, תנאי התנה הקב\"ה<sup data-n=\"194\">193</sup> עם מע\"ב אם יקיימו ישראל כו', וכן ע\"פ אלה תולדות השמים והארץ<sup data-n=\"195\">194</sup>, אלה בזכות מי נבראו ובזכות כו' בזכות אלה שמות בנ\"י<sup data-n=\"196\">195</sup> כו' ואלה בזכות כו' בזכות אלה העדות<sup data-n=\"197\">196</sup> כו', וכתי' אנכי עשיתי ארץ<sup data-n=\"198\">197</sup> ואדם עליה בראתי, שנשפל &lt;11&gt;\nּ מבחי' אנכי מי שאנכי<sup data-n=\"199\">198</sup> לעשות ארץ הלזו הגשמי' בשביל מציאות האדם שבראתי עליה שהוא מובחר הנבראים בארץ הלזו, ובראת\"י בגימ' תרי\"ג<sup data-n=\"200\">199</sup> שמכוון בריאת האדם הוא בשביל",[["184","183","<b>עולם התחי'. . להחיות הגוף. . אלה תולדות נח בסופו</b>: תרל\"ז — לא נדפס לע\"ע. ראה גם לקמן פט\"ז. סה\"מ תרל\"ח ע' לב."],["185","184","<b>היתכן שהקב\"ה יקפח שכר ברי'</b>: ראה ב\"ק לח, ב."],["186","185","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם תו\"א בשלח סב, סע\"ד. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["187","186","<b>שרפים עומדים</b>: ישעי' ו, ב. ראה סוטה לט, א (צויין אליו ב) לקו\"ת נשא כ, ג. כב, ג."],["188","187","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 15."],["189","188","<b>כנ\"ל</b>: פ\"ו."],["190","189","<b>אל תאמין בעצמך</b>: אבות פ\"ב, מ\"ד."],["191","190","<b>בראשית ברא. . ישראל. . התורה</b>: בראשית א, א. ראה רש\"י בראשית א, א. תו\"ח בראשית מד, א הערה 6. ראה גם תו\"ח שם ז, א ואילך."],["192","191","<b>עשרה עשרה הכף</b>: נשא ז, פו."],["193","192","<b>שעשה\"ד. . עש\"מ</b>: ראה זהר יתרו צג, ב. ויקרא יא, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1682."],["194","193","<b>תנאי התנה הקב\"ה</b>: ראה שבת פח, א. לעיל המשך מצה זו שם הערה 1686."],["195","194","<b>אלה תולדות השמים והארץ</b>: בראשית ב, ד. ראה שמו\"ר פמ\"ח, [ב]."],["196","195","<b>אלה שמות בנ\"י</b>: שמות א, א [ושם: ואלה — אבל כ\"ה בשמו\"ר שם. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואלא עלמא אמאי קאים ובהערה 17]."],["197","196","<b>אלה העדות</b>: ואתחנן ד, מה."],["198","197","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב. ראה גם לקמן פט\"ז."],["199","198","<b>אנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["200","199","<b>ובראת\"י בגימ' תרי\"ג</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1688 מהרמ\"ז והה\"מ."]]],[2000480092,"קיום תרי\"ג<sup data-n=\"201\">200</sup> מצות וכמ\"ש סוף דבר כו' כי זה כל האדם<sup data-n=\"202\">201</sup> כו', והנה כל תרי\"ג מצות הם מופלאי' מהשכל, כי הגם שיש הרבה מצות שמובן טעמם, זהו שענין עשייתם אינה בדרך חוקה, אבל למה יחפוץ הקב\"ה בהם זה הוא למעלה משכל המושג, וגם אפי' לפ\"ד רז\"ל שאמרו אלמלא לא ניתנה תורה<sup data-n=\"203\">202</sup> למדנו צניעות כו' הנה ג\"ז פלאי הוא למה טבע הקב\"ה טבע ההיא בנברא ההוא שנוכל ללמוד ממנו, אלא שזהו כמארז\"ל וכי מאי איכפת לי' להקב\"ה אם שוחט מן העורף או שוחט מן הצואר, אלא לא ניתנו המצות אלא לצרף בהם את הבריות<sup data-n=\"204\">203</sup>, ונת' במ\"א באריכות שענין תיבת בריות א\"א לפרש כ\"א על הנה\"ב לבד דוקא כו' ע' בד\"ה וככה תאכלו<sup data-n=\"205\">204</sup> באריכות, ובשביל זה הוא ג\"כ ירידת הנשמה בגוף ג\"כ שע\"י ירידה זו היא מתעלית בעילוי אחר עילוי עד רום המעלות כו', כי הנה\"ב גדלה ורב כוחה להעלות במעלות את נה\"א להיות רוח האדם שעולה גם מצ\"ע עולה עוד למעלה מעלה כו'.\n<b></b>קיצור. נרי בידך ונרך בידי, יפה שעה א', ולכאו' אינו מובן, ויובן בהקדם ענין ירידת הנשמה בגוף שהוא בשביל קיום המצות שע\"י יתברר נה\"ב וע\"י רוח האדם עולה כו'.\nט) <b>וביאור</b> הענין הוא דהנה א\"א נשמה שנתת בי טהורה היא אתה בראת<sup data-n=\"206\">205</sup>, ולכאו' אינו מובן מה\"ע טהורה היא קודם בראת, שקודם שנבראת אינו שייך לכאו' ענין קריאת שם כלל, אך הענין דהנה כל הנשמות אפי' נשמות הגבוהות כמו בני עלי'<sup data-n=\"207\">206</sup> ג\"כ היו אומרים כנוסח הזה שתקנו אנשי כנה\"ג<sup data-n=\"208\">207</sup>, ושהי' מסור בידם איש מפי איש<sup data-n=\"209\">208</sup> שכל דבריהם דברי קבלה, ונמצא שנשמות דאצי' ג\"כ אמרו כן, והיינו שעם היות הם נשמות דאצי' בבחי' זרע אדם כמ\"ש בת\"א בד\"ה ואלה המשפטים עכ\"ז בכדי שיחיו גוף הגשמי שלמטה בארץ הוצרכו לירד דרך בי\"ע דוקא",[["201","200","<b>תרי\"ג</b>: בהמשך יונתי הנדפס ליתא."],["202","201","<b>סוף דבר. . האדם</b>: קהלת יב, יג."],["203","202","<b>אלמלא לא ניתנה תורה</b>: ערובין ק, ב. ראה גם לקו\"ש יתרו כרך ג ע' 890 הערה 12. חוקת כרך ח ע' 130 ואילך ובהערה 49. כ\"ד טבת כרך כא ע' 284."],["204","203","<b>וכי מאי. . לצרף בהם את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד."],["205","204","<b>בריות. . הנה\"ב. . בד\"ה וככה תאכלו</b>: לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 48 (ובסה\"מ תרל\"ח ריש ע' נד) כותב: ”ד\"ה מים רבים ל\"ו\" — פק\"י ע' קטו. ראה גם לקמן מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 164. (בחלק ההנחות) הנחה ד\"ה יפה שעה אחת הא' על יד הערה 49. ד\"ה שובה ישראל הא' על הערה 168."],["206","205","<b>נשמה. . טהורה. . בראת</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 92."],["207","206","<b>בני עלי'</b>: סוכה מה, ב."],["208","207","<b>כנוסח הזה שתקנו אנשי כנה\"ג</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. מאמרי אדה\"ז תקס\"ג ח\"א ע' קכד. תו\"ח וארא ח\"א עד, א."],["209","208","<b>אנשי כנה\"ג. . איש מפי איש</b>: לקמן בשני ההנחות ניתוסף: אמרו מרע\"ה<sup data-n=\"e59\">א</sup>. ראה תו\"א בראשית ו, א. סה\"מ תרל\"ח ע' צא ובהערה 52.\n\n<b>א</b>  ראה פע\"ח שבסה\"מ תרל\"ח המובא בפנים ההערה."]]],[2000480093,"ולכן אומרים בראת יצרת נפחת<sup data-n=\"210\">210</sup> כו', וכמו\"כ גם נשמות דבי\"ע שהם הנק' בשם זרע בהמה<sup data-n=\"211\">209</sup> ג\"כ אומרים טהורה היא, והיינו שעם היות שהם נשמות דבי\"ע עכ\"ז שרש שרשם הוא בבחי' טה\"ע<sup data-n=\"212\">211</sup> אלא שירדו להיות בחי' נשמות דבי\"ע כו' כמ\"ש במ\"א.\n<b>והנה</b> לפ\"ז צ\"ל שרש ענין העלי' שע\"י ירידה זו מה היא, דהנה נת' בד\"ה אז ישיר שבמאמר מצה זו<sup data-n=\"213\">212</sup>, שעם היות שבאותיות הרשימו נגע בהן הצמצום, מ\"מ זהו רק בפעולת האותיות ולא באותיות עצמן, וגם בבחי' פעולתם זהו ג\"כ בהאור לבד שהאור נסתלק, והאותיות לא זזו ממקומן, ולכן בכח האותיות לגלות השכל ע\"ש כו', &lt;12&gt;\nּ א\"כ נש\"י ששרשם מפנימיות הכלים<sup data-n=\"214\">213</sup> כו' כמ\"ש בת\"א בד\"ה זכור ושמור דרוש השני<sup data-n=\"215\">214</sup>, ובד\"ה שחורה אני דרוש השני<sup data-n=\"216\">215</sup>, שזהו קודם ירידתם בגוף, ומהו עלייתם כשמתעלים בבחי' האור כו'.\n<b>והענין</b> הוא דהנה איהו וחיוהי חד ואיהו וגרמוהי חד<sup data-n=\"217\">216</sup> בהון, א' ב\"פ חד שלא כמו שמתייחד בחי' איהו עם גרמוהי מתייחד הוא עם בחי' חיוהי, שענין היחוד שמתייחד עם חיוהי הוא בא\"א לגמרי, ולכאו' אינו מובן מאחר שהוא ית' מתייחד עם בחי' גרמוהי עד שבורא בהן וע\"י יש מאין כמ\"ש באגה\"ק ד\"ה איהו וחיוהי<sup data-n=\"218\">217</sup>, שזהו רק בחיק הבורא ולא בחיק הנבראי', וגם בחי' גרמוהי עצמן איך שנפרש אותם אם הם בחי' כלים או ז\"ת<sup data-n=\"219\">218</sup> ג\"כ אין בכוחם לברוא יש מאין דאל\"כ לא ה\"צ שבחי' איהו יתייחד עמהן לברוא יש מאין כו', ומאחר שלצורך שיברא בריאה חדשה זהו מבחי' איהו דוקא אלא שמתייחד עם גרמוהי<sup data-n=\"220\">219</sup> כדי שיתהוו הנבראים ליש כמ\"ש במ\"א, מהו ההפרש בין בחי' איהו וגרמוהי לבחי' איהו וחיוהי, ואם נאמר שזהו רק ההפרש בין חיוהי לגרמוהי לבד אבל בבחי' שמתייחד עמהן לא יש הפרש ביניהן כלל הי' די לנו במה שא' חד פ\"א, שההפרש בין חיוהי לגרמוהי מובן מצד עצם פי' התיבות, ומהו אומרו ב\"פ חד הכוונה שעם היות אוא\"ס פשוט בתכלית הפשיטות עכ\"ז מתראה הוא בכמה חילוקי מדרגות עד אשר ע\"י שמחלק לאמר ב\"פ חד זהו להורות שבחי' איהו",[["210","210","<b>בי\"ע. . נפחת</b>: ראה תו\"א משפטים עז, סע\"א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א."],["211","209","<b>נשמות. . זרע אדם. . זרע בהמה</b>: ראה תו\"א ותו\"ח ר\"פ משפטים. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 29."],["212","211","<b>טהורה. . טה\"ע</b>: ראה גם לקמן פ\"י. מאמרי אדה\"א דברים ח\"ב ס\"ע תנח ואילך. שע\"ת ל, ב ובהערה 17. סה\"מ תרל\"ח ע' ערה. וש\"נ."],["213","212","<b>בד\"ה אז ישיר שבמאמר מצה זו</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ו. פ\"ז."],["214","213","<b>נש\"י ששרשם מפנימיות הכלים</b>: ראה גם (בנוסף על המצויין בפנים) לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 16."],["215","214","<b>בת\"א בד\"ה זכור ושמור דרוש השני</b>: ראה שם יתרו עב, ב."],["216","215","<b>ובד\"ה שחורה אני דרוש השני</b>: לקו\"ת שה\"ש ח, ג."],["217","216","<b>איהו וחיוהי. . וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 99. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' מג. וש\"נ."],["218","217","<b>באגה\"ק ד\"ה איהו וחיוהי</b>: ס\"כ (תניא קכט, ב. קל, ב)."],["219","218","<b>גרמוהי. . כלים או ז\"ת</b>: ראה גם סה\"מ תרל\"ג ח\"ב ע' תלה ובהערה שם. לעיל ח\"א המשך זאת חנוכת המזבח ובהערה 100. (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 52."],["220","219","<b>בריאה. . מבחי' איהו. . שמתייחד עם גרמוהי</b>: ראה אגה\"ק ס\"כ קל, ב. סה\"מ תרל\"ח ע' ד."]]],[2000480094,"שמתייחד עם גרמוהי עם היות שזהו בחי' איהו כו' עכ\"ז בחי' איהו שמתייחד עם חיוהי הוא בחי' היותר נעלה שלא בערך ממש כו'<sup data-n=\"221\">220</sup>, וצ\"ל מהו. והענין הוא דהנה נת' שבחי' איהו וגרמוהי חד זהו מה שהוא ית' מתייחד עם בחי' גרמוהי להוות<sup data-n=\"222\">221</sup> בהם וע\"י יש מאין, שז\"ע שיהי' נמשך ליש ודבר נפרד נבדל בפ\"ע, הגם שבאמת אין לך דבר שחוץ ממנו כלל, וגם אחר הצמצום וסילוק האור הנה הוא ממלא החלל כמקדם וההפרש הוא רק בין העלם לגילוי וכדכתי' את השמים ואת הארץ אני מלא<sup data-n=\"223\">222</sup>, אני הוא אוא\"ס עצומ\"ה כאדם האומר ע\"ע אני כוונתו הוא עצמו כו' א\"כ אני מלא גם עכשיו אלא שזהו בהעלם כו', עכ\"ז לגבינו נדמה שהוא דבר יש נפרד בפ\"ע, אמנם להיות כי כל דבר מוכרח שיהי' לו חיות ואור המקיימו כו' כמו שהנפש מחיה את הגוף אנו רואים שיש איזהו דבר שמחיה את הגוף הגם שאין אנו משיגים מהו אך אנו יודעים ברור שיש כו' שהרי בצאת הנפש מהגוף ה\"ה אבן דומם מוטל לארץ כו', כן גם הגוף לאחר הסתלקות<sup data-n=\"224\">224</sup> הנפש מוכרח לומר שיש דבר המחייהו שהוא בדמותו ובצלמו כמו שהי' קודם הסתלקות הנפש, מלבד הקיסטא דחיותא<sup data-n=\"225\">225</sup> שנשאר שזהו בשביל הרגש הנפש ממקרי הגוף, כמ\"ש ונפשו עליו תאבל<sup data-n=\"226\">226</sup> כו', וקשה רימה למת<sup data-n=\"227\">227</sup> כו', אמנם מה שהגוף הוא בדמותו זהו מפני עצם ענין חיות שמחי' הגוף עצמו &lt;13&gt;\nּ להיות בחי' גוף מוטל כאבן דומם, וכמו גופו של אדה\"ר שהי' מעפר<sup data-n=\"228\">228</sup> קודם שנפח בו נשמת חיים, וכמו העץ לאחר שכורתים אותו שאין לו הרגש כלל מהנפש הצומחת, ושב ונשתנה למהות אחר היינו כמו דומם<sup data-n=\"229\">229</sup> והוא מפני שנפשו הצומחת מסתלק ממנו ע\"י כריתתה ממקום גידולה, ועכ\"ז אינה מתבטל אצלה כלליות צורתה כ\"א צורת חיותה הוא אשר מתבטל, והרי כשנרקבת הנה היא נעשית לעפר ומי הוא המקיימה שלא יבטל הרכבת ד\"י<sup data-n=\"230\">223</sup> שבה, אלא שזהו נמשך מבחי' איהו בעצם המתייחד עם בחי' גרמוהי שעי\"ז נעשית בה החיות הן בעת חיותה והן לאח\"כ שבזה נק' עדיין חיה עד שנרקבת והיתה לעפר ומתבטלי' כל יסודותי' ולא נשאר רק יסוד העפר שהכל הי' מן העפר<sup data-n=\"231\">230</sup> כו', וא\"כ בחי' איהו זה הוא הכח",[["221","220","<b>כו'</b>: בהמשך הנדפס ליתא."],["222","221","<b>להוות</b>: שם: לברוא."],["223","222","<b>את השמים. . מלא</b>: ירמי' כג, כד."],["224","224","<b>לאחר הסתלקות. . הקיסטא דחיותא</b>: ראה המשך וככה תרל\"ז פנ\"ח (ע' פט): ובדרושי רבינו ז\"ל בתחלת לאדי ערך תקס\"ב שכמו שבשינה. . כן גם לאחר צאת הנפש מהגוף. . ואפשר שאינו מדברי רבינו ז\"ל בכיון\" ע\"ש. ושם פ\"צ (ע' קמו — עצם לוז). סה\"מ תרמ\"ד ע' רלח. תרמ\"ו ע' תכא."],["225","225","<b>הקיסטא דחיותא</b>: ראה זהר לך פג, א. אור החמה־ רא\"ג־ מקדש מלך לזהר שם. שער הכוונת ענין דרושי הלילה דרוש ו [ושם: הנזכר בזוהר בכמה מקומות]. לקו\"ת אמור לא, ב ובנסמן במ\"מ לשם. עקב יד, רע\"א. תו\"א לך יב, ג. סידור שער המילה קמז, ב. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שלג. תקס\"ה ח\"א ע' תקו. ענינים ע' תיד. וראה גם סה\"מ תרל\"ח ס\"ע מט."],["226","226","<b>ונפשו עליו תאבל</b>: איוב יד, כב."],["227","227","<b>וקשה רימה למת</b>: ברכות יח, ב. שבת יג, ב."],["228","228","<b>גופו של אדה\"ר שהי' מעפר</b>: בראשית ב, ז."],["229","229","<b>העץ. . כמו דומם</b>: ראה גם אוה\"ת על מארז\"ל ע' יא. חוקת ס\"ע תשסח ואילך."],["230","223","<b>הגוף. . שיש דבר המחייהו. . הרכבת ד\"י</b>: ראה גם סה\"מ תרכ\"ז ע' שפה. סידור ערב שבת קסה, ד ואילך. אוה\"ת וירא כרך ד ע' תשמב. סה\"מ עזר\"ת ע' קסה. לקמן בשתי ההנחות כאן."],["231","230","<b>שהכל הי' מן העפר</b>: קהלת ג, כ."]]],[2000480095,"המהוה להיות נפרד בחי' זולת חי כו', אמנם בחי' חיוהי איך שנפרש אותו אם מוחין אם אורות<sup data-n=\"232\">231</sup> הנה זה אינו נפרד כלל, שהרי הוא וחכמתו ובינתו ודעתו אחד<sup data-n=\"233\">232</sup>, וכן אוא\"ס הוא שם אחד לאחר הצמצום כמו קודם הצמצום שהרי קודם שעלה ברצונו כו' הי' אוא\"ס ממלא כל<sup data-n=\"234\">233</sup> החלל<sup data-n=\"235\">234</sup>, א\"כ לא נשתנה שמו כלל שקודם נק' אוא\"ס וגם לאחר נק' אור א\"ס כו' והוא מפני שזהו גילויו העצמים, א\"כ גם בבחי' איהו שמתייחד עם חיוהי זהו ג\"כ הבדל והפרש גדול שבחי' איהו שמתייחד עם גרמוהי הוא מה שבכח הא\"ס להוות יש ודבר נפרד, ואיהו המתייחד עם חיוהי זהו כח ובחי' הא\"ס שמגלה הארת עצמותו כו'.\n<b></b>קיצור. טהורה היא טה\"ע, א\"כ מהו העלי' הלא הצמצום הוא רק בהאור ולא בפעולת האותיות וכ\"ש באותיות כו', איהו וחיוהי ואיהו וגרמוהי זהו הכח שבא\"ס להוות נברא והכח לגלות עצמותו כו'.\nיו\"ד) <b>וביאור</b> הענין יובן בענין ההפרש שבין מח' לדיבור ששניהם הם לבושי הנפש, שלפעמים מלביש נפשו בלבוש המח' לבד שהולך או יושב וחושב מח' ואינו מדבר כלל, ולפעמים מדבר ומלביש שכלו או רצונו בלבוש הדבור, וההפרש שביניהם הוא שלבוש הדבור הנה הוא המגלה העלם העצמי לגבי זולתו, שהרי בלתי הדבור לא יבין זולתו כלל ההשכלות שהשכיל כו', ונמצא כי פעולת הדבור הוא בכדי שיבין זולתו אבל לעצמו א\"צ לדבור כלל כ\"א לשימוש שישמש לו זולתו, או שיבין זולתו שנמצא שזהו הכל בשביל זולת רק ההבדל שזהו בשבילו וזהו בשביל זולתו כו', משא\"כ המח' הוא בשביל עצמו, שהרי בלתי המח' לא יוכל להבין את ההשכלה שלו עצמו, שהרי חכ' היא בחי' ברק המבריק לבד, ועדיין איננה ידוע לו עצמו מהו כלל, כ\"א מה שנפל לו איזה הרגש שכל מבחי' משכיל שיבוא אח\"כ לידי השגת דבר מה כו', אך ג\"ז בתנאי כשיחשוב תומ\"י מהו זה שנפל לו, ואם יעבור איזהו זמן ולא<sup data-n=\"236\">235</sup> יהרהר בזה בהרגש הדבר ההוא במוחו ולבו ע\"י לבוש המחשבה המלביש את בחי' ההרגשות האלו לא יהי' מזה שום דבר ולא ידע כלל הדבר שהשכיל וישכח ג\"כ את הברק המבריק שהבריק לו במוחו מפני צד בחי' האחוריים שיש בכח שכלו שהשכיל כו', וכנודע שהשכחה היא<sup data-n=\"e1\">*</sup>",[["232","231","<b>חיוהי. . אם מוחין אם אורות</b>: ראה לקמן פ\"י. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 100. (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 52."],["233","232","<b>הוא וחכמתו ובינתו ודעתו אחד</b>: לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 99: אמרו רז\"ל. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"י. שער היחוד והאמונה פ\"ח. תניא פ\"ב."],["234","233","<b>קודם שעלה ברצונו. . ממלא כל החלל</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["235","234","<b>ממלא כל החלל</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 215."],["236","235","<b>ולא</b>: בהמשך יונתי הנדפס: לא. וכנראה שצ\"ל כבפנים."],["e1","*","נרשם בשולי היריעה (ובהמשך הנדפס ליתא):\nחיוהי מהות גילוי עצמו גרמוהי מהות גילוי לזולתו כו' גופא דמלכא."]]],[2000480096,"מבחי' האחוריים כמ\"ש באגה\"ק<sup data-n=\"237\">237</sup> בסופו בד\"ה &lt;14&gt;\nּ דוד זמירות<sup data-n=\"238\">236</sup> קרית להו, וא\"כ פעולת המח' היא העיקר בהשכלת דבר מה כמו בחי' הברק עצמו, שהרי כשם שבלתי הברק המבריק לא ישכיל שכל חדש, כן בלתי העיון וההלבשה במח' הרגש הברק לא יהי' מאומה, א\"כ ה\"ה שוה כמותו, ונמצא כי פעולת המח' הוא להוביל ולהמשיך בחי' העלם העצמי לגבי עצמו כו', ועפ\"ז נשכיל ענין ההבדל בין חיוהי לגרמוהי שגרמוהי הוא בשביל זולת כו' וחיוהי עדיין אינו מקור על זולת כ\"א העלם העצמי שיביא<sup data-n=\"239\">238</sup> לידי גילוי שבידיעת עצמותו יודע את התורה כמ\"ש באגה\"ק סי' הנ\"ל<sup data-n=\"240\">239</sup>, וה\"ז כמשל המח' כו', רק שבזה אינו דומה המשל להנמשל שבמשל הנה גם המח' היא רק מלבושי הנפש, ובנמשל הרי החכ' היא אינה מלבושי' כו'. אך לפמ\"ש בלק\"ת בביאור דולא תשבית גם החכ' אינה עצמיות הנפש<sup data-n=\"241\">240</sup>, וצ\"ל שזהו כמ\"ש בד\"ה אוא\"ס למעלה עד אין קץ שזהו כמו גופין<sup data-n=\"242\">241</sup> שהוא ג\"כ לבוש אבל א\"א לפשוט אותו שהרי בע\"כ אתה חי<sup data-n=\"243\">242</sup> כו', רק ששם נת' על חב\"ד שבמדות ולפמשנ\"ת כאן צ\"ל ג\"כ על חב\"ד עצמם אשר עפ\"ז יושג גם למעלה בבחי' חב\"ד דאצי' כו', שזהו בחי' חיוהי לפי' הזהר, ולפי' הע\"ח ואגה\"ק זהו בחי' האורות, ונמצא כי לפ\"ז יובן ההבדל ג\"כ בבחי' איהו המתייחד עם חיוהי ועם גרמוהי שבחי' איהו שמתייחד עם גרמוהי זהו מה שיש בכח הא\"ס שיתהוה ממנו זולת כו', אבל בחי' איהו שמתייחד עם חיוהי זהו כח הא\"ס המגלה העלם העצמי בשביל עצמו<sup data-n=\"244\">243</sup> פי' מה שבידיעת עצמותו יודע את התורה כמ\"ש באגה\"ק שעז\"נ לא ידע אנוש ערכה<sup data-n=\"245\">244</sup> רק אלקי' הבין דרכה<sup data-n=\"246\">245</sup> כו', וע\"י ירידת הנשמה בגוף לברר הנה\"ב ע\"י קיום התורה והמצות ללמוד וללמד לשמור ולעשות הנה עי\"ז מתעלה הנפש מבחי' גרמוהי שזהו בחי' טהורה היא כו' בכ\"מ שנדבר, אפי' בבחי' טה\"ע זהו רק גרמוהי שהרי זהו אותיות החקיקה<sup data-n=\"247\">246</sup> כמ\"ש<sup data-n=\"e2\">*</sup>",[["237","237","<b>באגה\"ק</b>: קו\"א נקרא ג\"כ אגה\"ק — לקו\"ת ד\"ה ויקרא. ועוד. ”הערות\" בסו\"ס התניא (מהדורת קה\"ת תשי\"ד ואילך)."],["238","236","<b>שהשכחה. . האחוריים. . דוד זמירות</b>: תניא קסא, א. ראה מאו\"א מערכת שכחה סל\"ז וביאיר נתיב שם. רמ\"ז לזהר בחוקותי קיב, א (ד\"ה אר\"י א\"ל — ע' צז בדפי הספר)."],["239","238","<b>שיביא</b>: אוצ\"ל: שיבוא."],["240","239","<b>סי' הנ\"ל</b>: לעיל כאן נק' האגה\"ק בשמה ”דוד זמירות\" ללא ציון סימן. וראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 541 שהוא סל\"ו."],["241","240","<b>בלק\"ת. . החכ' אינה עצמיות הנפש</b>: ויקרא ד, ב ואילך."],["242","241","<b>בד\"ה אוא\"ס. . כמו גופין</b>: ראה אוה\"ת על ענינים ע' קיג אילך (ובהנסמן בריש המאמר שם). ע' קמג ואילך."],["243","242","<b>בע\"כ אתה חי</b>: ראה אבות ספ\"ד."],["244","243","<b>איהו עם גרמוהי. . זולת. . חיוהי. . העלם העצמי בשביל עצמו</b>: ראה גם סה\"מ תר\"ן ע' רצא ושם: בד\"ה מצה זו ר\"מ. ואולי כוונתו לכאן."],["245","244","<b>לא ידע אנוש ערכה</b>: איוב כח, יג. כתוב זה לא הובא בקו\"א כאן."],["246","245","<b>אלקי' הבין דרכה</b>: איוב שם, כג."],["247","246","<b>טה\"ע. . אותיות החקיקה</b>: ראה גם לקו\"ת בחוקותי מו, ב. ויקרא בהוספות נג, ד. חוקת נט, ג. ר\"ה נד, ד. לקמן בשתי ההנחות כאן."],["e2","*","נרשם בשולי היריעה בסיום המאמר (ובהמשך הנדפס ליתא):\nוזהו כמו קודם שבודאי הבין ג\"כ, מציאת חכ' בכדי שיהי' אח\"כ חכ' ידיעא, וא\"כ זהו ג\"כ בשביל זולת."]]],[2000480097,"במ\"א או עכ\"פ הנושא וסובל את החקיקה של האותיות כו' שז\"ע גליף גליפו בטה\"ע<sup data-n=\"248\">247</sup> כו', שנכלל ג\"כ בכלל גרמוהי שה\"ז כמו הקלף שעליו כותבים האותיות, והעלי' הוא בבחי' חיוהי לאשתאבא בגופא דמלכא<sup data-n=\"249\">248</sup> כו', וזהו נרי בידך בחי' נר מצוה ונרך בידי הוא נר הוי' נשמת אדם אם שמרתם ד\"ת ללמוד וללמד לשמור ולעשות שעי\"ז יתברר נה\"ב הנה עי\"ז אני משמר אתכם לשון אני קאי על אוא\"ס עצומ\"ה בחי' חיוהי כו', ולשון משמר אתכם י\"ל מה שאני מלא זהו בבחי' העלם שז\"ע מקיף ג\"כ לפי' א' ומזה נמשך מה שואתה משמרה בקרבי<sup data-n=\"250\">249</sup> תתעלה הנפש בבחי' אני, שאני היינו אוא\"ס עצומ\"ה משמר אתכם ע\"י שתבואו לאשתאבא בגופא דמלכא כו', וזהו יפה שעה<sup data-n=\"251\">250</sup> א' כו' דהנה ארז\"ל עתיד הקב\"ה להנחיל לכל צדיק וצדיק ש\"י עולמות<sup data-n=\"252\">251</sup>, הנה ש\"י &lt;15&gt;\nּ הוא מחצה מתר\"ך, והיינו מפני שהם עולמות מל' העלם<sup data-n=\"253\">252</sup> שכ\"ז הוא מבחי' גרמוהי כו', אבל ע\"י תומ\"צ באים לאשתאבא בגופא דמלכא בחי' חיוהי, ולכך הם תר\"ך מצות<sup data-n=\"254\">253</sup> בחי' כתר<sup data-n=\"255\">254</sup> ב\"פ ש\"י<sup data-n=\"256\">255</sup>, וגם אינו מקפח שכר כו' כי ארז\"ל עתיד הקב\"ה לעשות ראש מחול לצדיקים לע\"ל<sup data-n=\"257\">256</sup>, מחול הוא בחי' עיגול שז\"ע כלליות הכתר, והיינו שכר מצוה מצוה<sup data-n=\"258\">257</sup> פי' המצוה בעצמה כו', ונמצא כי עם היות יפה שעה א' כו' עכ\"ז לא יקפח השכר שהרי לע\"ל יתגלה עצם המצוה כמו שהיא ברוחניות כו'.\n<b></b>קיצור. מח' ודיבור, דבור בשביל זולת מח' מגלה העלם העצמי לגבי עצמו, ועד\"ז חיוהי וגרמוהי, שנמצא יש הבדל גם בבחי' איהו המתייחד ג\"כ, ודזהו העלי' של הנה\"א כו', וזהו יפה שעה א', ש\"י תר\"ך, ועכ\"ז לא יקפח, כי שכר מצוה מצוה כו'.",[["248","247","<b>גליף גליפו בטה\"ע</b>: ראה זהר בראשית טו, א."],["249","248","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני ובהערה 51."],["250","249","<b>שואתה משמרה בקרבי</b>: ברכת אלקי נשמה (מברכות ס, ב)."],["251","250","<b>יפה שעה א'</b>: ראה גם המשך וככה תרל\"ז פ\"י."],["252","251","<b>עתיד. . לכל צדיק. . ש\"י עולמות</b>: עוקצי' בסופה. ראה אוה\"ת בהעלותך ע' תטז."],["253","252","<b>עולמות מל' העלם</b>: ראה ספר הבהיר ס\"י. תו\"ח שמות ח\"א יח, ד הערה 783."],["254","253","<b>תר\"ך מצות</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול ובהערה 11."],["255","254","<b>תר\"ך. . כתר</b>: ראה ע\"ח שער ז\"א שי\"ז, ספ\"א. מאמרי אדה\"א דברים ח\"ד ע' א'רצט. וש\"נ."],["256","255","<b>תר\"ך. . ב\"פ ש\"י</b>: ראה ע\"ח שם. תו\"ח שמות ח\"א ט, א הערה 390."],["257","256","<b>עתיד. . ראש מחול לצדיקים לע\"ל</b>: ראה ירושלמי מוע\"ק פ\"ג, ה\"ז. מגילה פ\"ב, ה\"ד. ויק\"ר פי\"א, ט. תענית לא, א. לקו\"ת ואתחנן ז, סע\"ב. לקו\"ש ט\"ו באב כרך כד ע' 66 ובהערה 76."],["258","257","<b>שכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב. ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 230."]]],[2000480098,"<h3>[לכל תכלה כו'] אך עדיין צ\"ל מאחר שבחי' חיוהי</h3>\n<b>פ' שופטים</b>\nיא) <b>אך</b> עדיין צ\"ל מאחר שבחי' חיוהי<sup data-n=\"259\">258</sup> הוא רק לגלות העלם העצמי לגבי עצמו שהוא מה שבידיעת עצמותו יודע את התורה<sup data-n=\"260\">259</sup>, א\"כ לאיזה צורך נאצל זה, הלא גם קודם שנאצל בחי' זו הי' בכח הא\"ס, ומה נתחדש באצילותה כו', ויש לפרש זה שקודם שנאצל בחי' זו אינה שייך כלל גם בחי' חכמת התורה שגם מה שבידיעת עצמותו יודע את התורה מוכרח לומר שיש בחי' מציאת שם חכמה שממוצא דבר נשמע שקודם שנאצלה בחי' זו אינה שייך כלל לאמר חכ' התורה לכן הגם שעדיין א\"ז גילוי לזולתו כלל עכ\"ז יש בחי' מציאות החכ' עד שנוכל לומר שעכ\"פ בידיעת עצמותו יודע בחי' התורה כו'.\n<b>ועוי\"ל</b> דהנה כ\"ז הוא בכדי שיוכל להיות אח\"כ מציאת ההשתלשלו' דע\"ס באצי' שא\"א כ\"א כאשר מתחלה נמצא מציאות שם חכ' שעדיין אינה שייך כלל לגילוי הזולת, אמנם בשם זה נמצא אח\"כ מציאות חכ' שגם זולתו יוכל להבינה לכן כאשר נאצל ממנו ית' להיות מציאות שם חכ' שאינה חכ' ידיעא<sup data-n=\"261\">260</sup> כלל, כ\"א מה שבידיעת עצמותו יודע את התורה, לכן אח\"כ נתהוה בחי' חכ' דאצי' שהוא ענין בחי' חכ' התורה כמו שהיא למעלה עדיין קודם בואה בבחי' התגלות למטה, וכנודע שעצם בחי' החכ' אינה עדיין בשביל זולת שהרי יכול לישב בעצמו ולהשכיל השכלות, אמנם השכלה זו היא מורגשת שגם זולתו יוכל להבינה, כ\"א שאינו מוכרח שישפיע אותה לזולתו כמו המדות עד\"מ שבהעדר ההשפעה מתבטל המדה<sup data-n=\"262\">261</sup>, וכשבא הזמן משני אלפי' תורה<sup data-n=\"263\">262</sup> התחיל לבוא לידי גילוי בחי' אור ושפע דחכ' זו",[["259","258","<b>אך עדיין צ\"ל מאחר שבחי' חיוהי</b>: מכאן מתחיל מאמר הד' מהמשך יונתי (הכולל פרקים יא-יב).\nכנראה שפרק זה נזכר בסה\"מ תרמ\"ג ע' פב. תרע\"ח ע' רעא. עטר\"ת ע' תמ.\nפי\"ב נזכר בסה\"מ מלוקט ב' ע' קכה.\nבבוך זה בסיום המאמר, הנה בשולי היריעה נרשמו ראשי פרקים ממאמר שנאמר מוצאי ר\"ה וש\"ש משנת תרמ\"א, שנדפסו לקמן. ונדפסו כאן בסיום המאמר בשולי היריעה (ע' תקיג). המשך הראשי פרקים ממאמר מוצאי ר\"ה הנ\"ל — ראה לקמן הערה 301.\nממאמר זה, שהפתיחה היתה: לכל תכלה ראיתי קץ, ישנם שני הנחות והם: א) הנחת<sup data-n=\"e60\">*</sup> כ\"ק אדמו\"ר מהורש\"ב (שנדפסה לקמן בחלק הנחותיו). ב) הנחה אחרת (והיא נדפסה לקמן בחלק ההנחות)."],["260","259","<b>שבידיעת עצמותו יודע את התורה</b>: ראה לעיל פ\"י על יד הערה 239 ואילך."],["261","260","<b>שאינה חכ' ידיעא</b>: נסמן בסמוך הערה 267."],["262","261","<b>החכ'. . ולהשכיל השכלות. . מתבטל המדה</b>: ראה גם אוצרות חיים בתחלתו. הובא בלקו\"ת מסעי צג, רע\"א. פרדס שער מהות והנהגה ש\"ח, פט\"ו. פלח הרמון שם פ\"ו<sup data-n=\"e61\">א</sup>. אוה\"ת שה\"ש כרך ב ע' תקנ וע' תקנה. סה\"מ תרכ\"ח ע' ד ואילך. המשך וככה תרל\"ז פכ\"ח. סה\"מ תרכ\"ו ע' רכג. תרכ\"ט ע' ט. תר\"ל ע' רסז. תרל\"ג ח\"ב ע' תקמא<sup data-n=\"e62\">ב</sup> (ובהנסמן בריש המאמר שם). תרל\"ד ס\"ע נד ואילך. לקמן בשני ההנחות כאן. סה\"מ תרע\"ח ע' רעו."],["263","262","<b>משני אלפי' תורה</b>: ע\"ז ט, א."],["e60","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>א</b>  ולכאורה כצ\"ל בסה\"מ תרע\"ח שבפנים ההערה.\n\n<b>ב</b>  נדפס גם לקמן מאמר ד\"ה ושאבתם מים פ\"א ובהערה 34."]]],[2000480099,"עד שבא לידי גילוי לבי\"ע, ומשה עלה למרום<sup data-n=\"264\">263</sup> והוריד עוז למטה, וכדכתי' וירד ה' על ה\"ס<sup data-n=\"265\">264</sup> כו', ואם<sup data-n=\"266\">265</sup> לא הי' תחלה בחי' מציאות שם חכ' דחכים<sup data-n=\"267\">266</sup> ולא בחכ' ידיעא<sup data-n=\"268\">267</sup> לא הי' נאצל בחי' חכ' ידיעא כו', ולפ\"ז מה שבידיעת עצמותו יודע את התורה ה\"ז כעין בחי' הממוצע &lt;16&gt;\nּ בין אוא\"ס הפשוט שאינו שייך לומר בחי' חכ' דחכים ולא בחכ' ידיעא, ובין בחי' חכ' ידיעא שבאצי' כו', ועם היות כי באמת לא נתחדש מאומה במה שנאצל בחי' חכ' שבידיעת עצמותו יודע את התורה שהרי קודם אצילותה היתה כלולה באור המאור עצמו אמנם זהו כמו כל בחי' הזיו והאור שמאיר מעצם המאור רק שבמשל כאשר האור מאיר מהמאור ה\"ה מורגש לאור, ובנמשל גם אחרי שנק' אור פרטי כמו חכ' כו' הוא ג\"כ לא בחכ' ידיעא כ\"א מה שבידיעת עצמותו הוא יודע את התורה כו', ויובן עוד בהקדם ביאור מה שאנו אומרים בידיעת עצמותו מהו, ואיך הוא קודם שלכאו' אינו שייך כלל, והיתכן שלא ידע את בחי' עצמותו כו', אך הענין הוא באמרו ידיעת עצמותו אינו דבר נוסף כלל ולא דבר שהיא לצורך זולתו דוקא, וכמו האדם שמטמין א\"ע מזולתו להתראות טיב שכלו והשפעותו בהשכלת התו' או כ\"ד שיש אצלו שהוא נעלם מעין זולתו כמו מי שמצא אוצר מופלג שמסתיר מבנ\"א, אמנם הוא בעצמו יודע מזה, אך הנה ידיעה זו ה\"ה ידיעה גמורה שהחכ' עד\"מ היא חכ' ידיעא שיכולה להיות נגלה לפני זולתו אלא שמעציר כח גילויה מטעם הכמוס אשר אתו שזהו ג\"כ חכ' ידיעא כו' שזהו מפני שמה שהוא יודע בעצמו בחי' חכ' זו זהו מה שכבר בא לידי השגה גמורה, והרי הוא מוגבל לכן השגתו מוגבלת ולכן גם זולתו יוכל להבינה כו', אמנם הנה אנו רואים שיש ענין מופלא שהחכם משיג שיש בדבר זה איזה כוונה, אבל הנה גם הוא עצמו אינו יודע עדיין איכות ומהות הכוונה כלל אלא שמשער בעצמו שיש דבר מה בזה וכאלו יודע מהו ובאמת אינו יודע עדיין כלל וכלל מהו, מ\"מ מי שאינו חכם ונבון דבר ה\"ה מופלא לגמרי ממנו, ומי שהוא בר שכל גדול וחכם גדול ה\"ה יודע שיש בזה שכל עמוק וא\"י יודע עדיין מהו, ומ\"מ בלתי ספק אצלו שיש בזה שכל וטעם עמוק וכאלו רואה ממש, או ע\"ד שארז\"ל איזהו חכם הרואה<sup data-n=\"269\">268</sup> כו' שענין הראי' אינו דבר שהוא בפועל אלא שרואה שכן יהי' לאחר זמן כו', ומ\"מ הנה זהו דבר המורגש לעין השכל כהרגש ההבנה, ולכן הרואה בעין השכל נק' בשם חכם שהוא חכ' ידיעא, אמנם בדבר שעדיין לא עיין בחכמתו כלל שהוא גם קודם שראה בעין השכל, ועכ\"ז אנו מחזיקים אותו לחכם מפני שכבר נסו אותו בכמה פעמים ורואים אנו שרואה בעין השכל הנולד לאחר זמן עד שנתחזק לחכם כו', וא\"כ הדבר שלא בא עדיין להשכיל עדיין אינו שייך לקרותו חכם ע\"ז, ועכ\"ז קוראין אותו חכם שמפני ידיעת עצמותו יודעי' אנו שידע, אמנם הנה כ\"ז הוא בזולת שאנו &lt;17&gt;\nּ מחזיקים אותו לחכם",[["264","263","<b>ומשה עלה למרום</b>: ע\"פ נוסח התקבצו מלאכים (שמח\"ת אחר קריאת התורה)."],["265","264","<b>וירד ה' על ה\"ס</b>: יתרו יט, כ."],["266","265","<b>ואם</b>: בהכת\"י אינו ברור כ\"כ. בהמשך יונתי הנדפס: וא\"כ. ולכאו' צ\"ל: ואם."],["267","266","<b>דחכים</b>: ניתוסף בפנים ע\"פ המשך הנדפס. ואולי נשתרבב לכאן מבסמוך שו\"ה דחכים."],["268","267","<b>דחכים ולא בחכ' ידיעא</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה יז, ב."],["269","268","<b>איזהו חכם הרואה</b>: תמיד לב, א. ראה גם סה\"מ תרמ\"ג ע' פב."]]],[2000480100,"מפני שבודאי יראה את הנולד, כן נבין בחכם עצמו מה שהוא רואה שיש כוונה עמוקה בדבר זה זהו מפני שיודע עצמותו היינו עצם כח חכמתו לכן כאלו רואה הוא כו' הגם שעדיין לא נכנס להיות חכ' ידיעא גם אצלו כו', רק שכל חכ' הוא מוגבלת שבזה א\"א להדמות המשל לנמשל, אבל זה נוכל להבין בטוב שענין ידיעת עצמותו אינה דבר נוסף כלל שהרי בלתי זה הוא אינו נכנס כלל באיזה מציאות כו', ובידיעה זו שיודע את עצמות כח שכלו יודע שיש בדבר ההוא שכל עמוק מאד מאד ולא בא עדיין בהשגת עין השכל, ועד\"ז נבין במה שאמרו שבידיעת עצמותו יודע את התורה, הנה קודם ששייך לומר בחי' הידיעה בעצמותו היינו קודם בחי' אצילות שם ידיעה ודעת אינו שייך לומר ג\"כ שיודע חכ' התורה שהרי כשם שאינו שייך שם ידיעה כן אינו שייך שם חכ' כו', ולפ\"ז קריאת שם זה הוא הגבלה, אמנם במה שא\"א ידיעת עצמותו הנה עם היות שז\"ע תוארים כפי המצוייר אצלינו אחרי ההגבלה כו' מ\"מ כשאומרים ידיעת עצמותו באוא\"ס שעצמותו אינו מושג כלל וכלל גם אחרי שנאצל הע\"ס ג\"כ שהרי זהו מהארה בעלמא, וכמו התפשטות האור ממאור השמש כו' כמ\"ש במ\"א באריכות כו', א\"כ ידיעת עצמותו שבידיעת עצמו יודע זהו רק תוארי' כמו שמצוייר אצלינו אח\"כ שכ\"ז הוא רק לשבר את האוזן<sup data-n=\"270\">269</sup> במה שהיא יכולה לשמוע, אמנם באמת מושלל הוא לגמרי מגדר בחי' הידיעה שאצלינו שהיא מופעלת ומורגשת כו', ועד\"ז מה שיודע את התורה הוא ג\"כ מושלל לגמרי מגדר וערך ידיעה המורגשת אח\"כ אצלינו מאחר שהיא בידיעת עצמותו כו', אלא שכ\"ז הוא לשבר את האוזן כו'.\n<b></b>קיצור. מאחר שחיוהי הוא לגלות העלם העצמי לגבי עצמו לאיזה צורך נאצל בחי' זו, וי\"ל שזהו בשביל שיהי' שייך לומר בחי' חכ' התו', הב' בכדי שיהי' נאצל אח\"כ מציאות חכ' ידיעא, ואומרו בידיעת עצמותו שולל ענין הידיעה לגמרי מגדר ידיעה מופעלת ומורגשת שזהו רק לשבר את האוזן כו'.\nיב) <b>ועדיין</b> צ\"ל האיך ע\"י ירידת הנשמה בגוף יבא האדם לאשתאבא בגופא דמלכא שז\"ע בחי' חיוהי ע\"י העבודה בתומ\"צ, אשר לכאו' אינו מובן כלל הלא כל התומ\"צ נתלבשו בדברים המצומצמי' דוקא כמו שכל המצות עד\"מ סוכה צ\"ל ז' טפחים ומשהו<sup data-n=\"271\">270</sup>, והגבוה מעשרים אמה פסולה<sup data-n=\"272\">271</sup>, וכן ד' מינים",[["270","269","<b>לשבר את האוזן</b>: ילקוט שמעוני האזינו לב, ב (בסופו — רמז תתקמב) בשם ברייתא דל\"ב מדות<sup data-n=\"e63\">ג</sup>. רש\"י בשלח יג, יח<sup data-n=\"e64\">ד</sup>. יתרו יט, יח (ג\"פ). יט. תשא לא, יז. ישעי' סג, א<sup data-n=\"e65\">ה</sup>. מכות יב, א ד\"ה חמוץ בגדים. לק\"ט יתרו יט, טז. יח. תו\"א מג\"א צג, ב."],["271","270","<b>סוכה צ\"ל ז' טפחים ומשהו</b>: באגה\"ק ס\"י: ז\"ט. אבל כ\"ה בכ\"מ ומהם (בשתי ההנחות כאן). לקמן מאמר ד\"ה עשה צדקה ומשפט ובהערה 130. (ובהנחה שם על יד הערה 102). ד\"ה עטרת תפארת שיבה על יד הערה 46. (ובהנחה שם על יד הערה 42־ בין הערות 122-123). ראה סה\"מ תרל\"ב ח\"א ע' פד ובהערה שם. ובהנחה שם ע' רמו: לא פחות משבעה טפחים ומחצה."],["272","271","<b>והגבוה מעשרים אמה פסולה</b>: משנה סוכה ב, א.\n\n<b>ג</b>  אבל לפנינו: להשמיע האוזן כדרך שהיא שומעת.\n\n<b>ד</b>  והוא הגהת ר\"י קרא — ראה תוספות השלם שם אות ח.\n\n<b>ה</b>  בכמה דפוסים ליתא."]]],[2000480101,"שבלולב יש לכאו\"א שיעורים שפחות מהשיעור הם פסולים<sup data-n=\"273\">272</sup>, וכן בכל מצותי' של תורה, תפילין ד' בתים, ציצית ד' חוטין כפולים לח' ובד' כנפות דוקא, ומעשר חלק עשירי<sup data-n=\"274\">273</sup> דוקא וכן כל המצות כו', אך הענין הוא דכתי' לכל תכלה ראיתי קץ רחבה מצותך מאד<sup data-n=\"275\">274</sup>, פי' לכל תכלה הוא בחי' כליות הנפש בג\"ע ראיתי שיש קץ לדבר שבחי' ג\"ע שבכל עולם ועולם הנה הוא &lt;18&gt;\nּ מוגבל לפי ערך העולם וא\"כ יש לו קץ ושיעור, וכנודע שג\"ע הוא בחי' ג\"ר<sup data-n=\"276\">275</sup> שמעולם ההוא, שבחי' ז\"ת הוא מה ששייך לעולמות, וכמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"277\">276</sup>, זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"278\">277</sup>, אבל בחי' ג\"ר הוא אינו שייך לעולמות דהיינו לזולתו וכנ\"ל, והוא בחי' ג\"ע שבכל עולם, וכמ\"ש מזה במ\"א בד\"ה ביום השמע\"צ<sup data-n=\"279\">278</sup>, ובד\"ה ענין פרה אדומה<sup data-n=\"280\">279</sup>, ועכ\"ז עם היותו ג\"ר מ\"מ יש לו קץ שהרי הוא מוחין מבחי' מדות אלו, אבל רחבה מצותך מאד שהמצות הם כלים רחבים לקבל בחי' מאד להתלבש בהם בחי' הארת אוא\"ס ב\"ה אשר יאיר לע\"ל בבחי' בלי גבול ותכלית בחסד חנם כו', וזהו לשון מאד בלי גבול ותכלית כמ\"ש באגה\"ק סי' י\"ז<sup data-n=\"281\">280</sup>, ונמצא כי המצות הם<sup data-n=\"282\">281</sup> כלים רחבים לקבל מבחי' מאד העליון ועמ\"ש מזה בד\"ה את ה' האמרת<sup data-n=\"283\">282</sup>, ופי' מאד העליון דהנה ג' בחי' אהבה דכתי' בפ' ואהבת<sup data-n=\"284\">283</sup> אשר בכל מאדך הוא בחי' היותר גבוה ונעלה שהוא למעלה מהגבלת כלי הלב דבכל לבבך ולמעלה מהגבלת כחות הנפש המלובשים בגוף שז\"ע בכל נפשך, כ\"א בכל מאדך ענין מאד הוא בלי גבול לצאת מנרתק הגוף המגביל כ\"א בבחי' כלה שארי ולבבי<sup data-n=\"285\">284</sup> כו', שבאמת היא אה\"ר וגדולה מאד, אך עכ\"ז באמת הנה היא ג\"כ מוגבלת שהרי הוא רק למעלה מהגבלת האדם שהוא מוגבל בעולם הזה הגשמי, אבל בערך הא\"ס היא ג\"כ מוגבלת, וז\"ע אומרו מאדך שאצלך זהו מאד<sup data-n=\"286\">285</sup>, אבל לא שבאמת לאמיתו הנה היא מאד, רק שמחסד ה' אלינו אינו מבקש כ\"א לפי כחינו וכמארז\"ל במד\"ר כשהוא מבקש אינו מבקש אלא",[["273","272","<b>ד' מינים. . שפחות מהשיעור הם פסולים</b>: ראה שו\"ע אדה\"ז הל' לולב סתרמ\"ח, סכ\"ט. סתרמ\"ט, סכ\"ג. סתר\"נ, ס\"א."],["274","273","<b>תפילין. . ציצית. . ומעשר חלק עשירי</b>: ראה גם לקמן מאמר ד\"ה עשה צדקה ומשפט קרוב לסופו. וש\"נ."],["275","274","<b>לכל תכלה ראיתי קץ רחבה מצותך מאד</b>: תהלים קיט, צו. ראה אגה\"ק סי\"ז."],["276","275","<b>שג\"ע. . ג\"ר</b>: ראה (בנוסף להמצויין בסמוך בפנים) ביאוה\"ז אחרי עה, א. ולהצ\"צ שם כרך א ע' שנג ואילך. אוה\"ת בראשית כרך ג ס\"ע 1058 ואילך. סה\"מ תרל\"ב ח\"א ע' קפז. וש\"נ. וראה ג\"כ לקמן ספט\"ו."],["277","276","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לקמן מאמר ד\"ה ושאבתם מים פ\"א ובהערה 22."],["278","277","<b>זכור רחמיך. . המה</b>: תהלים כה, ו [בדילוג השם]."],["279","278","<b>בד\"ה ביום השמע\"צ</b>: כ\"ה גם בהמשך יונתי הנדפס."],["280","279","<b>ובד\"ה ענין פרה אדומה</b>: ראה אוה\"ת חוקת ע' תשפד (וראה גם במהדורת תשנ\"ח)."],["281","280","<b>מאד בלי גבול. . באגה\"ק סי' י\"ז</b>: ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 99."],["282","281","<b>הם</b>: בהמשך יונתי הנדפס: מהם. וכנשצ\"ל כבפנים."],["283","282","<b>בד\"ה את ה' האמרת</b>: ראה סה\"מ תרל\"ב ח\"ב ע' תפב. תרל\"ט (נמצא בדפוס)."],["284","283","<b>בפ' ואהבת</b>: ואתחנן ו, ה. ראה גם לקמן פי\"ג ופי\"ד."],["285","284","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["286","285","<b>מאדך שאצלך זהו מאד</b>: ראה לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך ובהערה 30."]]],[2000480102,"לפי כחן<sup data-n=\"287\">286</sup>, אבל בחי' מאד העליון הוא בלי גבול ממש, שהוא באמת לאמיתו בלי גבול ותכלית, וזהו בחי' אוא\"ס שיאיר לע\"ל שהוא בל\"ג ממש, והמצות הם כלים רחבים לקבל בחי' מאד העליון שהוא בל\"ג ממש, אמנם עדיין צ\"ל האיך המצות שהם ירדו להתלבש בכלים מוגבלים להיות כך ולא כך שהוא מוגבל בערך עשייה הגשמיות שלנו כו' יהיו כלים לקבל בחי' מאד העליון שהם רחוקים יותר משני קצוות ששניהם מוגבלים, והגבול אינם מניחם להתקרב מפני שזה מזרח וזה מערב, אבל גבול ובלי גבול הוא אינו בערך כלל<sup data-n=\"288\">287</sup> וכלל, והאיך יתאחדו כא' מה שאינו בערך כלל, ואם ביכולתם להתאחד יפלא למה ה\"צ להיות הצמצום הלא הי' יכול להיות מבלתי בע\"ג בחי' הגבול גם בלא הצמצום ומק\"פ<sup data-n=\"289\">288</sup> כו'.\n<b>אך</b> הענין הוא דשרש ענין מה שירדו המצות להתלבש בגבול ומדה זהו כמו שכל מברר בהכרח שירד במקום המתברר כו', שאל\"כ א\"א לו לברר ומוכרח הוא להתלבש בלבושי המתברר<sup data-n=\"290\">289</sup>, וז\"ע ירידת הנשמה ממקום כבודה לבוא בגוף הגס והשפל ונבזה<sup data-n=\"291\">290</sup> ובחומר גסות הנה\"ב בכדי שיוכל לבררם כו', ועד\"ז נתלבשו המצות בדברים הגשמי' המקבלים חיותם מנוגה והם מוגבלי' מאד, וגשמיים, רק ששרש שרשם הוא ממה שנפל מעולם התהו שקדם לתיקון במעלה שהיו אורות מרובים<sup data-n=\"292\">291</sup>, ולא הריבוי לבד אלא שהי' בא\"א ממש וכנ\"ל<sup data-n=\"293\">292</sup>, וע\"י שעושים מזה מצוה שנעשה כלי לרצון העליון שעם היות הרצון הוא &lt;19&gt;\nּ שמוגבל להיות רצון פרטי עכ\"ז הנה עי\"ז נעשה נח\"ר לבעל הרצון כמארז\"ל נח\"ר לפני שאמרתי ונעשה רצוני<sup data-n=\"294\">293</sup>, ונמצא כי גם כמו שהם למטה הרי יש בהם מבעל הרצון שהוא מושלל לגמרי מערך בחי' ההגבלה, וכמו שהיו התומ\"צ קודם בריאת העולם אלפי' שנה שבידיעת עצמותו יודע את התורה שנת\"ל שמושלל מגדר הגבלה, ולכן בגמר הבירורים דתהו יזכך העולם עד שהמצות שלנו דעכשיו ודימוהמ\"ש שיהי' כמצות רצונך כמ\"ש ושם נעשה לפניך כמצות רצונך<sup data-n=\"295\">294</sup> יהיו כלים רחבים לקבל בחי' מאד העליון דהיינו בחי' אורות דתהו שהם בחי' מאד לגבי בחי' כלים דתיקון שהם מוגבלים לקבל בחי'<sup data-n=\"e3\">*</sup>",[["287","286","<b>כשהוא מבקש. . כחן</b>: ראה במדב\"ר פכ\"א, כא. לקו\"ש ר\"ה כרך ט ע' 452 בהערה."],["288","287","<b>גבול ובלי גבול הוא אינו בערך כלל</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה אחת הערה 111."],["289","288","<b>ואם. . הצמצום ומק\"פ</b>: ראה ע\"ח דרוש עגוי\"ש ש\"א, ענף ב."],["290","289","<b>שכל מברר. . בלבושי המתברר</b>: ראה ביאוה\"ז ויגש כו, ד. אמור קמב, ב. שע\"ת נ, ד. מאמרי אדה\"א ויקרא ח\"א ע' קמג. וש\"נ. סה\"מ תרלב ח\"א ע' צד. וש\"נ."],["291","290","<b>והשפל ונבזה</b>: בהמשך הנדפס: השפל והנבזה."],["292","291","<b>התהו. . אורות מרובים</b>: ראה גם לקמן מאמר ד\"ה ביום השמיני עצרת ובהערה 52."],["293","292","<b>שהי' בא\"א ממש וכנ\"ל</b>: ספ\"ז. וש\"נ."],["294","293","<b>נח\"ר. . ונעשה רצוני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["295","294","<b>ושם נעשה לפניך כמצות רצונך</b>: מוסף ליו\"ט [בדילוג]. ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת הב' ובהערה 9."],["e3","*","בשולי היריעה נרשם (ובהמשך הנדפס ליתא):\nאיך כלי יקבל, בירור התהו, א\"כ זהו מאד דתיקון, אך באמת ע\"ד עקודים."]]],[2000480103,"אורות מועטי' דתיקון כו', א\"כ לפ\"ז צ\"ל שזהו מאד דתיקון לבד, אמנם באמת אינו כן שבחי' מאד העליון כולל גם בחי' מאד בערך התהו ג\"כ, דהנה ע\"י בחי' בירור התהו יתגלה בחי' הארת אוא\"ס שלמעלה מתהו ותיקון ששניהם הם עולמות, וע\"ד בחי' עקודים שעקוד בכלי אחד<sup data-n=\"296\">295</sup> שלמעלה מנקודי' וברודים שהם תהו ותיקון<sup data-n=\"297\">296</sup> כו', וז\"ע מה שנמשלו המצות בנר כמ\"ש כי נר מצוה, והיינו כי הנר בו נאחז האור להאיר, עד שהנר הוא אור, ולועזים אותו בל\"א<sup data-n=\"298\">297</sup> ליכט ע\"ש האור כי כל מהותה הוא האור כו', והנה האור עם היות שהוא עצמו מוגבל נברא ומחודש כמו המים וכל שארי נבראים, עכ\"ז אנו רואים שבכל הדברים כשנוטלים מהם הם מתמעטים כמו המים כשישתו מהם עם רב יתמעטו הרבה, וכן בכל הדברים כשמשתמשי' מהם מתמעטים, משא\"כ האור כשידלקו עד\"מ אלף אלפי' נרות מנר א' לא תתמעט מזה כלום וא\"כ עם היות שעצם האור הוא נברא מוגבל עכ\"ז נראה בו גם כח הא\"ס במה שאינו נחסר מאומה מריבוי הדלקת נרות שמדליקים ממנו כו', ולכן נמשל הקב\"ה באש כמ\"ש כי ה' אלקיך אש אוכלה הוא<sup data-n=\"299\">298</sup> להיות כי באש נראה גם כח הא\"ס, גם אנו רואים באש שמצד עצמו אין לו כליון כלל והוא מצ\"ע הי' דולק זמן בלתי מוגבל רק כשכלה השמן או החלב והפתילה מסתלק האור שזהו מצד שאין לו במה לאחוז, ולא שעצם האור כלה שהרי כשמוסיפים שמן דולק עוד, כי האור מצ\"ע אינו מקבל שינויים כלל וכלל ומצ\"ע הנה הוא שוה ממש בעת שמדליקי' ובעת שמכבין ואינו מתיישן כלל, שכ\"ז מורה על בחי' לא שניתי כו' ולכן נמשל בו הקב\"ה, משא\"כ המים מצ\"ע פועל בהם חום האויר שהוא הולך וחסר עד אשר יתייבש לגמרי גם כשיעמוד בכלי אשר אינו בולע מים כו', ומטעם זה עצמו נמשלו המצות בנר להיות כי יש בכח בחי' המצות לקבל בחי' מאד העליון שהוא בל\"ג באמת לאמיתו כו', ועם היות שירדה להיות רצון פרטי דמצוה זו עד\"מ, מ\"מ ה\"ה מעורר בעל הרצון, וגם כי ע\"י בירור דתהו עי\"ז נמשך &lt;20&gt;\nּ מאוא\"ס שלמעלה מתהו ותיקון הבלתי מוגבל כו', וה\"ז כמו הנשמה שהיא הנה\"א שהיא נק' ג\"כ נר כמ\"ש נר ה' נשמת אדם וכנ\"ל<sup data-n=\"300\">299</sup>, וירדה ממקום כבודה בשביל בירור נה\"ב ע\"י מעהמ\"צ בכדי לבוא לאשתאבא בגופא דמלכא בחי' איהו המתייחד עם חיוהי כו' וכנ\"ל<sup data-n=\"301\">300</sup>.\n<b></b>קיצור. האיך ע\"י ירידת הנשמה תבוא לאשתאבא כו' הלא המצות הם מוגבלי', אך לכל תכלה ראיתי קץ, אבל רחבה מצותך לקבל בחי' מאד העליון שהיא בל\"ג ממש, ולכן נמשלה לנר הוא האור שאינו נכלה כלל כו'.",[["296","295","<b>עקודים שעקוד בכלי אחד</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. תו\"א נח י, ג ואילך. תו\"ח וארא ח\"א נב, ד. וש\"נ. סה\"מ תרנ\"ב ע' ק ואילך. תרל\"ח ס\"ע עה ואילך ובהערה 274."],["297","296","<b>מנקודי' וברודים שהם תהו ותיקון</b>: ראה לקו\"ת אמור לד, ג. בהעלותך לא, ג."],["298","297","<b>בל\"א</b>: בלשון אידיש. ראה שיחת ליל הושע\"ר תשנ\"ב אות ג (שיחות קודש ע' 165 ואילך). ליל שמח\"ת קודם הקפות תשנ\"ב — סה\"ש תשנ\"ב ח\"א ע' 38 בשולי הגליון להערה 20. לקו\"ש משפטים כרך כא ע' 448 הערה 15."],["299","298","<b>כי ה' אלקיך אש אוכלה הוא</b>: ואתחנן ד, כד."],["300","299","<b>וכנ\"ל</b>: פ\"ו ואילך."],["301","300","<b>וכנ\"ל</b>: פ\"י."]]],[2000480104,"בשולי היריעה נרשמו ראשי פרקים מדרושי מוצאי ר\"ה וש\"ש שנדפסו לקמן (ובהמשך הנדפס ליתא):\n<b>ר\"ה</b> תשו' ע\"ד בידך אפקיד רוחי<sup data-n=\"e4\">א</sup>, שהשבת הפקדון צ\"ל נקי, וז\"ע הוידוי בק\"ש שעה\"מ, כן החזרת חיות שנה העברה צ\"ל נקי וז\"ע תשובה להשיב חיות שנה העברה, בתשו\"ש שעי\"ז יומשך חיות חדש, כמו בכ\"י שנעשה ברי' חדשה<sup data-n=\"e5\">ב</sup>, וז\"ע ברכות השחר, ובכלליות הוסיפו ט' ברכות<sup data-n=\"e6\">ג</sup>, ולכאו' הצ\"ל זכרונות<sup data-n=\"e7\">ד</sup>, אלא שע\"י המלוכה בא הזכרון<sup data-n=\"e8\">ה</sup>, ובמה בשופר צעקה<sup data-n=\"e9\">ו</sup> פנימיות, אדם ובהמה כבהמה דוקא רק שזהו למעלה מן הטו\"ד ערום בדעת<sup data-n=\"e10\">ז</sup>, שכנתי ערמה<sup data-n=\"e11\">ח</sup>, ערום ביראה<sup data-n=\"e12\">ט</sup>, ימים נוראים מקור היראה<sup data-n=\"e13\">י</sup> כענין ערום כו' שח\"ס מקור ח\"ע.",[["e4","א","בידך אפקיד רוחי: תהלים לא, ו.\n\n<b>ב</b>  בכ\"י שנעשה ברי' חדשה: ראה לקמן הערה 593.\n\n<b>ג</b>  ט' ברכות: ראה לקמן ובהערה 605.\n\n<b>ד</b>  הצ\"ל זכרונות: ראה לקמן על יד הערה 616 ואילך.\n\n<b>ה</b>  הזכרון: המשך הראשי פרקים למאמר זה — ראה במאמר שנדפס לאח\"ז קרוב לתחילתו בשולי היריעה — הערה א.\n\n<b>ו</b>  ובמה בשופר צעקה: ראה לקמן מאמר ד\"ה שובה ישראל בפנים בין הערות 22-23.\n\n<b>ז</b>  ערום בדעת: ראה שם הערה 35.\n\n<b>ח</b>  שכנתי ערמה: משלי ח, יב.\n\n<b>ט</b>  ערום ביראה: ברכות יז, א.\n\n<b>י</b>  ימים נוראים מקור היראה: ראה גם המשך מים רבים תרל\"ו פ\"נ. ח\"ב ע' של. ע' שמז."]]],[2000480105,"<h3>[אני לדודי] והנה כל מה שנת\"ל בענין עליית נה\"א</h3>\n<b>פ' תצא</b>\nיג) <b>והנה</b><sup data-n=\"302\">301</sup> כל מה שנת\"ל<sup data-n=\"303\">302</sup> בענין עליית נה\"א ע\"י ירידתו בגוף זהו הכל ע\"י בירור נה\"ב והגוף עצמו ששרשם מתהו כנ\"ל<sup data-n=\"304\">303</sup>, ואמנם באמת גם הנה\"א מצ\"ע מתעלה<sup data-n=\"305\">304</sup> ג\"כ ע\"י ירידתו להתלבש בגוף ונה\"ב. דהנה אנו רואים",[["302","301","<b>והנה כל מה שנת\"ל בענין עליית נה\"א</b>: מכאן מתחיל מאמר הה' מהמשך יונתי (הכולל פרקים יג-טו).\nכנראה שלמאמר זה (פי\"ג) נתכוון בסה\"מ תרס\"ט ס\"ע קמ [ושם: וכמשל אמת המים. . ומוליך גם הסתימה עמו וכמ\"ש מזה בדרוש גן נעול (מצה זו) תר\"מ].\nאולי למאמר זה נתכווין (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה ד\"ה ויאמר כו' לך לך על יד הערה 30 (ושם: פ' נצבים).\nפט\"ו נזכר בסה\"מ תרנ\"א ע' עג.\nממאמר זה נדפסו לקמן במקומם עוד שני הנחות [שבהם הפתיחה היא: אני לדודי], והם: הנחת<sup data-n=\"e66\">*</sup> כ\"ק אדמו\"ר מהורש\"ב. ב) הנחה אחרת.\nבבוך זה נרשם מלמטלמ\"ע בצד השמאלי של העמוד ראשי פרקים ממאמר שנאמר מוצאי ר\"ה תרמ\"א שנדפס לקמן. ונדפס כאן בשולי היריעה. התחלת הראשי פרקים ממאמר הנ\"ל — ראה גם לעיל הערה 258."],["303","302","<b>שנת\"ל</b>: פ\"ח ואילך."],["304","303","<b>כנ\"ל</b>: על יד הערה 165."],["305","304","<b>הנה\"א מצד עצמו מתעלה</b>: ראה לקו\"ת בלק עג, סע\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תשמה. לקמן בשני ההנחות כאן. לקו\"ש ויצא כרך טו ע' 248 ואילך (ובהנסמן שם). תבא כרך יט ע' 240 הערה 39. מוצ\"ש נח כרך כ ע' 284 הערה 30. וראה גם תו\"א טז, רע\"ג מע\"ח של\"ט ובהגהות הצ\"צ שם קלט ד, ואילך."],["e66","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000480106,"במים ההולכים בנהר לאט לאט, כמו אמת המים העוברת ממקום למקום שהולכת בלאט, מפני שאין בה מים רבים כ\"כ, ואין נביעתם בריבוי כ\"כ שיתרבו המים אשר ע\"כ הולכת לאט, הנה כשסותמין מקום יציאתה באמצע הילוכה עד\"מ מתקבץ ריבוי מים באמת המים עד שמתגברים על מקום סתימתם והולכי' ברעש ובמהירות גדול ועצום, או שנובעי' מצד אחר וקורעי' את העפר המגבילם על הצדדי' והולכים להם וגם הילוכם יותר חזק, וכשאין בהם קיבוץ כ\"כ עד שיוכלו להתגבר על מקום סתימתם הנה הם עולים ומתפשטי' על גדותי' שזהו הוראה שיש ריבוי מים אמנם לא נתגברו כ\"כ עד שיקרעו או ידחו הסתימה כ\"א מפני שנתרבו אין להם גדדות<sup data-n=\"306\">*305</sup> להחזיקם לכן הם מתפשטי' על השדות שבסביבות האמת המים כו', וככל המשל הזה יובן בנה\"א שבאדם שהוא חלק הוי' ממש, וכמשנ\"ת לעיל בקצרה<sup data-n=\"307\">305</sup> ענין בחי' י\"ה ובחי' ו\"ה שיש בנפש ע\"ש. וכן יש ג\"כ בחי' קוש\"י כמשנ\"ת שזהו בחי' עם קשה עורף וסלחת כו', הנה כשהגוף ונה\"ב אינם מונעי' כ\"כ לרצון הנה\"א שנמשלה לאש כמ\"ש נר ה' נשמת אדם, שכמו שהנר עולה<sup data-n=\"e14\">*</sup>",[["306","*305","<b>גדדות</b>: כ\"ה בהכת\"י."],["307","305","<b>כמשנ\"ת לעיל בקצרה</b>: פ\"ה."],["e14","*","בשולי היריעה נרשמו ראשי פרקים ממאמר מוצאי ר\"ה שנדפס לקמן (ובהמשך הנדפס ליתא):\nיוםא זכרון תרועהב, וצ\"ל למה נק' יום הזכרון, הלא זכרון זהו רק בשבת, ועיקר הוא התרועה עצמה, אמרו לפני מ'ג זכרונות ובמה בשופר, נמצא פעולתו לזכרון, זכור לעבדיך אי\"וד, שצ\"ל האיך שייך שישכח ח\"ו על אי\"ו, אך מה הגפן הזהה חי ונשען על עצים מתים כו', ג' בחי' אהבה, אברהם בכל לבבך חו\"ג והחסד גובר, בכל נפשך אפי' נוטל יצחק עקידה, בכל מאדך יעקב ת\"תו נחלה בלי מצרי'ז, עולה כו' ומחבר חיו'ח א\"כ אין מצר, וכשיש ג' בחי' אלו א\"צ כ\"כ לזכות אבות, אבל כשפגמו, אזי נשען על עצים זכור לאי\"ו תמורת ג' אהבות, שעיקר העבודה אהוי\"ר לאהבה וליראה אותי את האלקי' יראט, ועי\"ז זה כל האדם שכ\"א יבוא לזה אסה\"מי, אך זהו ע\"י תשובה לשארית נחלתויא כו', ולכן נק' יום הזכרון שגם אם לא אכשיר דראיב מ\"מ כשזוכר אי\"ו סולח ומוחל כו', ולכן גם בחול נק' יום הזכרון.\nיום: המשך לשולי הגליון שבסוף המאמר שלפני זה הערה ה.\nיום זכרון תרועה: ראה לקמן פכ\"ד.\nאמרו לפני מ': ראה ר\"ה טז, סע\"א. לד, ב.\nזכור לעבדיך אי\"ו: ראה עקב ט, כז.\nמה הגפן הזה: ראה שמו\"ר רפכ\"ט.\nת\"ת. . עולה: ראה לעיל הערה 44.\nנחלה בלי מצרי': שבת קיח, סע\"א.\nחיו': אינו ברור כ\"כ. ואוצ\"ל: חו\"ג.\nאת האלקי' ירא: קהלת יב, יג.\nכ\"ה בהכת\"י.\nלשארית נחלתו: מיכה ז, יח.\nלא אכשיר דרי: ע\"פ יבמות לט, ב. חולין צג, ב."]]],[2000480107,"הלהב שלה תמיד למעלה, ובטבעה נמשכת אחר האבוקה, כן הנה\"א נא' רוח בני האדם העולה היא למעלה<sup data-n=\"308\">306</sup> ע\"י קיום התומ\"צ כנ\"ל, ונמשכת תמיד אחר האבוקה שז\"ע הבקשה משכני אחריך נרוצה<sup data-n=\"309\">307</sup> פי' שכנס\"י מבקשת שתאיר בחי' האבוקה שעי\"ז הוא בחי' משכני, ואז אחריך נרוצה כטבע הנר שנמשך אחרי האבוקה, ונרוצה לשון רבים<sup data-n=\"310\">308</sup> מפני שכאשר הנה\"ב אינו מונע ומעכב שזהו הוראה שאיננו גס כ\"כ עד שנמצא בו בחי' הכנעה למלאות רצון הנה\"א, א\"כ יש בו בחי' ביטול קצת עכ\"פ שנמצא גם הוא רץ ע\"י הנה\"א שנמשך אחר האבוקה, וכאשר עוסק בתומ\"צ בריבוי ובשקידה בכי\"ת ואינו נפרד מיחודו ואחדותו ית' אזי מתמלא יותר ויותר שענין בחי' זו י\"ל &lt;21&gt;\nּ במשל גם באמת המים שלא נסתם מקום יציאתה לגמרי, מ\"מ כשמתוסף מים רבים היא עולה ומתמלאת כ\"כ עד שיוצא מהגבלת גדרים היינו גדותיה כו' כמו בעת הפשרת שלגים וכדומה בריבוי גשמים כו', ובנמשל היינו שהגם שלא הסתיר הנה\"ב והגוף לגמרי עד שימנעו הנה\"א מעשיית המצות כו' וכן ג\"כ לא כבש את יצרו שלא לעסוק בצרכי תענוגי גופו ונה\"ב ברצונות ותענוגי' גשמיי' כו' שזהו כמשל אמת המים שהולכת בלתי סתימה כו', עכ\"ז מצד ריבוי הטוב שעושה ועוסק בתומ\"צ והגוף ונה\"ב אינם מסתירים, הנה ע\"י ריבוי הטוב עולה הנה\"א בעילוי אחר עילוי להיות רוח האדם עולה כ\"כ עד שיוצא חוץ מגדרי הגוף והנה\"ב עד שמתפשט ברוחב מאד כמו אמת המים שיוצא מגדותיה ומתפשטת בשדה עד\"מ, ובעבודה ז\"ע בכל נפשך היינו בכל כחות הנפש גם בכחות החיצוני' שאינם שייכים לאהבה עד\"מ שהרי הלב אוהב שעיקר האהבה היא בלב כמ\"ש ואהבת כו' בכל לבבך<sup data-n=\"311\">309</sup>, ומהו שמוסיף עוד בכל נפשך, אלא שזהו כמשל אמת המים המתגברת בריבוי מים עד שיוצא מגדותי' ומתפשטת לצדדי' גם במקום שתמיד אין שם הילוך המים כ\"א מחמת הריבוי כו', וכך מצד ריבוי האהבה שבלב מתפשט להיות בכל נפשך בכל כחות הנפש גם בכחות החיצוני' שירוץ ברגליו לדבר מצוה וכדומה בשארי הפרטי' בפרטי כחות האדם כמו שמחמת אהבתו וטרדתו בעשיית המצוה ולימוד התורה שוכח על מה שרוצה לאכול כו' וה\"ז כמשל הנ\"ל כו'.\n<b></b>קיצור. עליית נה\"א מצ\"ע יובן בהקדם המשל מאמת המים כו' וכשמתמלאת עד שמתפשט על גדותיה, זהו כמו בחי' בכל נפשך, ובעבודה ע\"י ריבוי אהבת הלב דבכל לבבך כו'<sup data-n=\"e15\">*</sup>.",[["308","306","<b>רוח בני האדם העולה היא למעלה</b>: קהלת ג, כא."],["309","307","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."],["310","308","<b>ונרוצה לשון רבים</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פס\"א. וש\"נ."],["311","309","<b>בכל נפשך. . ואהבת. . לבבך</b>: ואתחנן ו, ה."],["e15","*","שנרשם בשולי היריעה (ובהמשך הנדפס ליתא):\nונה\"א יודע מעלת התומ\"צ משרשן ברצה\"ע שהרי היא חלק ה' שיש בה ג\"כ מבחי' הרצון, קשה עורף לעמוד נגד מונע, וע' מע' מחוייב להפריז."]]],[2000480108,"יד) <b>ואמנם</b> כשהגוף ונה\"ב מעלימים ומסתירים, ואינם מניחים הנה\"א לעלות למעלה כטבעה למשוך אחר האבוקה כו', ואינו מניחה לבוא לבחי' האהבה לאלקות מפני ריבוי גסות נפשו הבהמית, וחומר הגוף הגס והחומרי כו' עד שמחמת ריבוי ההסתר הנ\"ל מתגברת הנה\"א בכח ועוז גדול עד שיצאת מנרתיקה הוא הגוף ונה\"ב ובוקעת מקום הסתימה כנ\"ל במשל, ואז מחמת תוקף הכח והעוז הנה היא באה לעלות במעלות בעילוי הרבה יותר מכמו ענין ההתפשטות שבעבודה זהו כענין בכל נפשך כו', אלא שבאה לבחי' אהבה בכל מאדך, פי' מאד הוא בלי גבול היינו למעלה מהגבלת כחות הגוף כ\"א להיות בבחי' ועמך לא חפצתי, כי מי לי בשמים ובארץ<sup data-n=\"312\">310</sup> געה\"ת והעליון, ועוה\"ב וכל הגילוי' בעולמות עליונים כו', שהרי ועמך לא חפצתי כלל, פי עמך אפי' בחי' מקור החיים והתענוגי' ג\"כ לא חפצתי מפני שהוא עמך לבד כמ\"ש כי עמך מקו\"ח<sup data-n=\"313\">311</sup> שגם בחי' מקור החיים הוא עמך בטל וטפל &lt;22&gt;\nּ לך, וא\"כ במה יחפוץ בטפל או בעיקר כו', ובחי' תגבורת אהבה זו זהו כמשל המים שבוקעים מקום הסתימה והולכים ברעש גדול ובכח חזק מאד כו' כנ\"ל במשל.\n<b>והנה</b> בחי' אהבה דבכל מאדך זו עם היות שבאה מחמת הגוף ונה\"ב שמפני שהם מסתירים עי\"ז בא הנה\"א לידי אה\"ר ונפלאה כזו כו' עכ\"ז א\"א להתייחס אה\"ר זו לנה\"ב והגוף כ\"א שהם הגורמי' לבד ולא עצם האהבה היא מהם, ולכן אהבה זו מתייחסת להנה\"א לבד אלא שבאה ע\"י ירידתה בגוף ונה\"ב אשר בלתי ירידתה זו א\"א לה לבוא לבחי' אה\"ר כזו, כמו המלאכים שאינם באים לעולם לידי אה\"ר כזו וכמ\"ש ויעמידם לעד לעולם, שלעד ולעולם הם עומדים בבחי' מדריגת אהבתם כמו שנוצרו ונבראו כו', שלכן נק' עומדים, משא\"כ נשמות נק' מהלכים, ע\"י ירידתם בגוף דוקא וכנ\"ל ע\"י הסתימה והמניעה כו', אבל בהיות הנשמה למעלה לא היתה באה לעולם לידי אהבה כזו שהרי אין שם מונע, ולכן גם הנשמות בהיותם למעלה נק' בשם בחי' עומדים כמ\"ש חי ה' אשר עמדתי לפניו כו' ואין יתרון לנשמות בהיותם למעלה על המלאכי' אלא במה שהמלאכים הם מבחי' חיצוני' הכלים והנשמות מפנימי' הכלים<sup data-n=\"314\">312</sup>, א\"כ נבראו ונוצרו בבחי' היותר גבוה ונעלה, ומ\"מ הנה הם עומדים כמו שנבראו ואינם מהלכי' מדרגא לדרגא כ\"א ע\"י ירידתה בגוף דוקא כו', וזהו העלי' שע\"י ירידתה שגם מצ\"ע מתעלית בעילוי רב ועצום מאד מבחי' גבול לבחי' בלי גבול כו', ולפי מה שנת\"ל זהו העלי' מבחי' גרמוהי לבחי' איהו וחיוהי<sup data-n=\"315\">313</sup> כו'.",[["312","310","<b>מי לי בשמים ובארץ</b>: תהלים עג, כה [בדילוג]. ראה גם לקמן פכ\"ב. וש\"נ. לעיל ח\"א הנחת כ\"ק אדמו\"ר מהורש\"ב (בחלק הנחותיו) הנחה ד\"ה גל נעול ובהערה 65."],["313","311","<b>כי עמך מקו\"ח</b>: תהלים לו, י. ראה לקו\"ת אמור לא, ד. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 50."],["314","312","<b>שהמלאכים. . חיצוני'. . מפנימי' הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 16."],["315","313","<b>שנת\"ל. . גרמוהי. . איהו וחיוהי</b>: פ\"י."]]],[2000480109,"<b>ועדיין</b> צ\"ל ולחקור דעם היות שזהו נחשב לעבודת ועליית הנה\"א מצ\"ע מ\"מ בודאי מתעלה עי\"ז הנה\"ב ג\"כ שהרי אין הקב\"ה מקפח שכר כל ברי', וא\"כ ענין סתימת נה\"ב הוא היצה\"ר הוא בשביל שלא יצייתו לו כמ\"ש בזהר ממשל הזונה עם בן המלך<sup data-n=\"316\">314</sup> כו' ונמצא כי עבור שכר מניעתה וסתימתה שעי\"ז נתעלה הנה\"א כנ\"ל צ\"ל מהו כו', ויובן זה בהקדם המשל בסתימת אמת המים הנ\"ל כשמתגברי' המים מאד וקורעים מקום הסתימה הנה הדבר שבו סתמו מקום הליכת המים מקודם שנקרע הנה הוא הולך ג\"כ עם המים שהמים מוליכים הנסרים עד\"מ ג\"כ למקום שהם הולכים, ונמצא כשם שהסתימה פעלה שיגברו המים עד שיקרעו הסתימה, כן אח\"כ כאשר נתגברו המים ושבים ללכת במקום הילוכם רק בתגבורת יותר או גם מתפשטים יותר הנה הם מובילים את דבר הסתימה למקום שהם בעצמם לא הי' באפשרם להלוך כלל. ועד\"ז יובן בנמשל שגוף האדם יסודו מעפר, וכמ\"ש בבריאת אדה\"ר וייצר ה' אלקי'<sup data-n=\"317\">315</sup> את האדם עפר מן האדמה כו', ואח\"כ נפח בו רוח חיים שהי' גופו מוטל תחלה בריאה מן העפר ולא נתעלה במעלת המדבר כ\"א הי' דומם כתחילתו רק שנעשה ציור ותמונת גוף אדם ונעשה כלי מוכן לקבל צורת הנפש וכנ\"ל, &lt;23&gt;\nּ וע' בת\"א בד\"ה וייצר<sup data-n=\"318\">316</sup>, וחיות הגוף עצמו שיחיה באופן בריאותו כמ\"ש נברא ונוצר אינו תלוי בנפשו כלל וכנ\"ל, ומה שארז\"ל בענין נשמה מאימתי ניתן באדם<sup data-n=\"319\">317</sup> משעת יצירה צ\"ל הכוונה חיות בשר האדם לבד ולא חיות כאדם הנולד, שזהו רק בכדי שלא יסרח<sup data-n=\"320\">318</sup>, אלא שצ\"ע ממארז\"ל מלמדין אותו כל התורה<sup data-n=\"321\">319</sup>, שבאמת גם מזה אין פירכא כלל שהרי זהו רק הכח שיעסוק בתורה אח\"כ כמ\"ש בלק\"ת<sup data-n=\"322\">320</sup>, וא\"כ א\"ז מכחות נפשו הנגלי' דאל\"כ לא הי' עבודה והי' זאת בטבעו כטבע הגשמיות כו', ורואים אנו בצאתו לאויר העולם שהגוף נעשה מסתיר אח\"כ ומעלים על אור הנפש היודעת את בוראה ועמדה לפניו באהוי\"ר כו', ומלבד זה גם אם חיות הבשר הוא מהנפש הנה הנפש מחי' את הבשר בהכרח לומר שיש מציאות בשר תחילה אשר הנפש מחי' אותה, ובלתי חיות א\"א להיות מציאות כו', וכן נה\"ב שבאדם הנה הוא ממה שנפל בשבה\"כ מעולם התהו כו', שדעת לנבון נקל שמפני גסותם א\"א להם לעלות במעלות כ\"א ע\"י עבודה ובירור כו', ולכן רוח הבהמה נה\"ב שבאדם מצ\"ע הנה היא יורדת למטה בארץ<sup data-n=\"323\">321</sup>, ואשר על כן ועל כל הנעשה בהם הנה הם מעלימים ומסתירים על אור ה' וקדושתו שהנה\"א יודעת",[["316","314","<b>ממשל הזונה עם בן המלך</b>: ראה זהר תרומה קסג, א. תניא פ\"ט ופכ\"ט ובמ\"מ הגהות והע\"ק לשם. תו\"ח מקץ רטז, ד הערה 67."],["317","315","<b>וייצר ה' אלקי'</b>: בראשית ב, ז."],["318","316","<b>בת\"א בד\"ה וייצר<sup data-n=\"e67\">א</sup></b>: ראה שם ג, ד. ד, א ואילך."],["319","317","<b>נשמה מאימתי ניתן באדם</b>: ראה סנהדרין צא, ב (ע\"י שם ובמפרשים). מ\"מ הגהות והע\"ק לש' היחוד והאמונה פ\"ו (ע' שעא). המשך תער\"ב ח\"ב ע' א'יב. לקו\"ש ח\"י אלול כרך כד ע' 180."],["320","318","<b>משעת יצירה. . כדי שלא יסרח</b>: כ\"ה גם בהמשך יונתי הנדפס. ובשני ההנחות שנדפסו לקמן. ראה סנהדרין שם."],["321","319","<b>מלמדין אותו כל התורה</b>: ראה נדה ל, ב. מפרשי הע\"י שם. תו\"ח בא ח\"א קכט, א. וש\"נ. בשלח קפ, ג. וש\"נ."],["322","320","<b>רק הכח. . בלק\"ת</b>: שלח מד, א."],["323","321","<b>רוח הבהמה. . היא יורדת למטה בארץ</b>: ע\"פ קהלת ג, כא.\n\n<b>א</b>  ראה גם אוה\"ת בראשית כרך ג ע' 1138. סה\"מ תרל\"ח ע' קצח."]]],[2000480110,"ומכרת כו', שהרי היא חלק ה' ממש כו', ולכן כל כמה שהגוף ונה\"ב מעלימים ומסתירים על הנה\"א שלא תוכל להיות בבחי' רוח האדם עולה עד שמתגברת עלי' ומתוספת כחה בשיעור רב מאד, כן בבא הנה\"א לבחי' אהבה בכל מאדך מושכת גם הנה\"ב והגוף שיזדככו ויעלו במעלות כמו שהמים מוליכים הנסרים למקום הילוכם, נמצא שבבחי' הכח והעוז הגוף ונה\"ב הם הפועלי' בנה\"א, ובבחי' העלי' הנה\"א הוא הפועל בהגוף ונה\"ב כו', ועכ\"ז שניהם עולים כו'.\n<b></b>קיצור. שע\"י מניעת הגוף ונה\"ב עי\"ז בא הנה\"א לבחי' בכל מאדך, שהגם שזהו מצד המונעי' עכ\"ז מתייחס רק לנה\"א כו', ולהיות כי אין הקב\"ה מקפח שכר כל ברי' לכן מתעלים ג\"כ ע\"ד כמו הנסרים ממקום הסתימה הולכים בזרם המים כו'.\nטו) <b>ומעתה</b> יובן ענין ירידת הנשמה ועלייתה במעשה המצות, רק שהוא באופן אחר לגמרי, ותחילה נבין בעצם ענין המצות שגם הם ירדו ממקום כבוד העצמי ששרשם בתרי\"ג ארחין דגלגלתא בבחי' הרצ\"ע, וירדו להתלבש בדברים גשמיים ציצית בצמר הגשמי ותפילין בקלף הגשמי ושופר גשמי וד\"מ שבלולב גשמיי' ותרומות ומעשרות וצדקה בגשמיות, שכ\"ז הוא ירידה והשפלה גדולה עד אין חקר כלל, שהלא מהו ערך הדברים הגשמיי' אפי' לגבי בחי' רצון האדם כ\"ש וק\"ו לבחי' רצה\"ע שמובדל ומרומם עד אין קץ באמת לאמיתו כו', אלא שהירידה היא צורך עלי'<sup data-n=\"324\">322</sup> בכדי שע\"י הלבשה זו בדברים הגשמיי' שמקבלים חיות מנוגה ששרש שרשן הוא מבחי' התהו שקדם במעלה מתיקון שעי\"ז יתעלו מנפילתם להתעלות למעלה ראש כו', וא\"כ צ\"ל שהעלי' היא למעלה מבחי' הרצון, &lt;24&gt;\nּ דאל\"כ א\"ז עליי' שהרי גם קודם ירידתם היו בבחי' הרצון כו', והוא בבחי' בעל הרצון כו' כנ\"ל. אך הנה ענין המצות תלוי בעשיית האדם דוקא, שכאשר איש הישראלי עושה המצוה אז היא מצוה, ויש בה מבחי' בעל הרצון כו', אבל קודם שעושה המצוה לא יש שם מצוה עליה כלל שהרי תפילין הם רק תשמישי קדושה<sup data-n=\"325\">323</sup>, וציצית תשמישי מצוה<sup data-n=\"326\">324</sup>, ולא בשם מצוה לפי שענין ציווי המצוה הוא צו את בנ\"י<sup data-n=\"327\">325</sup> שיעשו מצוה כו' א\"כ קריאת שם מצוה תלוי בעשיית האדם ובלתי עשייתו לא יש בה כלל שם עצם המצוה, ועד\"מ ד\"מ שבלולב כמו שהם גדילים עד\"מ אין בהם שום צד מצוה כלל, שהרי אינם דומים לתפילין שנכתבו ונעשו בקדושה כו' משא\"כ צמחי' אלו או גז הכבשי' הרי הם צמחו כטבעם בקבלת חיותם מנוגה בלתי שום שינוי כלל כו', ונמצא כי לבוש הגשמי של המצוה היא רק כמו גרם שכשיעשה האדם אותה אז תהי' מצוה, ועיקר המצוה תלוי בהעשייה דוקא, אמנם גם בלתי גשם הדבר בלתי אפשר שיעשה האדם כו', ולכן היא מתעלית בעליית האדם ועכ\"ז עיקר העילוי הוא",[["324","322","<b>שהירידה היא צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["325","323","<b>תפילין. . תשמישי קדושה</b>: ראה שו\"ע אדה\"ז הל' תפילין סמ\"ב, ס\"ו. אבל כ\"ה בכ\"מ — ראה לעיל ח\"א (בחלק הנחת כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 55."],["326","324","<b>וציצית תשמישי מצוה</b>: ראה שו\"ע אדה\"ז הל' ציצית רסכ\"א. הל' תפילין שם."],["327","325","<b>צו את בנ\"י</b>: ויקרא כד, ב. ועוד."]]],[2000480111,"להאדם דוקא, וזהו שנת' בכ\"ד שכאשר מ\"ה מברר ב\"ן<sup data-n=\"328\">327</sup> מתעלה לבחי' ס\"ג<sup data-n=\"329\">328</sup>, וס\"ג הוא בחי' התהו<sup data-n=\"330\">329</sup> שבז\"ת דס\"ג הי' השבירה<sup data-n=\"331\">330</sup> כנודע, ולעיל נת'<sup data-n=\"332\">331</sup> שהעליייה הוא למעלה מתהו ותיקון, בחי' שם ע\"ב<sup data-n=\"333\">326</sup> דיודי\"ן<sup data-n=\"334\">332</sup> כו', וי\"ל שעליית דברים הגשמיי' ששרשם מבחי' התהו מתעלים לשרשם הוא בחי' תהו דהיינו ש' ס\"ג, אבל האדם העושה מתעלה לבחי' ש' ע\"ב שלמעלה מתהו ותיקון, ועוי\"ל שבאמת שניהם מתעלים למעלה מהתהו, כי אינו דומה כ\"כ גשם המצוה לדבר הגורם כנ\"ל בענין הסתימה, ורק י\"ל שעשיית האדם וגשם המצוה הוא זה וזה גורם כו', ובשניהם הוא הרצה\"ע שנמצא שבהם הוא בעל הרצון, דאל\"כ הלא השבירה הי' בכוונה כנ\"ל<sup data-n=\"335\">333</sup> ובכ\"ד, שזהו ג\"כ כעין ירידה צורך עלי' ואם עולים רק לשרשם מהו העלייה כו', אלא שצ\"ל שמ\"ש שעולים לס\"ג י\"ל ג\"ר דס\"ג שזהו למעלה מתהו ותיקון כו', אמנם לפי מה שנת\"ל בענין ג\"ע שהוא ג\"ר שבכל עולם, א\"כ ג\"ר דס\"ג הוא כענין ג\"ע דתהו שא\"ז תכלית העלי' כו', אמנם באמת חו\"ב הם תרדל\"מ<sup data-n=\"336\">334</sup> א\"כ ס\"ג וע\"ב הם ג\"כ עד\"ז וצ\"ע, או י\"ל שג\"ר דס\"ג זהו למעלה מתהו, וכמו ג\"ע דתיקון י\"ל שזהו ג\"ר דז\"ת עצמם, אך באמת א\"צ לזה כלל שהרי בתהו לא הי' שייך ג\"ר לז\"ת שזהו רק בתיקון ציור אדם אבל בתהו נקודים זת\"ז<sup data-n=\"337\">335</sup> הנה גם במדות לא הי' התכללות וכ\"ש מוחין ומדות, א\"כ ג\"ר דס\"ג הוא למעלה מתהו כו'.\n<b>ובכ\"ז</b> יובן ענין אני לדודי ודודי לי הרועה בשושנים<sup data-n=\"338\">336</sup>, ולכאו' צ\"ל מהו ענין הרועה בשושנים לבחי' אני לדודי, אך הענין הוא שארז\"ל א\"ת שושנים אלא ששונים<sup data-n=\"339\">337</sup> והיינו ששונים בהלכות, שכל מצותי' ש\"ת הם מבוארי' בהלכות, ונא' שושנים שכשם בשושנה יש י\"ג עלין<sup data-n=\"340\">338</sup> דסחרין לה כך בתורה הוא י\"ג מדות",[["328","327","<b>מ\"ה מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["329","328","<b>ב\"ן מתעלה לבחי' ס\"ג</b>: ראה לקו\"ת בחוקותי מז, ג. תו\"ח וארא ח\"א ע, ג. וש\"נ."],["330","329","<b>וס\"ג הוא בחי' התהו</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"א. תו\"ח בראשית ט, א ובהערה 2."],["331","330","<b>שבז\"ת דס\"ג הי' השבירה</b>: ראה גם תו\"א מג\"א צז רע\"ג. לקו\"ת פ' ראה לא, ב. תו\"ח בא ח\"א קיז, רע\"ג. (וארא פה, ג. וש\"נ)."],["332","331","<b>ולעיל נת'</b>: ראה פי\"ב."],["333","326","<b>מ\"ה. . ב\"ן. . ס\"ג. . ע\"ב</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ ובהערות 79-82."],["334","332","<b>שם ע\"ב דיודי\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. שער רפ\"ח ניצוצין שי\"ח, פ\"א. מאמרי אדה\"א דברים ח\"ד ע' א'קצב. וש\"נ. לוח השמות במק\"מ בסוף בראשית קכו, ב."],["335","333","<b>השבירה הי' בכוונה כנ\"ל</b>: לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ס. פס\"א."],["336","334","<b>חו\"ב הם תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."],["337","335","<b>בתהו. . זת\"ז</b>: ראה ע\"ח שער הכללים פ\"א. שער התיקון ש\"י, פ\"ה. מאמרי אדה\"א קונטרסים ע' תז. וש\"נ. וראה גם סה\"מ תרל\"ח ע' רסא. וש\"נ."],["338","336","<b>אני לדודי ודודי לי הרועה בשושנים</b>: שה\"ש ו, ג."],["339","337","<b>אל תקרי שושנים אלא ששונים</b>: ראה זח\"ב תוספות עדר, א. מאמרי אדה\"א דברים ח\"ד ע' א'קפח. וש\"נ. סה\"מ תרל\"ח ע' רפה. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הב' בסופה."],["340","338","<b>בשושנה יש י\"ג עלין</b>: ראה זהר בהקדמה א, א. ביאורי הזהר שם. ולהצ\"צ כרך ב ע' תקצא. ע' תקצט ואילך. תו\"א מג\"א קטז, ג. לקו\"ת פ' ראה לג, א. לד, ב. מאמרי אדה\"ז תקס\"ו ע' שפה ואילך."]]],[2000480112,"שהתורה נדרשת בהם<sup data-n=\"341\">339</sup>, שעי\"ז מתעלים נש\"י להיות אני לדודי ודודי לי ס\"ת ד' יודי\"ן<sup data-n=\"342\">340</sup> שהם בחי' ד' יודי\"ן דש' ע\"ב<sup data-n=\"343\">341</sup> בחי' אזרח כו' כמ\"ש בהגהות לד\"ה ראה אנכי נותן שבלק\"ת<sup data-n=\"344\">342</sup> כו'.\n&lt;25&gt;\nּ<b>קיצור.</b> מצות שנתלבשו בדברים גשמיי' זהו ג\"כ ירידה צורך עלי', ועכ\"ז עיקר תלוי בעשיית האדם דוקא, והעלי' הוא בע\"ב דיודי\"ן, וזהו אני לדודי כו' ד' יודי\"ן שזהו ע\"י הרועה בשושנים א\"ת שושנים אלא ששונים בהלכות שהם פי' וביאור המצות כו'.",[["341","339","<b>י\"ג מדות שהתורה נדרשת בהם</b>: תו\"כ ר\"פ ויקרא."],["342","340","<b>אני לדודי. . ד' יודי\"ן</b>: אבודרהם סדר תפלת ר\"ה ופירושה בשם הדרשנים. דרשות ר\"י אבן שועיב ס\"פ שופטים בשם המדרש. אילת אהבים לר\"ש אלקבץ שה\"ש ו, ג. ר\"ח שער התשובה פ\"ד (ד\"ה עוד יש). ב\"ח לטאו\"ח סתקפ\"א ד\"ה והעבירו בשם האחרונים."],["343","341","<b>ד' יודי\"ן דשם ע\"ב</b>: ראה גם רמ\"ז תרומה קלד, ב הובא בלקו\"ת במדבר ט, ד. בלק ע, ב [ומציין ללקו\"ת — להאריז\"ל — בלק כג, י<sup data-n=\"e68\">ב</sup>. שער היחודים פ\"ח<sup data-n=\"e69\">ג</sup>]. לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב (בחלק הנחותיו) כאן בסופה."],["344","342","<b>דש' ע\"ב בחי' אזרח כו' בהגהות לד\"ה ראה שבלק\"ת</b>: ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 93.\n\n<b>ב</b>  ראה גם שער הפסוקים וספר הליקוטים שם.\n\n<b>ג</b>  בלקו\"ת — להאריז\"ל — שם מציין: [פ\"ח] יחוד ה. וראה שער רוח הקדש קלא, ב יחוד ח\"י."]]],[2000480113,"<h3>[אני לדודי] והנה אני לדודי ודודי לי</h3>\n<b>פ' תבא</b>\nטז) <b>והנה</b> אני לדודי ודודי לי<sup data-n=\"345\">343</sup>, ר\"ת אלול<sup data-n=\"346\">344</sup>, ולכן מסיים הרועה בשושנים שהם יגמה\"ר, וכמו השושנה שיש לה תליסר עלין דסחרין לשושנה, אוף כנס\"י כו' תליסר מכילין דרחמי כמ\"ש בזהר<sup data-n=\"347\">345</sup>, ולפ\"ז צ\"ל הלא בפסוק דודי לי ואני לו<sup data-n=\"348\">346</sup> כתיב ג\"כ הרועה בשושנים ששם לכאו' אינו שייך יגמה\"ר, שהרי פסוק זה מדבר ביצ\"מ ובמ\"ת ומהו\"ע יגמה\"ר לשם. והנה מצינו עוד בשה\"ש שא'",[["345","343","<b>והנה אני לדודי ודודי לי</b>: מכאן מתחיל מאמר הו' מהמשך יונתי (הכולל פרקים טז-יח). ממאמר זה נדפסו לקמן עוד שני הנחות [שבהם הפתיחה היא: אני לדודי], והם: הנחת<sup data-n=\"e70\">*</sup> כ\"ק אדמו\"ר מהורש\"ב. ב) הנחה אחרת."],["346","344","<b>אני לדודי ודודי לי ר\"ת אלול</b>: ראה אבודרהם סדר תפלת ר\"ה ופירושה בשם הדרשנים. דרשות ר\"י אבן שועיב ס\"פ שופטים בשם המדרש. סדר היום סדר ר\"ח אלול. ב\"ח לטאו\"ח סתקפ\"א ד\"ה והעבירו בשם האחרונים. מאמרי אדה\"א דברים ח\"א ע' שלב. וש\"נ."],["347","345","<b>בשושנים שהם יגמה\"ר. . כמ\"ש בזהר</b>: ראה שם בהקדמה א, א. ביאורי הזהר שם. ולהצ\"צ כרך ב ע' תקצא. ע' תקצט ואילך."],["348","346","<b>דודי לי ואני לו</b>: שה\"ש ב, טז."],["e70","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\nמעתיק חלק מלשונו (מהתיבות דרכן של בנ\"א. . ובניו שם).\nכנ\"ל (ואלו הן. . תבואתה). ומקדים לזה הב\"ר שבהערה 358 דבסמוך.\nכאן הלשון: שני דברים קדמו לעולם תורה וישראל, ובשני דברים אלו אני אומר ישראל קדמו (ומביא הב\"ר).\nמעתיק לשונו (שני דברים. . תבואתה בשינוי קל). ומציין ללקו\"ת יונתי. ומפרש התיבות שני דברים.\nושם: ”ואדמו\"ר הביא ראי' לזה\". וכ\"ה לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב (בחלק הנחותיו) כאן: ורבינו ז\"ל הביא ראי' לזה. ובהנחה שני' (לקמן בחלק ההנחות) כאן: והביא אדמו\"ר נ\"ע ראי' ע\"ז. וראה גם בסמוך הערה 358.\nנדפס גם בסה\"מ תש\"ט ע' 219.\nהובא כמו בסה\"מ ה'ת\"ש דבפנים ההערה.\nושם בשינוי. ראה הערה לשם. בסה\"ש דלקמן שבפנים ההערה."]]],[2000480114,"אני לדודי ועלי תשוקתו<sup data-n=\"349\">347</sup>, שענין פסוק זה מורה שתשוקתו ית' עלינו כבי' גדולה יותר מכמו תשוקת ישראל אליו ית' ח\"ו, שזהו אינו מובן כלל, ולאיזה צורך תשוקתו ית' עלינו, וכמו שהקשו המפרשים בענין העבודה דכתי' ועבדתם כו' ולעבדו בכל לבבכם<sup data-n=\"350\">348</sup> הלא הוא ית' שלימותא דכולהו<sup data-n=\"351\">349</sup> כו', אך הענין הוא כמארז\"ל נתאוה הקב\"ה להיות לו ית'<sup data-n=\"352\">351</sup> דירה בתחתונים<sup data-n=\"353\">350</sup>, ומפני מה נתאוה<sup data-n=\"354\">352</sup> זה א\"י<sup data-n=\"355\">353</sup> ואינו מושג לנו כו', אך זה ידוע לנו שנתאוה כו', ועד\"ז מצינו בדרז\"ל במד\"ר ע\"פ שוקיו עמודי שש זה העולם שנשתוקק הקב\"ה לבראותו<sup data-n=\"356\">354</sup>, שג\"כ מדוע נשתוקק זה אינו ידוע לנו, רק זאת ידוע לנו שנשתוקק כו', ושרש הענין יובן ע\"פ משרז\"ל בתנא דבי אליהו שני דברים קדמו לעולם<sup data-n=\"357\">355</sup> תורה וישראל, וא\"י איזה<sup data-n=\"358\">356</sup>",[["349","347","<b>אני לדודי. . ועלי תשוקתו</b>: שם ז, יא."],["350","348","<b>ועבדתם כו' ולעבדו בכל לבבכם</b>: משפטים כג, כה. עקב יא, יג. ראה גם לקו\"ת בהעלותך לה, סע\"ד ואילך. בלק ע, ג. מאמרי אדה\"ז תקס\"ב ח\"א ע' רסב. ענינים ע' רמה ואילך. אוה\"ת משפטים ע' א'קצח. ע' א'רו ואילך. ע' א'ריט ואילך. ע' א'רמד. סה\"מ תרל\"ג ח\"ב ע' תלב."],["351","349","<b>שלימותא דכולהו</b>: ת\"ז בהקדמה יז, ב."],["352","351","<b>ית'</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 14. ד\"ה יפה שעה הג' על יד הערה 15. סה\"מ תרכ\"ט ע' רט. תרל\"ח ע' מ. מכתב כ\"ק אדמו\"ר (מהוריי\"צ) נ\"ע לריזיק מח' אדר ב' תרפ\"ט<sup data-n=\"e71\">א</sup>. שיחת ליל ב' דחה\"פ תשי\"ב פסקא מה נשתנה<sup data-n=\"e72\">ב</sup>. לקו\"ש דברים כרך יט ע' 27 ואילך."],["353","350","<b>נתאוה הקב\"ה. . דירה בתחתונים</b>: ראה תניא רפל\"ו. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1693."],["354","352","<b>ומפני מה נתאוה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1776."],["355","353","<b>א\"י</b>: בהמשך יונתי הנדפס: אינו ידוע."],["356","354","<b>במד\"ר ע\"פ שוקיו עמודי שש. . לבראותו</b>: במד\"ר רפ\"י. שה\"ש ה, טו."],["357","355","<b>בתנא דבי אליהו<sup data-n=\"e73\">ג</sup> שני דברים קדמו לעולם</b>: רבא קרוב לספי\"ד בשינויים."],["358","356","<b>וא\"י איזה</b>: בהמשך הנדפס: ואינו ידוע איזהו. בתנד\"א ובאוה\"ת משלי שם: אבל איני יודע איזה [באוה\"ת איזהו].\n\n<b>א</b>  נדפס ברשימות חוב' קפד ע' 5.\n\n<b>ב</b>  נדפס בשיחות קודש תשי\"ב כרך ג ע' 253 ס\"ה.\n\n<b>ג</b>  מובא גם בכ\"מ ומהם: אוה\"ת בא ע' רצד. תבוא ע' תתרלד. ע' תתרלט. משלי כרך א ע' תקפו. סה\"מ תרכ\"ו ע' רכח. תרכ\"ז ע' רלה. ע' רמד. ס\"ע תז. תרל\"ה ח\"א ע' רמא. ח\"ב ע' שנז. ע' תקמג. (המשך מים רבים) תרל\"ו פקע\"ה. ח\"ב ע' רמו. ע' רמט. תרנ\"ט ע' יג. (המשך) תרס\"ו ע' תקז. (המשך) תער\"ב ח\"א ע' קמב. ח\"ג ע' א'רנא. ע' א'תג. תרפ\"ג ע' רמח. ה'ת\"ש ע' 61. תש\"ה ע' 121. לקו\"ש כ' מ\"ח תש\"מ כרך כ ע' 370. ברכה כרך לד ע' 222. סה\"ש תשמ\"ט ח\"ב ע' 725 בהערות. תשנ\"א ח\"ב ע' 816 ואילך ובהערות. תשנ\"ב ח\"א ע' 48 בהערות. ע' 116 ואילך ובהערות. ח\"ב ע' 447."]]],[2000480115,"מהם קדם אומר אני ישראל<sup data-n=\"359\">357</sup> קדמו, וכן מובן ממה שאומר<sup data-n=\"360\">358</sup> (היינו בתורה שקדמה לעולם<sup data-n=\"361\">359</sup> ) צו את בנ\"י דבר אל בנ\"י<sup data-n=\"362\">360</sup> הוי ישראל קדמו, והיינו כי בחר בנו לעבדו וליראה אותו שזהו ע\"י קיום מצותיו הנא' בתורה, וגם לימוד התורה עצמה הוא מכלל הרמ\"ח מצות<sup data-n=\"363\">361</sup> עשה<sup data-n=\"364\">362</sup> כו', ונמצא כי התומ\"צ הם הפרטים שעי\"ז מתגלה שאנו עובדים אותו, והעובד קדם במח', ובשביל זה נבה\"ע, והגם שנת\"ל בפי' אנכי עשיתי ארץ כו' שכ\"ז הוא בשביל בראתי בגימ' תרי\"ג כו' צ\"ל שע\"י קיום התרי\"ג מצות מתברר עבודתינו כנ\"ל, והעיקר הוא כפשוטו של מקרא ואדם עליה בראתי שכל מכוון הארץ הוא בשביל האדם וכמ\"ש כי זה כל האדם, ואתם קרוים אדם<sup data-n=\"365\">363</sup> כו' והיינו ע\"י עבודתו<sup data-n=\"366\">364</sup> שהוא בבחי' זה כו', ע\"י בחי' קיום המצות כו', ושרש ענין מעלת האדם הוא שבו וע\"י נמשך המשכת אלקותו בעוה\"ז השפל והגשמי שז\"ע דירה בתחתונים והיינו כמו שהי' קודם הבריאה וביתר שאת, דהנה ידוע שרש ענין הצמצום הוא כשעלה ברצונו הפשוט להטיב לברואיו<sup data-n=\"367\">365</sup> דזה א\"א כ\"א ע\"י שצמצם וסילק אורו הגדול כבי' על הצד<sup data-n=\"368\">367</sup> כמ\"ש בע\"ח ובס' מב\"ש<sup data-n=\"369\">366</sup>, ונשאר חלל ומק\"פ<sup data-n=\"370\">368</sup> שלא נשאר<sup data-n=\"371\">369</sup> רק רשימה לבד, וע' מזה בד\"ה מצה זו בענין &lt;26&gt;\nּ אז ישיר<sup data-n=\"372\">370</sup>, ונמשך המשכת הק\"ו, והוא מסיים באצי'<sup data-n=\"373\">371</sup>, ובוקע הפרסא<sup data-n=\"374\">372</sup> שבין אצי' לבי\"ע להיות נמשך הארת הק\"ו ע\"י העבודה",[["359","357","<b>אומר אני ישראל</b>: בהמשך הנדפס: אומר אני שישראל. בתנד\"א־ אוה\"ת משלי־ בא שם: אבל אני אומר ישראל."],["360","358","<b>וכן מובן ממה שאומר</b>: ראה ב\"ר פ\"א, ד. לקו\"ת שה\"ש טז, ד. לקמן בשתי ההנחות (נעתקו בשוה\"ג דלעיל) כאן. בהשיחות שבהערה 355. וראה גם לקו\"ש עקב כרך יט ע' 458 (נדפס גם באג\"ק שלו כרך יד ע' קפט)."],["361","359","<b>בתורה שקדמה לעולם</b>: פסחים נד, א."],["362","360","<b>דבר אל בנ\"י</b>: בשלח יד, ב. טו. תרומה כה, ב. תשא לא, יג. ויקרא א, ב. ועוד."],["363","361","<b>לימוד התורה. . הרמ\"ח מצות עשה</b>: ראה סהמ\"צ להרמב\"ם מ\"ע יא."],["364","362","<b>הרמ\"ח מצות עשה</b>: מכות כג, סע\"ב."],["365","363","<b>ואתם קרוים אדם</b>: יבמות סא, א. ראה גם תו\"ח יתרו ח\"ב רסב, א ואילך ובהערה 285. סה\"מ מלוקט ו' ע' פג. וש\"נ."],["366","364","<b>עבודתו</b>: בהמשך יונתי הנדפס: עבודתינו."],["367","365","<b>כשעלה ברצונו הפשוט להיטיב לברואיו</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב (כשעלה ברצונו הפשוט). שער הכללים בתחילתו (להיטיב לברואיו)."],["368","367","<b>וסילק אורו הגדול כבי' על הצד</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 216 ובשוה\"ג ד שם."],["369","366","<b>שצמצם וסילק. . ובס' מב\"ש</b>: ח\"א פ\"א. פ\"ב. ראה גם לקו\"ת בהוספות (לויקרא) נא, ב-ג שמציין לאוצ\"ח ומבו\"ש."],["370","368","<b>ונשאר חלל ומק\"פ. . רשימו</b>: ראה המשך מצה זו שם הערה 217."],["371","369","<b>נשאר</b>: בהמשך יונתי הנדפס: נמשך. וכנשצ\"ל כבפנים."],["372","370","<b>בד\"ה מצה זו בענין אז ישיר</b>: ראה לעיל הערות 367-368."],["373","371","<b>הק\"ו והוא מסיים באצי'</b>: ראה ע\"ח שער סדר אצי' ש\"ג בתחלתו. תו\"ח ויצא קעו, ג הערה 45."],["374","372","<b>הק\"ו. . ובוקע הפרסא</b>: ראה אגה\"ק ס\"כ (תניא קלא, ב). סה\"מ תר\"ן ע' רפג [ושם ”דבע\"ח ובשמ\"ש שם\". ושם ע' רפב מציין: ”בע\"ח (שער אבי\"ע<sup data-n=\"e74\">ד</sup> ושער סדר אבי\"ע ובשמ\"ש שער ההקדמות שער דרושי אבי\"ע)\"<sup data-n=\"e75\">ו</sup> לקו\"ש בראשית טו ע' 472 (נדפס גם באגרותיו ח\"ג ריש ע' קלו).\n\n<b>ד</b>  שתי תיבות אלו אינן מופיעים בלקו\"ש שבפנים ההערה (וכן אינם בהמשך זה שיו\"ל בקופיר). אבל אולי אינם שייכים להמבואר כאן (בע' רפג. אלא לעמוד שלפנ\"ז ע' רפב). ראה שם שער דרושי אבי\"ע פי\"ג-פי\"ד.\n\n<b>ו</b>  דרוש א (שעח, רע\"א)."]]],[2000480116,"בתומ\"צ, שהעיקר הוא להוסיף אורות באצי'<sup data-n=\"375\">373</sup>, וממילא נמשך הארת האצי' ע\"י הבקיעה הנ\"ל בבי\"ע כו' כמ\"ש במ\"א בענין לאתקנא רזא דשמא קדישא<sup data-n=\"376\">374</sup> כו', בהגהות לד\"ה משה ידבר<sup data-n=\"377\">375</sup>.\n<b>ולהבין</b> זה צ\"ל מה\"ע הוספת אורות באצי', הלא אצי' הוא אלקות<sup data-n=\"378\">376</sup> והע\"ס ביאר בעבודת הקדש באריכות איך שהוא אינון ואינון הוא<sup data-n=\"379\">377</sup> כו' ומהו ע\"י<sup data-n=\"380\">*378</sup> תוס' אורות באצי' כו', וגם צ\"ל ענין בחי' הק\"ו שמאיר באצי' לבד ולא בבי\"ע כו'. אך הענין הוא דהנה מה שאצי' הוא אלקות היינו שאינו כמו נבראי' דבי\"ע ואפי' ע\"ס דבי\"ע כ\"א שהם אלקות (בל\"א געטליך) אבל לא אלקה<sup data-n=\"381\">378</sup> (בל\"א גאט) ולכן בכדי להיות התהוות יש מאין זהו ע\"י שבחי' איהו דוקא אוא\"ס מתייחד עם גרמוהי, איך שנפרש גרמוהי הן על כלים או ז\"ת, הרי אין ביכולת בחי' גרמוהי עצמם להוות יש מאין א\"ל<sup data-n=\"382\">379</sup> ע\"י יחוד בחי' איהו עם גרמוהי כו', והיינו דעם היות אצי' הוא אלקות עכ\"ז זהו מה שנאצל מאתו ית' ע\"פ הצמצום ומק\"פ כנ\"ל, ולכן ע\"י המצות ממשיכים תוס' אורות באצי' והיינו שממשיכים מבחי' אוא\"ס שלמעלה מאצי' באצי' כו', וממילא נמשך גם בבי\"ע ע\"י שבוקע הפרסא מחמת ריבוי האור שמתוסף באצי' כו'.\n<b>ושרש</b> ענין המשכת אוא\"ס מלמעלה מהאצי' ע\"י עשיית המצות, הנה מלבד מה שע\"י קיום המצות נמשך מבחי' אוא\"ס בעל הרצון כנ\"ל בענין נח\"ר לפני שאמרתי ונעשה רצוני כו', הוא מצד הלבושי' דמעהמ\"צ שנתלבשו בדברים גשמיים דוקא ציצית בצמר הגשמי ושופר מקרן איל<sup data-n=\"383\">380</sup> הגשמי וד\"מ שבלולב מצמחי' הגשמיים שמקבלים חיותם מנוגה כו', שהוא מה שנפל בשה\"כ, ועולים מנוגה להיות כלי לבחי' רצה\"ע שבו מלובש אור בעהר\"צ כו', ולהיות כן מזדככת מחומרתה וגסותה הגשמי להיות כלי לאור בחי' בעהר\"צ שנמשך נעשה לו ית'",[["375","373","<b>העבודה בתומ\"צ. . להוסיף אורות באצי'</b>: ראה פע\"ח בהקדמה. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש יא כלל טז. מאמרי אדה\"א דברים ח\"ד ע' א'תסז. וש\"נ. תו\"ח בשלח ח\"א קנו, ב הערה 312."],["376","374","<b>לאתקנא רזא דשמא קדישא</b>: בתו\"א שמות מט, רע\"ד. יתרו סז, ד בשם הזהר."],["377","375","<b>בהגהות לד\"ה משה ידבר</b>: ראה אוה\"ת יתרו ע' תתלג."],["378","376","<b>אצי' הוא אלקות</b>: ראה לקו\"ת תזריע כג, ב. שלח לח, א. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1599."],["379","377","<b>בעבודת הקדש. . שהוא אינון ואינון הוא</b>: ראה שם חלק היחוד פ\"ד. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 102."],["380","*378","<b>ומהו ע\"י</b>: בהמשך יונתי הנדפס: ומהו\"ע."],["381","378","<b>שאצי'. . שהם אלקות. . אבל לא אלקה</b>: ראה גם סהמ\"צ להצ\"צ ע' נב וע' קלב ואילך. המשך וככה תרל\"ז פע\"ח. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית כרך ו ע' תתרמו. סה\"מ תרל\"ח ע' תכה. וש\"נ. (וראה גם לקמן — בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב — בהנחה כאן הערה 50)."],["382","379","<b>א\"ל</b>: בהמשך הנדפס: אם לא."],["383","380","<b>ושופר מקרן איל</b>: ראה ר\"ה טז, א. מאמרי אדה\"א דברים ח\"ג ע' תתצז. וש\"נ."]]],[2000480117,"בחי' בעהר\"צ דירה בתחתונים, אלא שמפני שעדיין העולם אינו מבורר לכן אינו נראה ונגלה לעינינו הגשמיים בחי' אור וחיות המצוה, ואלמלא ניתנה רשות לעין לראות<sup data-n=\"384\">381</sup> בחי' הרוחניות שיש בדבר הגשמי בעת עשיית המצוה הי' נראה ונגלה לעין כל בחי' אוא\"ס בעהר\"צ, ע\"ד מ\"ש בסש\"ב בענין חיות העולם<sup data-n=\"385\">382</sup>, וזהו אשר יתגלה לע\"ל דכתי' כי עין בעין יראו<sup data-n=\"386\">383</sup>, וכתי' חשף ה' את זרוע קדשו<sup data-n=\"387\">384</sup>, פי' חשף שיעביר ההסתר דכעת שאינו נראה ונגלה מטעם הנ\"ל ויתגלה בחי' זרוע קדשו שהוא עד\"מ היד בשעה שנותנת צדקה ומעשה הצדקה הגשמי, או לולב ואתרוג הגשמי יתגלה ויתראה לעיני כל בחי' פרט הרצון ממעשה המצוה שבו מלובש אוא\"ס בעהר\"צ הוא בחי' אוא\"ס עצומ\"ה בלתי שום הסתר כלל, וכמ\"ש ולא יכנף שיהי' בלתי כנף המעלים ומכסה כו', והיו עיניך רואות<sup data-n=\"388\">385</sup>, כמשל אדם הרואה את חבירו עין בעין כך כבי' יתגלה ויתראה &lt;27&gt;\nּ אוא\"ס שלמעלה מהאצי' בלבוש מעשה המצוה מזוככת מגשמיותה, וע\"ד משנ\"ת במ\"א בד\"ה אלה תולדות נח<sup data-n=\"389\">386</sup> בענין עוה\"ב אין בו לא אכילה ולא שתי'<sup data-n=\"390\">387</sup> כו' שחיות האדם עד\"מ הוא מגשם הבע\"ח וגשם הצומח דוקא, ושרשם מבחי' סוכ\"ע, ולע\"ל יהי' קבלת החיות מבחי' רוחני' הסוכ\"ע שהחיה הבע\"ח והצומח כו', ועד\"ז גשם המצוה שיזדכך לע\"ל יהי' בערך בחי' סוכ\"ע המחיה הדבר ההוא כמו האתרוג וכדומה כו', ונמצא מובן אשר בכלי זכה כזו יוכל להיות גילוי אוא\"ס בחי' בעהר\"צ כו'. וז\"ע אשר נתאוה הקב\"ה להיות לו ית' דירה בתחתוני', פי' שאם היות שגם עכשיו יש בחי' הרצ\"ע ובחי' בעהר\"צ<sup data-n=\"391\">388</sup> במעהמ\"צ מ\"מ זהו בהעלם שאינו נראה כו' שמפני הגסות א\"א להיות התגלות לעינינו כו' אבל נתאוה שיהי' לו דירה הכוונה שיתגלה ויתראה דירתו כו', וא\"כ פי' עלה ברצונו להטיב כו' היינו שיומשך גילוי אלקותו כמו קודם הצמצום רק שא\"א להיות מציאת האדם ומציאות תחתוני' כ\"א ע\"י הצמצום, ושוב בעבודת האדם יומשך גילוי אלקותו כמו קודם הצמצום כו', ויתחדש עי\"ז שהאדם המוגבל יתעלה לראות עין בעין אוא\"ס בעהר\"צ הבלתי מוגבל כו', וזהו דודי לי ואני לו שקאי על יצ\"מ ומ\"ת שנתגלה בחי' דודי לי תחלה ועי\"ז ואני לו, וכמ\"ש נפשי יצאה בדברו<sup data-n=\"392\">389</sup>, וכן אח\"כ קיום התומ\"צ ואשר<sup data-n=\"393\">390</sup> בחר בנו להיות לו לעם סגולה שז\"ע ואני לו זהו ע\"י דודי לי שמתחלה נמשך מלמעלמ\"ט להיות בחי' דודי לי שירד ה' על ה\"ס וגילה אלקותו ית' וקדשנו במצותיו באמרו אנכי ולא יהי' לך<sup data-n=\"394\">391</sup> כו'.",[["384","381","<b>ואלמלא ניתנה רשות לעין לראות</b>: ברכות ו, א."],["385","382","<b>בסש\"ב בענין חיות העולם</b>: שער היחוד והאמונה פ\"ג."],["386","383","<b>כי עין בעין יראו</b>: ישעי' נב, ח."],["387","384","<b>חשף ה' את זרוע קדשו</b>: ישעי' שם, י."],["388","385","<b>ולא יכנף. . והיו עיניך רואות</b>: שם ל, כ."],["389","386","<b>בד\"ה אלה תולדות נח</b>: תרל\"ז פי\"ח — לא נדפס לע\"ע."],["390","387","<b>עוה\"ב אין בו. . שתי'</b>: ברכות יז, א. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קלה ואילך. המשך וככה תרל\"ז פצ\"א. פצ\"ב."],["391","388","<b>כו' וז\"ע. . בעהר\"צ</b>: בהמשך יונתי הנדפס ליתא. ואלי נשמט מפני תיבות הדומות: בעהר\"צ. . בעהר\"צ."],["392","389","<b>נפשי יצאה בדברו</b>: שה\"ש ה, ו."],["393","390","<b>ואשר</b>: בהמשך הנדפס: ואח\"כ."],["394","391","<b>אנכי ולא יהי' לך</b>: ראה יתרו כ, ב-ג."]]],[2000480118,"<b></b>קיצור. בב\"פ<sup data-n=\"395\">392</sup> אני לדודי נא' הרועה בשושנים, ופעם ג' מסיים ועלי תשוקתו, נתאוה להיות לו דירה בתחתונים כו', וז\"ע מעלת האדם כו', להוסיף אורות באצי' ע\"י מעהמ\"צ, ולברר הגשמיות ע\"ד<sup data-n=\"396\">393</sup> חיותה הרוחני' שיאיר בה בגילוי אוא\"ס בעהר\"צ כמו קודם הצמצום כו', וזהו דודי לי.\nיז) <b>אך</b> הנה כ\"ז הוא כשאכשיר דרי<sup data-n=\"397\">394</sup> בקיום התומ\"צ כדבעי לאיש הישראלי, וכן בעבודה שבלב כמ\"ש ולעבדו בכל לבבכם הן בקיום המצות עד\"מ בתפילין לשעבד הלב והמוח<sup data-n=\"398\">395</sup>, והן כמארז\"ל עבודה שבלב זו תפלה<sup data-n=\"399\">396</sup> כו', בכל הפרטים כו', אבל אם חטא והעביר את הדרך בחי' דרך ה' לעשות צדקה ומשפט<sup data-n=\"400\">397</sup>, ופגם בהעדר עשיית מ\"ע, וכ\"ש בעשותו אחת ממצות ה' אשר לא תעשינה ואשם<sup data-n=\"401\">398</sup> כו', וגם מי שלא חטא בפו\"מ כ\"א הרהורי עבירה לבד הרי ארז\"ל הרהורי עבירה קשה מעבירה<sup data-n=\"402\">399</sup> לפי שהמחשבה היא כח היותר דק, ולכן מתקלקל יותר כמו הבגד משי דק שמתקלקל יותר ע\"י הכתמים שנעשו בו מהר יותר מבגד פשתן או קנבוס כו', וגם שהמח' היא לבוש הרצון השולט על כל כחות הנפש, וגם אין לו הגבלה שכ\"ז שלא קיים תאוותו במעשה אינו מרוה צמאונו הקשה וה\"ה מלא מחשבות רעות אשר מכ\"ז הרהורי עבירה קשים יותר מעבירה עצמה כו', ואי לזאת הנכשל באחת מאלה לא די שלא פעל ע\"י עשיותיו במעהמ\"צ כנ\"ל להוסיף אורות באצי' &lt;28&gt;\nּ לאתקנא רזא דשמא קדישא כ\"א הוריד המשכת הקדושה למקום הטינופת אשת הזימה כו', והוסיף חיות בסט\"א כו', לכן כמו החולה בא' מאבריו שלא יעלה ארוכה ע\"י אכו\"ש לבד כ\"א נצרך הוא לתרופות מיוחדות לרפאות מקום שנחלה, כך מי שפגם במ\"ע מרמ\"ח מצות שהם כנגד רמ\"ח אבריו ש\"א<sup data-n=\"403\">401</sup>, או בל\"ת שהם כנגד<sup data-n=\"404\">403</sup> שס\"ה<sup data-n=\"405\">400</sup> גידיו<sup data-n=\"406\">402</sup> ה\"ה חולה בפרט זה וצריך לרפואה דוקא, ואינו מספיק לו תומ\"צ שילמוד אח\"כ ויעשה מצותיו שזהו כמו אכו\"ש, כמ\"ש לכו לחמו בלחמי<sup data-n=\"407\">404</sup> כו', וכתי' הוי כל צמא לכו למים<sup data-n=\"408\">405</sup>, כמו החולה שאינו מתרפא ע\"י אכו\"ש כ\"א מוכרח לקבל רפואה, וכך ברוחני' צריך הוא רפואה,",[["395","392","<b>בב\"פ</b>: בהמשך יונתי הנדפס: ב\"פ."],["396","393","<b>ע\"ד</b>: שם: עד."],["397","394","<b>כשאכשיר דרי</b>: ע\"פ יבמות לט, ב. חולין צג, ב."],["398","395","<b>בתפילין לשעבד הלב והמוח</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה, סי\"א. סידור שם [נדפס גם בהוספות לשו\"ע שם]."],["399","396","<b>עבודה שבלב זו תפלה</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א. רמב\"ם ריש הלכות תפלה. אוה\"ת עקב ע' תרח."],["400","397","<b>דרך ה'. . ומשפט</b>: וירא יח, יט."],["401","398","<b>בעשותו אחת ממצות ה'. . ואשם</b>: ויקרא ד, כז [ושם: בעשותה — ראה גם לקמן מאמר ד\"ה עשה צדקה ומשפט על יד הערה 154. סה\"מ תר\"ל ע' צג]."],["402","399","<b>הרהורי עבירה קשה מעבירה</b>: ראה יומא כט, א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 381."],["403","401","<b>מרמ\"ח מצות. . אבריו ש\"א</b>: מכות שם."],["404","403","<b>בל\"ת שהם כנגד שס\"ה גידיו</b>: ראה תיוב\"ע וזהר שבהערה שלפנ\"ז."],["405","400","<b>מרמ\"ח מצות. . בל\"ת. . שס\"ה</b>: מכות כג, סע\"ב."],["406","402","<b>רמ\"ח אבריו ש\"א. . שס\"ה גידיו</b>: אהלות פ\"א, מ\"ח. תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב."],["407","404","<b>לכו לחמו בלחמי</b>: משלי ט, ה."],["408","405","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."]]],[2000480119,"וזהו שארז\"ל גדולה תשובה שמביאה רפואה לעולם<sup data-n=\"409\">406</sup>, שע\"י התשובה מתרפא מחולי שלו כו', ושרש ענין התשובה הוא החרטה ועקירת הרצון מדבר שנכשל בו, ושיהי' סור מרע תמיד, ולגדור גדרים שלא ישוב לכסלה, ואז בחי' עשיית הטוב שיעשה יהי' ביסוד מוסד להברותו ולחזקו כמו החולה כשמתרפא מחולאתו שחלה ע\"י התרופות שעושים לו, אז כשמתחיל לאכול מתחזק עוד יותר כו', וכך כאשר שב ורפא לו, אז ע\"י עשיית הטוב שעושה מתחזק הרבה לדבקה בו ית' כו'.\n<b>וביאור</b> הענין, דהנה שרש ענין תרי\"ג מצות הוא כמו תרי\"ג חבלים דקים אשר נתחברו ונכרכו יחד להיות לחבל א', כך יעקב חבל נחלתו, וכמ\"ש בסש\"ב<sup data-n=\"410\">407</sup> משל הנ\"ל שהיא חבל הנכרכה מתרי\"ג נימין דקין, וכאשר עובר האדם<sup data-n=\"411\">408</sup> על מ\"ע או מל\"ת נפסק חבל דק עד<sup data-n=\"412\">409</sup> אשר ע\"י ריבוי העבירות נכרתה נפשו לגמרי כו', ומ\"מ ע\"י התשובה מתקשרת נפשו בקשר אמיץ וחזק שהוא כמשל החבל שנפסקה וקושרין אותה הנה במקום הקשירה שם החבל עב יותר ע\"י שהיא כפולה שם ד' פעמים<sup data-n=\"413\">410</sup> וממילא ה\"ה חזקה יותר במקום הקשירה כו', וכך עד\"מ זה יובן בבחי' יעקב חבל נחלתו שכאשר נפסקו איזהו חבלים דקים שבחבל, או גם אם נכרתה לגמרי ואין לך דבר שעומד בפני התשובה<sup data-n=\"414\">411</sup> שאם תשו\"ת אינו מועיל יועיל לו בחי' תשו' עילאה, ומ\"ש רז\"ל ששמע חוץ מאחר<sup data-n=\"415\">412</sup> כו' כבר פירשו בזה שתשו\"ת לא הי' מועיל לו, אבל תשו' עילאה הי' מועיל גם לו כו', ואי לזאת דעת לנבון נקל איך שכאשר מקשר א\"ע לאלקות ע\"י בחי' תשו' מעומקא דלבא נעשה ההתקשרות יותר עב ויותר חזק כנ\"ל במשל החבל כו', וכמו החולה שלאחר שנתרפא ע\"י תרופות תעלה ארוכה מתחזק בבריאותו יותר ויותר כו', כך הבע\"ת כששב ורפא לו<sup data-n=\"416\">413</sup> הרי הוא קשור עוד יותר כו'.\n<b></b>קיצור. כשפגם באיזה דבר מתרי\"ג מצות, ואפי' בהרהורי עבירה, ה\"ה מוריד שפע הקדושה למקום כו', וגדולה תשובה שמביאה רפואה לעולם, ועי\"ז מתחזק עוד יותר, כמשל החבל שבמקום שקושרין אותה חזק יותר כו'.\n&lt;29&gt;\nּיח) אך איך יבא לידי תשובה מעומקא דלבא, הנה זהו ע\"י שיתבונן ויעורר ר\"ר על נפשו וניצוץ האלקי אשר בקרבו, איך שהוא חלק אלק' ממעל<sup data-n=\"417\">414</sup>, ועד",[["409","406","<b>גדולה תשובה. . לעולם</b>: יומא פו, סע\"א."],["410","407","<b>בסש\"ב</b>: אגה\"ת פ\"ה. פ\"ז (צז, ב). וראה גם אגה\"ת מהדו\"ק ע' תקיג ואילך."],["411","408","<b>האדם</b>: ניתוסף ע\"פ המשך הנדפס."],["412","409","<b>עד</b>: שם ליתא."],["413","410","<b>כפולה שם ד' פעמים</b>: בהמשך שם: כפולה שם ב' פעמים. ראה בשתי ההנחות כאן, כבפנים. אגה\"ת ספ\"ט ובמ\"מ הגהות והע\"ק לתניא פל\"ג (ע' רה). לקוטי לו\"י הערות לס' התניא אגה\"ת כאן (ע' לג). לקו\"ש ביאורים בלקלו\"י על אגה\"ת כרך ט\"ל ס\"ד (ע' 114) ואילך. לקו\"ש ח\"ש כרך ה' ע' 111 הערה 39. תולדות כרך י ע' 73 הערה 30."],["414","411","<b>ואין לך דבר שעומד בפני התשובה</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. לקו\"ש בא כרך ו ע' 66 הערה 54."],["415","412","<b>ששמע חוץ מאחר</b>: חגיגה טו, א."],["416","413","<b>כששב ורפא לו</b>: ע\"פ ישעי' ו, י."],["417","414","<b>חלק אלק' ממעל</b>: ראה איוב לא, ב. תניא רפ\"ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 395."]]],[2000480120,"ירידתו בגוף ונה\"ב עמד באהוי\"ר<sup data-n=\"418\">415</sup> והתקשרות עצומה בשרשו ומקורו באוא\"ס חיי החיים<sup data-n=\"419\">416</sup>, וירד עשר מעלות אחורנית<sup data-n=\"420\">417</sup> לבוא להתלבש בגוף שפל ונבזה שלא בערך ממש, וכמשנת\"ל שהירידה היא צורך עלי' שע\"י ירידתו הלזו יתעלה בעילוי אחר עילוי לדבקה בו אוא\"ס בחי' איהו וחיוהי כו', והנה צלל במים אדירים והעלה בידו חרס<sup data-n=\"421\">418</sup> שלא די שלא תיקן כלום אלא שפגם נפשו עד שכולה מליאה פצעים ומכף רגל ועד ראש אין בה מתום<sup data-n=\"422\">419</sup> מחמת הפגמי' והמחשבות זרות ורעות שנדבקו והלבישו אותה עד שנדחית ממחיצתה ר\"ל, ולכן גדלה הרחמנות עליה עד אין שיעור, ואי לזאת יתמרמר לבו<sup data-n=\"423\">420</sup> בקרבו ויעורר ר\"ר על נפשו האלקי' עד שיצעק מתוך פנימיות נקודת לבבו לה' אחד וישוב וירחמהו ויכבוש עוונותיו<sup data-n=\"424\">421</sup> וימחול ויסלח לו כו', וז\"ע תקיעת שופר שהתקיעה היא צעקה פנימיות בקול פשוט, שברים תרועה ז\"ע גנוחי גניח ילולי יליל<sup data-n=\"425\">422</sup> כמשל החולה שגונח, וכשמרגיש כאביו צועק שנית בקול פשוט כו', וזהו אני לדודי ודודי לי פי' שע\"י שאני לדודי בבחי' תשו' מעומקא דלבא עי\"ז ודודי לי בבחי' החזרת פנים בפנים, דהנה עד\"מ שני בנ\"א הגם שעומדי' מקרוב רק שהם בבחי' אחור באחור ה\"ה רחוקי' זמ\"ז, אבל כשמתרצים זל\"ז אז כ\"א מסביר פניו לחבירו כו', ועד\"ז יובן בעבודת ה' שכאשר פנו אלי עורף<sup data-n=\"426\">423</sup> ולא פנים זה\"ע אחור באחור, וכמ\"ש ואנכי הסתר אסתיר פני מהם<sup data-n=\"427\">424</sup> כו', אבל ע\"י התשובה נמשך החזרת פב\"פ כו', וז\"ע ודודי לי כו', ובשני פסוקי' אלו<sup data-n=\"428\">425</sup> נא' הרועה בשושנים, וכמארז\"ל א\"ת שושנים אלא ששונים כו', דהנה במשה כשהזכיר שם אל שהוא מדה ראשונה מיגמה\"ר<sup data-n=\"429\">426</sup> כמ\"ש אל נא רפא נא לה, השיב לו הקב\"ה ק\"ו ואביה ירוק ירק בפניה<sup data-n=\"430\">428</sup> כו', וכמש\"פ הרה\"מ נ\"ע<sup data-n=\"431\">427</sup>, כי י\"ג מדות שהתורה נדרשת בהם הם כנגד יגמה\"ר, ולכן כשהזכיר תיקון הראשון מיגת\"ד<sup data-n=\"432\">429</sup> נמשך ק\"ו, וכמ\"כ",[["418","415","<b>ועד ירידתו. . באהוי\"ר</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["419","416","<b>חיי החיים</b>: יומא עא, א. ראה גם תניא פמ\"ד (סג, א)."],["420","417","<b>וירד עשר מעלות אחורנית</b>: ע\"פ מלכים-ב כ, י. יא. ישעי' לח, ח."],["421","418","<b>צלל במים אדירים והעלה בידו חרס</b>: ראה בב\"ק צא, סע\"א. רמב\"ם הל' קדוש החדש פי\"א, ה\"ב."],["422","419","<b>ומכף רגל ועד ראש אין בה מתום</b>: ע\"פ ישעי' א, ו."],["423","420","<b>עד שנדחית. . לבו</b>: בהמשך יונתי הנדפס ליתא. כנראה נשמט בשגגת המעתיק."],["424","421","<b>וישוב. . עוונותיו</b>: ע\"פ מיכה ז, יט."],["425","422","<b>שהתקיעה. . בקול פשוט. . גנוחי גנח ילולי יליל</b>: ראה לקמן ספכ\"ג. וש\"נ."],["426","423","<b>פנו אלי עורף</b>: ירמי' ב, כז. ראה גם לקמן על יד הערה 513. לקמן (בחלק ההנחות) בהנחה ד\"ה כנשר יעיר קנו על יד הערה 38. אחר הערה 57. סה\"מ תרל\"ג ח\"ב ס\"ע שצו ואילך. וש\"נ. מאמרי אדה\"א נ\"ך ס\"ע רי ואילך. וש\"נ."],["427","424","<b>ואנכי הסתר אסתיר פני מהם</b>: חיבור שני כתובים — וילך לא, יח. יז."],["428","425","<b>ובשני פסוקי' אלו</b>: ראה לעיל רפט\"ז."],["429","426","<b>שם אל. . מיגמה\"ר</b>: ראה לקו\"ש אלול כרך ד ע' 1348 ואילך. ובאג\"ק שלו ח\"ב ע' שסט ואילך."],["430","428","<b>השיב. . ואביה ירוק ירק בפניה</b>: שם שם, יד. רש\"י וספרי שם. ב\"ק כה, א."],["431","427","<b>אל נא רפא נא לה. . הרה\"מ נ\"ע</b>: בהעלותך יב, יג. או\"ת שם. לקמן בשתי ההנחות כאן. ראה גם בסמוך הערה 429."],["432","429","<b>י\"ג מדות שהתורה נדרשת. . יגמה\"ר. . מיגת\"ד</b>: ראה גם או\"ת (קה\"ת) שם. קז, ב. לקו\"א סקל\"ט. סה\"מ תרכ\"ו ע' דש. ס\"ע שיט. תרכ\"ז ע' תמו. וש\"נ."]]],[2000480121,"בהיפך על ידי יג\"מ שהתו' נדרשת בהן נמשך י\"ג ת\"ד, ולכן אמרו א\"ת שושנים י\"ג ת\"ד אלא ששונים יג\"מ שהתורה נדרשת בהם כי ענינם א' הוא, ולכן בפסוק דודי לי שקאי על יצ\"מ שהי' הכנה למ\"ת, ועל מ\"ת עצמה נא' הרועה בשושנים שהוא בחי' יג\"מ שהתו' נדרשת שעי\"ז נמשך יגמה\"ר, ובפסוק אני לדודי שקאי על התשובה נא' הרועה בשושנים שהוא בחי' יגמה\"ר כו', רק שפסוק דודי לי זהו כשההמשכה שהיא מלמעלמ\"ט כמו ביצ\"מ ומ\"ת שנגלה עליהם ממה\"מ הקב\"ה<sup data-n=\"433\">431</sup>, ובנון יום ירד ה' על ה\"ס ונתן לנו התורה<sup data-n=\"434\">430</sup> שזהו מלמעלמ\"ט לכן נא' דודי לי תחלה ועי\"ז אני לו, אך פסוק אני לדודי קאי על התשובה שהיא מלמטלמ\"ע נא' אני לדודי תחלה ועי\"ז דודי לי כו', ועכ\"ז נמשך גם ע\"ז סיוע מלמעלה וזהו שאני לדודי ודודי לי ר\"ת אלול וס\"ת ד' יודין שהם &lt;30&gt;\nּ ארבעים נגד ארבעים יום שמר\"ח אלול עד יוהכ\"פ שהוא זמן<sup data-n=\"435\">432</sup> התשובה שאז נמשך הכח מלמעלה בחי' אתעדל\"ע שמעורר אתעדל\"ת<sup data-n=\"436\">433</sup> והיינו הכח שיוכל לבוא לבחי' תשובה כו'.\n<b></b>קיצור. לבוא לידי תשובה זהו ע\"י התבוננות ירידתו וריחוקו מה' אחד, ועי\"ז אני לדודי ואז ודודי לי החזרת פב\"פ, ובשניהם נא' הרועה בשושנים כי יג\"מ שהתו' נדרשת בהם מכוון כנגד יגמה\"ר, וכמ\"ש הרה\"מ בפי' אל נא רפא כו' שנמשך ק\"ו כו'.",[["433","431","<b>שנגלה עליהם ממה\"מ הקב\"ה</b>: נוסח ההגדה."],["434","430","<b>ביצי\"מ. . ובנון יום. . התורה</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1217."],["435","432","<b>זמן</b>: בהמשך יונתי הנדפס: ענין."],["436","433","<b>אתעדל\"ע שמעורר אתעדל\"ת</b>: ראה תו\"א תצוה פב, סע\"א ואילך. לקו\"ת ויקרא ב, ב. וש\"נ."]]],[2000480122,"<h3>[יפה שעה אחת] ומעתה כו' אני לדודי ועלי תשוקתו</h3>\n<b>פ' נצבים</b>\nיט) <b>ומעתה</b> יובן ענין מ\"ש אני לדודי ועלי<sup data-n=\"437\">434</sup> תשוקתו, ויש לדקדק מהו שא' ועלי תשוקתו למה לא אמר ואלי<sup data-n=\"438\">435</sup> תשוקתו באלף שהי' פירושו שתשוקתו הוא לי, ומהו עלי כו', הנה ארז\"ל במד\"ר בראשית פ\"ך (וכ\"ה בשה\"ש",[["437","434","<b>ומעתה כו' אני לדודי ועלי תשוקתו</b>: מכאן מתחיל מאמר הז' מהמשך יונתי (הכולל פרקים יט-כא<sup data-n=\"e76\">א</sup>).\nממאמר זה נדפסו לקמן עוד שלשה הנחות [שבהם הפתיחה היא: יפה שעה אחת], והם: א) רשימת ראשי פרקים<sup data-n=\"e77\">ב</sup> מכ\"ק אדמו\"ר מהורש\"ב. ב) הנחתב כ\"ק אדמו\"ר מהורש\"ב<sup data-n=\"e78\">ג</sup>. ג) הנחה אחרת."],["438","435","<b>ועלי. . ואלי</b>: ראה גם לקו\"ת פ' ראה לד, ב. סידור שער האלול רכז, ד. רכט, ד<sup data-n=\"e79\">ד</sup>. תו\"ח משפטים ח\"ב רפח, ב. סה\"מ תרל\"ח ע' רפה. לקמן מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 50. בג' ההנחות כאן.\n\n<b>א</b>  חלק מפרק כא נכנס בדרוש ויובן ענין הטוב (ר\"ה תרמ\"א).\n\n<b>ב</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>ג</b>  נכתב בשנת תרמ\"ב כפי ששמעתי מהר\"ן מווליז.\n\n<b>ד</b>  וכן צ\"ל בתו\"ח (שבפנים ההערה) הערה 91."]]],[2000480123,"במקומו<sup data-n=\"439\">437</sup> בשינוי קצת) ארבע תשוקות הן<sup data-n=\"440\">436</sup> אין תשוקתה של אשה אלא לאישה שנא' ואל אישך תשוקתך<sup data-n=\"441\">438</sup>, אין תשוקתו של יצה\"ר אלא על קין וחבריו שנא' ואליך תשוקתו<sup data-n=\"442\">439</sup>, אין תשוקתן של גשמים אלא על הארץ שנא' פקדת ארץ ותשוקקיה<sup data-n=\"443\">440</sup>, ואין תשוקתו של הקב\"ה אלא על ישראל שנא' ועלי תשוקתו, ד\"א תשוקתו תשים אנו, ואע\"פ שתשים אנו<sup data-n=\"444\">441</sup>, אנו מקוים לישועתו<sup data-n=\"445\">442</sup> של הקב\"ה ומייחדים שמו בכ\"י, ומסיים בשה\"ש ואומרים ב\"פ<sup data-n=\"446\">443</sup> שמע ישראל כו'. וצ\"ל ב' פירושים אלו שדרש תשוקתו ל' תשוקה, ולשון תש וקו, הנה ענין תשוקת האשה ואל אישך תשוקתך הוא כי אשה אש ה'<sup data-n=\"447\">444</sup> ותשוקתה לאיש בחי' אש יו\"ד<sup data-n=\"448\">445</sup> כו', ותשוקת הגשמים לארץ זהו תשוקת המשפיע למקבל כו'<sup data-n=\"449\">446</sup>, אך ענין תשוקת הקב\"ה על ישראל צ\"ל הלא אנת הוא שלימותא דכולהו כו' וכלום חסר כו', וגם כאן אמרו<sup data-n=\"450\">447</sup> על ישראל ולא לישראל כדקדוק לשון הפסוק ועלי. ויובן בהקדם ענין הפסוק אני לדודי ודודי לי, שהגם שנת\"ל<sup data-n=\"451\">448</sup> שעיקר פי' הפסוק הוא על התשובה, מ\"מ יש לפרשו גם על כלליות העבודה כו' דהנה ארז\"ל בילקוט אני לדודי בעוה\"ז, ודודי לי בעוה\"ב<sup data-n=\"452\">449</sup> כו'. וביאור הענין דהנה ארז\"ל במשנה דאבות יפה שעה א' בתשו' ומעש\"ט בעוה\"ז מכל חיי העוה\"ב, ולכאו' צ\"ל מאחר שאומר מע\"ט עם התשובה למה צריך לתשובה, שהתשובה בכלל היא על חטא ועון שזהו כשלא אכשיר דרי<sup data-n=\"453\">450</sup> כו', וא\"כ מ\"ע תשובה עם מעש\"ט כו'. וגם ארז\"ל כל ימיו בתשובה<sup data-n=\"454\">451</sup> שזהו ג\"כ אינו מובן למה צ\"ל כ\"י בתשובה שמאחר ששב ורפא לו, א\"כ לכאו' א\"צ יותר לתשובה כ\"א למעש\"ט, והאומר אחטא ואשוב<sup data-n=\"455\">452</sup> אין מספיקין בידו לעשות תשובה ואיך הוא<sup data-n=\"456\">453</sup> כ\"י בתשובה. אך הענין דענין ופי' תשובה אינה דוקא על חטא ועון<sup data-n=\"457\">454</sup> בפו\"מ או אף גם על חסרון דק שבדקות שכ\"ז הוא",[["439","437","<b>בשה\"ש במקומו</b>: שהש\"ר פ\"ז, יא."],["440","436","<b>במד\"ר בראשית פ\"ך. . ארבע תשוקות הן</b>: ס\"ז."],["441","438","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["442","439","<b>ואליך תשוקתו</b>: שם ד, ז."],["443","440","<b>פקדת ארץ ותשוקקיה</b>: תהלים סה, י [ושם: הארץ]."],["444","441","<b>ואע\"פ שתשים אנו</b>: כ\"ה בשה\"ר שם [אע\"פ]. ובב\"ר: ואפי' שאנו תשים."],["445","442","<b>לישועתו</b>: כ\"ה בשה\"ר שם. ובב\"ר: לתשועתו."],["446","443","<b>ואומרים ב\"פ</b>: שם: ומיחדים שמו שתי פעמים ואומרים."],["447","444","<b>אשה אש ה'</b>: ראה סוטה יז, א. זהר בראשית מח, ב. ביאוה\"ז נח ז, ב. תו\"ח שבהערה הבאה."],["448","445","<b>לאיש בחי' אש יו\"ד</b>: ראה סוטה שם. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אשה. תו\"ח בשלח ח\"א רלח, ב. וש\"נ."],["449","446","<b>ותשוקת. . כו'</b>: בהמשך יונתי הנדפס ליתא. ואולי נשמט מפני תיבות הדומות: כו'. . כו'."],["450","447","<b>אמרו</b>: שם: אמר."],["451","448","<b>שנת\"ל</b>: פי\"ח."],["452","449","<b>אני לדודי בעוה\"ז ודודי לי בעוה\"ב</b>: ילקוט שמעוני שה\"ש ו, ג (סוף רמז תתקצא). ראה גם לקמן רפכ\"ג."],["453","450","<b>כשלא אכשיר דרי</b>: ע\"פ יבמות לט, ב. חולין צג, ב."],["454","451","<b>כל ימיו בתשובה</b>: שבת קנג, א. ראה גם לקו\"ת בלק עד, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקטו. המשך מים רבים תרל\"ו פקע\"ז. לקמן מאמר ד\"ה רני ושמחי בשולי היריעה פיסקא או."],["455","452","<b>אחטא ואשוב</b>: יומא פה, ב (במשנה)."],["456","453","<b>ואיך הוא</b>: בהמשך הנדפס: כו' ואיך."],["457","454","<b>תשובה אינה. . ועון</b>: ראה חובת הלבבות שער עבודת אלקים פ\"ג (ד\"ה והחמישי כי מצות). תו\"א ויחי מה, א. מאמרי אדה\"א נ\"ך ע' רו. הנחות תקע\"ז ע' צה. סה\"מ תרכ\"ט ע' קד. ע' קכא. ע' קעט. תרל\"ג ח\"ב ע' שעט. המשך מים רבים תרל\"ו פקל\"ה. סה\"מ תרל\"ח ע' תסו. תרצ\"ז ע' 235 ובהנסמן בהנ\"ל. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' יד."]]],[2000480124,"בכלל חטא, שפירושו הוא מלשון חסרון<sup data-n=\"458\">455</sup> כמו קולע אל השערה ולא יחטיא<sup data-n=\"459\">456</sup> שפירושו שלא יחסר כמלא חוט השערה כו', או כמו והייתי אני ובני שלמה חטאים<sup data-n=\"460\">457</sup> פירושו חסרים מן הטוב שהבטיח לה, וכמ\"כ בפי' חטא נכלל חסרון דק שבדקות שהוא ג\"כ בכלל חטא ועון כו', &lt;31&gt;\nּ ולפ\"ז מ\"ש שהתשו' אינה על חטא ועון דוקא צ\"ל שהיא לא על החסרון דק שבדקות ג\"כ, אלא פי' וענין בחי' תשו' זו הוא כפשוטו לשון תשוב שהו\"ע החזרה למקורה<sup data-n=\"461\">458</sup> כמו והרוח תשוב אל האלקי'<sup data-n=\"462\">459</sup> אשר נתנה שפירושה החזרה אל חיק אביה אשר לוקחה משם שהרי היא חלק הוי' ממש כו'.\n<b></b>קיצור. ד' תשוקות הן, תשוקת הקב\"ה על ישראל, כלשון הכתוב ועלי תשוקתו, יפה שעה א' בתשומע\"ט צ\"ל מה\"ע תשו' כשהמעשים הם טובים, וכן<sup data-n=\"463\">460</sup> כ\"י בתשובה, אלא שפי' תשובה לשון החזרה כו'.\nך) <b>ולהבין</b> פי' וענין תשובה זו, צ\"ל שרש ענין השבת שהוא ג\"כ בחי' תשובה<sup data-n=\"464\">461</sup> שהרי שבת אותיות תשב<sup data-n=\"465\">462</sup>, וצ\"ל שייכות ענין השבת לתשובה, שלכאו' מצות שבת היא מצוה מרמ\"ח מ\"ע<sup data-n=\"466\">463</sup> ואינה ענין למצות התשובה שהיא<sup data-n=\"e16\">*</sup>",[["458","455","<b>חטא. . מלשון חסרון</b>: ראה לקו\"ת מטות פב, א. נצבים נא, א. מאמרי אדה\"א דברים ח\"ג ע' תתקיד. נ\"ך ע' נא. סה\"מ תרל\"ב ח\"א ע' קמד. המשך תער\"ב ח\"ג ע' א'תנט. סה\"מ מלוקט א' ע' רצב. שם ב' ע' קכח ובהנסמן בהנ\"ל."],["459","456","<b>קולע אל השערה ולא יחטיא</b>: ס' שופטים כ, טז [בדילוג]."],["460","457","<b>והייתי אני ובני שלמה חטאים</b>: מלכים-א א, כא."],["461","458","<b>תשו'. . החזרה למקומה</b>: ראה לעיל הערה 454."],["462","459","<b>והרוח תשוב אל האלקי'</b>: קהלת יב ז."],["463","460","<b>וכן</b>: בהמשך הנדפס: וזהו."],["464","461","<b>השבת. . בחי' תשובה</b>: ראה אגה\"ת שבהערה הבאה. וראה גם לקו\"ת ש\"ש סו, ג. המשך מים רבים תרל\"ו פקע\"ח. סה\"מ מלוקט ו' ע' שמה."],["465","462","<b>שבת אותיות תשב</b>: ראה יפה תואר לב\"ר ספכ\"ב<sup data-n=\"e80\">ה</sup>. אגה\"ת ספ\"י. מאמרי אדה\"א דברים ח\"ד ע' א'קפ<sup data-n=\"e81\">ו</sup>. וש\"נ. תו\"ח נח נה, ב ובהערה 20. סה\"מ תרל\"ח ע' קל. וש\"נ. לקמן בג' ההנחות כאן."],["466","463","<b>שבת. . מרמ\"ח מ\"ע</b>: סהמ\"צ להרמב\"ם מ\"ע קנד. קנה. רמב\"ם הל' שבת רפ\"א. רפכ\"ט."],["e16","*","נרשם בצד השמאלי של העמוד מלמטלמ\"ע והמשכו בשולי היריעה:\nשבת אותיות תשבא, החזרת כח הפועל, וחיות העולם ממח'ב לבוש הבינהג, גס ס\"גד ע\"י המתגלה בבינהה כעין שופר, ולכן בשבת אין תוקעי'ו, ומ\"מ עפד\"ת תוקעיןז שלא כל העונג שוה וכמו שבחכ' הגם שגבוה מבינה עכ\"ז הגילוי דעונג בבינה, לכן במקדש הגם שחסר ה'ח מ\"מ תוקעין, ובמדינה גזירה דרבהט, שמיטה שביתה תשובה, חזרת עבדי' כו', עיקר שופר ביובלי תשו'יא תשובו איש אל אחוזתויב, יובל יובל במלופום מלמעלמ\"ט ומלמטה למעלה בד\"ה מקוששיג, והכל ל' חזרהיא, וא\"כ תשו' ומע\"טיד, י\"ל שכשהמעשים הם טובי' שמאירי' זהו תשו' החזרת הניצוץ, או י\"ל תשו' אהוי\"ר גדפיןטו, וכן כ\"י בתשובהטז החזרת הניצוצות ע\"י שמשיב נפשו כו', וכ\"ז הוא כשלא פגם כלל שג\"ז הוא אני לדודייז ע\"י תרי\"ג מצותיח ועי\"ז ודודי לייז, אבל כשפגם צ\"ל תשו' מעומקא כו' ממעמקי' ב' עומקי'יט תעלומות לבכ, עי\"ז נמשך ודודי לי החזרת פב\"פ, וזהו ע\"י שופר צעקה בקרן בהמה אדם ובהמה ערומים בדעתכא, ערום בירור נחשכב, וכ\"ז הוא לחיי הגוףכג היינו הנפש שמחי' הגוף שיוכל לסגל מעש\"ט, דין הנשמות הוא לאח\"מכד כמ\"ש בהגמ\"יכג, דין דלע\"ל שופר גדול, והיינו לאחר בירור קול גדול דמ\"ת, דין דנשמה עסקת בתו' שזהו תחילת דינוכה, וכשמזדכך מזה אזי טל תחי' הוא טל תו' יהי' ע\"י שופר גדול כי מ\"ת הי' שופר מקו ימין ולע\"ל גם שמאל יתברר והי' ביום ההוא יתקעכו, והיינו ע\"י בירור והי' ה' לי לאלקי'כז, ולכן נטל שיחתן ועשאן מפתח לגאולתם ש\"בכח.\n\n<b>ה</b>  ושם: שבת מלשון תשובה.\n\n<b>ו</b>  ראה שם ע' א'קפג הטעם ששבת אותיות תשב בלא ה\"א.\nשבת אותיות תשב: ראה הערה 462\nשבת. . וחיות העולם ממח': ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערות 382-383.\nממח'. . הבינה: ראה זהר רע\"מ פינחס רכט, סע\"ב. פרדס שעה\"כ שכ\"ג, פי\"ג מערכת מחשבה.\nגס סג: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ערבים עלי דברי דודיך הערה 72.\nע\"י המתגלה בבינה: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. תו\"ח לך פא, ב. ביאוה\"ז להצ\"צ אחרי ע' שסד.\nבשבת אין תוקעי': ר\"ה כט, ב.\nעפד\"ת תוקעין: ר\"ה שם. ראה לקו\"ת ר\"ה נז, ב ואילך.\nשחסר ה': יומא כא, ב. ראה לקו\"ת שם נז, ג.\nגזירה דרבה: ר\"ה כט, ב.\nעיקר שופר ביובל: ראה ר\"ה ל, א. לקו\"ת ר\"ה ס, ב.\nתשו'. . ל' חזרה: ראה לעיל הערה 454.\nתשובו איש אל אחוזתו: בהר כה, יג.\nיובל יובל במלופום. . בד\"ה מקושש: לקו\"ת שלח מב, ד.\nתשו' ומע\"ט: אבות פ\"ד, מי\"ז.\nאהוי\"ר גדפין: ראה לעיל הערה 79.\nכ\"י בתשובה: ראה לעיל הערה 451.\nאני לדודי. . ודודי לי: ראה לעיל הערה 336.\nתרי\"ג מצות: ראה לעיל הערה 61.\nממעמקי' ב' עומקי': תהלים קל, א. ראה גם לקמן מאמר ד\"ה ושאבתם מים פ\"ג. מאמרי אדה\"א קונטרסים ס\"ע שט ואילך. וש\"נ.\nתעלומות לב: תהלים מד, כב. ראה גם לקמן מאמר ד\"ה ושאבתם מים שם. מאמרי אדה\"א שמות ח\"ב ע' שצב. וש\"נ. שע\"ת ז, א ובהערה 3. תו\"ח בא ח\"א קו, ב. וש\"נ. סה\"מ תרל\"ח ע' תעא.\nאדם ובהמה ערומים בדעת: תהלים לו, ז. ראה חולין ה, ב. לקו\"ת בחוקותי נ, רע\"ג.\nערום בירור נחש: ראה אוה\"ת מטות ע' א'שמג.\nלחיי הגוף. . בהגמ\"י: ראה גם לקמן הערה 568.\nדין הנשמות הוא לאח\"מ: רמב\"ן בשער הגמול בתחלתו (כתבי הרמב\"ן ח\"ב ע' רסה).\nעסקת בתו' שזהו תחילת דינו: ראה קדושין מ, ב. שו\"ע אדה\"ז הל' ת\"ת פ\"ד, ה\"ז.\nוהי' ביום ההוא יתקע: ישעי' כז, יג.\nוהי' ה' לי לאלקי': ויצא כח, כא.\nנטל שיחתן. . ש\"ב: ב\"ר פ\"ע, ו."]]],[2000480125,"מ\"ע<sup data-n=\"467\">464</sup> בפ\"ע כו', אך הנה פי' וענין מה ששבת הוא אותיות תשב שהו\"ע החזרת המוחין למקורם ושרשם כו', והענין הוא דכתי' ששת ימים עשה<sup data-n=\"468\">465</sup> וגו', פי' ששת ימים שהששת ימים עצמן ירדו ונשפלו בבחי' העשייה ולכן לא נא' בששת ימים כ\"א ששת ימים מטעם הנ\"ל, ועד\"מ אדם העושה איזה מלאכה הנה בשעת מעשה המלאכה ידיו הם העושים את המלאכה, והמוחין הם טרודים לעיין בעיון השכלי איכות ומהות המלאכה<sup data-n=\"469\">466</sup> בכמותה ואיכותה וכן כל האברים הנצרכים למלאכה זו עד\"מ העין לראות מה שעושה, והאוזן לשמוע בכ\"ד הצריכים שמיעת האוזן במלאכה דקה כמו ששומעים הילוך המ\"ש<sup data-n=\"470\">467</sup> וכדומה בכל הדברים שאופן א' מנהיג חבירו כו', וא\"כ בעת עשיית דבר המלאכה כל כחות הנ\"ל הם טרודי' בהמלאכה ההיא שענין בחי' הטרדא הוא ההשפלה ממקומם להיות מושפלים בהדבר שעושה כו', וכל מלאכה שצריכה עיון א\"א בשעת מעשה לחשוב בשכל אחר בשעת מעשה וכן א\"א להביט בעינו<sup data-n=\"471\">468</sup> בד\"א ולשמוע דבר אחר כו', אבל לאחר שכבר גמר מלאכתו עולה שכלו ומדותיו שהם הכוסף והתאוה להדבר שעושה כו' למקורם ושרשן, וכשהוכשר בעיניו מלאכתו שעשה אז מתענג ממנה כשרואה בעין הגשמי",[["467","464","<b>התשובה שהיא מ\"ע</b>: ראה סהמ\"צ להרמב\"ם מ\"ע עג. רמב\"ם הל' תשובה רפ\"א. לקו\"ש ר\"ה כרך ד ע' 1144 ובהערה 5. משפטים כרך ו ע' 329. קדושים כרך יז ע' 210 ואילך ובהערה 40. נשא כרך לח ע' 18 ואילך. סה\"מ תרל\"ח ע' שז. וש\"נ."],["468","465","<b>ששת ימים עשה</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 32."],["469","466","<b>והמוחין. . המלאכה</b>: בהמשך יונתי הנדפס ליתא. ואולי נשמט מפני תיבות הדומות: המלאכה. . המלאכה."],["470","467","<b>המ\"ש</b>: המורה שעות."],["471","468","<b>בעינו</b>: בהמשך הנדפס: בעיניו."]]],[2000480126,"ובעין השכל את טיב הציור ונקיות המלאכה שעשה כו', ועד\"ז יובן למעלה הגם שלא בעמל ולא ביגיעה<sup data-n=\"472\">469</sup> ברא הקב\"ה את עולמו כ\"א במאמר וברוח פיו כו', עכ\"ז זהו מפני שדבורו של הקב\"ה חשיב מעשה<sup data-n=\"473\">470</sup>, ומאחר שחשיב מעשה ממילא נמצא בו כל בחי' הפרטיות שיש בבחי' המעשה כו' שהוא מה שארז\"ל בעשרה דברים ברא הקב\"ה<sup data-n=\"474\">471</sup> את עולמו בחכ' ובתבונה ובדעת בכח ובגערה כו', וכמ\"ש ה' בחכ' יסד ארץ כונן<sup data-n=\"475\">472</sup> כו' בדעתו<sup data-n=\"476\">473</sup> כו', והגם כי ששת ימים עשה כנ\"ל, ושי\"ב הם ששה מדות עכ\"ז הנה נודע &lt;32&gt;\nּ כי בתיקון כל מדה כלולה מע\"ס<sup data-n=\"477\">474</sup>, ונמצא כי במדות יש ג\"כ בחי' המוחין שז\"ע בחי' מוחין שבמדות, שעם היות בחי' המוחין אלו אינם שוים לבחי' מוחין בעצם עכ\"ז הם למיניהם שהרי הם בחי' מוחין ולא מדות אלא שהם מוחין שבמדות, ועכ\"ז נושאים עליהם שם מוחין דוקא, וכמארז\"ל בראשית נמי מאמר הוא<sup data-n=\"478\">475</sup> הנה נודע כי בראשית הוא בחי' חכ'<sup data-n=\"479\">476</sup> כמ\"ש ראשית חכ'<sup data-n=\"480\">477</sup>,",[["472","469","<b>שלא בעמל ולא ביגיעה</b>: ראה ב\"ר פ\"ג, ב. ספ\"י."],["473","470","<b>שדבורו. . חשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח."],["474","471","<b>בעשרה דברים ברא הקב\"ה</b>: ראה חגיגה יב, א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וביום הביכורים הערה 41."],["475","472","<b>ה' בחכמה יסד ארץ כונן</b>: משלי ג, יט."],["476","473","<b>בדעתו</b>: משלי שם, כ."],["477","474","<b>כל מדה כלולה מע\"ס</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א. לקו\"ת מטות פז, ב."],["478","475","<b>בראשית נמי מאמר הוא</b>: בראשית א, א. ר\"ה לב, א."],["479","476","<b>בראשית. . חכ'</b>: ראה רקאנטי ר\"פ בראשית. מאמרי אדה\"א בראשית ע' א. וש\"נ."],["480","477","<b>ראשית חכמה</b>: תהלים קיא, י."]]],[2000480127,"וכמש\"ת ת\"י בחוכמתא<sup data-n=\"481\">478</sup>, ונמצא כי בששת ימי בראשית היו בחי' מוחין אלו מושפלים בעשיית כל הדברים למיניהם שנתהוו בדרך בריאה יש מאין דבר מלא דבר<sup data-n=\"482\">479</sup> בששת ימים אלו, ובבא יום השבת כשקידש היום ולילו עמו (שהיתה ג\"כ יום כמ\"ש במד\"ר ל\"ו שעות שמשה אותה האורה<sup data-n=\"483\">480</sup>, לכן נק' קידש היום) שבת מכל מלאכתו<sup data-n=\"484\">481</sup>, פי' וענין שביתה זו הוא החזרת המוחין והמדות למקורן כמו קודם שנשפלו, שהרי אינו שייך לומר שביתה כאדם השובת ממש בגשמיות שעמל תחלה ואח\"כ שבת מעמלו, אבל הקב\"ה לא בעמל ולא ביגיעה אלא במאמר כו' השביתה היא מן הדבור שפסק מלדבר בהויות הדברים שנתהוו, ונמצא מובן שבשי\"ב שהאיר<sup data-n=\"485\">482</sup> הדבור האיר בו המדות שבהן מלובש המוחין, וכשהפסיק מלדבר חזרו המדות והמוחין לשרשן ומקורן, וה\"ז כאדם שפוסק מלדבר שא\"צ להעמיק בדעתו איך לדבר, ועכ\"ז תיכף אחר שביתתו מלדבר חושב במח' במה שדיבר אם בפרטיות השכלת דבריו או בכלליות דבריו, ועד\"ז כששבת הקב\"ה מלדבר שדבורו חשוב מעשה נפסק העשייה בפועל ועלה מדותיו וחכ' מלבוש הדבור ועכ\"ז נשארו בלבוש המח', ומבחי' מח' זו נמשך החיות לעולמות ביום השבת, ועש\"ז נק' שבת לשון שביתה ששבת מכל מלאכתו כמ\"ש כי בו שבת מכל מלאכתו<sup data-n=\"486\">483</sup> כו' וכנ\"ל, ושבת אותיות תשב ע\"ש החזרת המדות ומוחין למקורן, ומה כתיב אחר ששבת<sup data-n=\"487\">484</sup> ויברך כו' ויקדש אותו<sup data-n=\"488\">485</sup> שברכו וקדשו, ועד\"ז יובן בענין תשובה באדם שהארת נשמתו המחי' את הגוף הנה היא בדרך ירידה והשפלה שהרי היא חלק אלקה ממעל ועמדה באהוי\"ר לפניו ית' כנ\"ל באריכות, וכשירדה להתלבש בגוף הנה לא כל הנשמה מלובשת בגוף<sup data-n=\"489\">486</sup> כ\"א הארה ומקצת הנשמה מלובשת בגוף שהרי המלאך בשליש העולם עומד וכ\"ש הנשמה שהיא מפנימיות הכלים כמ\"ש בלק\"ת בד\"ה יונתי בחגוי הסלע, וא\"כ הארה זו היא בדרך ירידה והשפלה ולכן כשעומד להתפלל וללמוד היא מתחלת להתעלות ועכ\"ז היא מלובשת ממש אלא שהעלי' היא שמתרוממת, וכן כשעושה מצוה מתרומם נפשו כמ\"ש וצדקה תרומם גוי<sup data-n=\"490\">487</sup>,",[["481","478","<b>ת\"י בחוכמתא</b>: תרגום ירושלמי לבראשית א, א. כ\"ה בכ\"מ בדא\"ח ובתרגום שם: בחוכמא<sup data-n=\"e82\">ז</sup> — סה\"מ מלוקט ג' ע' קסד."],["482","479","<b>דבר מלא דבר</b>: אולי צ\"ל: דבר לא מדבר — ראה סה\"מ תרל\"ח ע' שעא בהערה. ראה גם (לקמן — הנחת כ\"ק אדמו\"ר מהורש\"ב — בחלק הנחותיו) הנחה ד\"ה אני לדודי הב' על יד הערה 55. (בחלק בהנחות) הנחה ד\"ה יפה שעה אחת הא' על יד הערה 55. ד\"ה אני לדודי הב' על יד הערה 45."],["483","480","<b>ל\"ו שעות שמשה אותה האורה</b>: ירושלמי ברכות פ\"ח, ה\"ה. ב\"ר פי\"א, ב. פי\"ב, ו."],["484","481","<b>שבת מכל מלאכתו</b>: נסמן בסמוך הערה 483."],["485","482","<b>שהאיר</b>: בהמשך הנדפס: שהאיר בו. וכנראה נסרך מתיבות אלו שבסמוך בפנים."],["486","483","<b>כי בו שבת מכל מלאכתו</b>: בראשית ב, ג."],["487","484","<b>כתיב אחר ששבת</b>: בראשית שם, ב."],["488","485","<b>ויברך כו' ויקדש אותו</b>: התחלת הכתוב כי בו שבת."],["489","486","<b>לא כל הנשמה מלובשת בגוף</b>: ראה גם (בנוסף להמצויין בפנים) לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 595."],["490","487","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם: צדקה — ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 66].\n\n<b>ז</b>  ראה גם זהר בראשית לא, ריש ע\"ב: בראשית. . כמה דתרגם יונתן בראשית בחכמתא."]]],[2000480128,"וכל המצות נק'<sup data-n=\"491\">488</sup> צדקה כמ\"ש וצדקה כו' כל המצוה, אלא עיקר התשובה היא בלילה כשישן ומפקיד נפשו אצל אביה שבשמים, כמ\"ש בידך אפקיד רוחי, והוא ר\"ת באר<sup data-n=\"492\">489</sup> שכמו הבאר נובע מתתא לעילא כך הנשמה עולה במעלות להפקד בידו של הקב\"ה, שזהו באמת תשובה גמורה שהרוח תשוב אל האלקי' אשר נתנה &lt;33&gt;\nּ וכשמחזירה באיזהו ריוח שהרויחה בירידתה, וכ\"ש שלא נתלכלכה בשום דבר אז היא שואבת לו חיים מלמעלה כמארז\"ל שהנשמה עולה ושואבת לו חיים<sup data-n=\"493\">490</sup> מלמעלה כמו בשבת דכתי' ויברך כו' ויקדש אותו כו'.\n<b></b>קיצור. שבת שביתת והחזרת המוחין למקורן, ועד\"ז הוא בכל לילה שנשמת האדם עולה ושואבת לו חיים מלמעלה כמו בשבת שבירכו וקדשו כו'.\nךא) <b>ויובן</b> זה עוד משמיטה, ששש<sup data-n=\"494\">491</sup> שנים תזרע שדך<sup data-n=\"495\">492</sup> ובשנה השביעית שבת שבתון יהי' לארץ שבת לה'<sup data-n=\"496\">493</sup>, שענין בחי' שביתה זו ה\"ה ג\"כ כמו שביתת השבת בכל שבוע, ששש שנים זהו כמו שש הימים שכמו בכל יום הוא עשיית מלאכה כמ\"ש ששת ימים תעשה מעשיך<sup data-n=\"497\">494</sup> שז\"ע ההיתר על עשיית מלאכה, דאל\"כ מאן דמחוי במחוג<sup data-n=\"498\">495</sup> קמי מלכא קטלא חייב ובאמת לית אתר פנוי מיני'<sup data-n=\"499\">496</sup> ומכה\"כ<sup data-n=\"500\">497</sup>, ואת השמים ואת הארץ אני מלא<sup data-n=\"501\">498</sup>, ואם לא שהתיר לנו הכתוב עשיית מלאכה לא הי' שום הוראת היתר בעשיית מלאכה, ובשנה השביעית שבת שבתון שתשבות הארץ מחרישתה וזריעתה וצמיחתה, שאז היא בבחי' תשובה שכחות המלובשים בה שבים לשרשן ואינם בבחי' ירידה והשפלה, ועוד יותר הוא ביובל שנת החמשים שנה<sup data-n=\"502\">499</sup>",[["491","488","<b>נק'</b>: בהמשך יונתי הנדפס: נק' בשם."],["492","489","<b>בידך אפקיד רוחי והוא ר\"ת באר</b>: תהלים לא, ו. ראה פע\"ח שער ק\"ש שעהמ\"ט שט\"ז, פ\"ב. פ\"י. שעה\"כ ענין דרושי הלילה דרוש י. ספר הגלגולים פ\"ח. משנת חסידים וסידור האריז\"ל במקומו. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' נט־ מאמרי אדה\"א דברים ח\"ד ע' א'רסה־ הנחות תקע\"ז ע' קפה־ תו\"ח וישב רא, א־ שער האמונה פב, א־ שע\"ת נו, א ובהנסמן בהנ\"ל."],["493","490","<b>שהנשמה עולה ושואבת לו חיים</b>: ב\"ר פי\"ד, ט. ראה גם פדר\"א פי\"ב<sup data-n=\"e83\">ח</sup> וברד\"ל שם."],["494","491","<b>ששש</b>: בהמשך הנדפס: שש."],["495","492","<b>ששש שנים תזרע שדך</b>: בהר כה, ג."],["496","493","<b>ובשנה השביעית. . שבת לה'</b>: בהר שם, ד."],["497","494","<b>ששת ימים תעשה מעשיך</b>: משפטים כג, יב. ראה גם סידור שער המילה קמה, ד ואילך. סהמ\"צ להצ\"צ ע' ח. אוה\"ת לך כרך ד ע' תשכ ס\"ד. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' קמו. ע' רסה ואילך. סה\"מ תר\"ל ע' רנו ואילך. תרל\"ב ח\"א ע' ס ואילך. המשך מים רבים תרל\"ו ר\"פ פ\"ו. סה\"מ תרע\"ח ע' קעג ואילך. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 81. (בחלק ההנחות) בהנחה כאן על יד הערה 100 (ושם הובא הכתוב: ששת ימים תעבוד — תשא לד, כא)."],["498","495","<b>מאן דמחוי במחוג</b>: ראה חגיגה ה, ב."],["499","496","<b>לית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר מא, א. שם בהוספות נב, ג."],["500","497","<b>ומכה\"כ</b>: ישעי' ו, ג."],["501","498","<b>ואת השמים. . מלא</b>: ירמי' כג, כד. ראה תניא פמ\"ח. תו\"ח בשלח ח\"א קסו, ג. וש\"נ."],["502","499","<b>ביובל שנת החמישים שנה</b>: בהר כה, יא.\n\n<b>ח</b>  ואולי כצ\"ל בסה\"מ מלוקט ב' ע' רסז הערה 35. ראה לקו\"ש ואתחנן כרך כט ע' 32 הערה 40."]]],[2000480129,"שהיא השביתה שהשדות חוזרים לבעליהן וכמ\"ש תשובו איש אל אחוזתו<sup data-n=\"503\">500</sup>, שזהו כמו התשובה שהוא החזרה לבעליהן שזהו כמו למקורן ושרשן, ועד\"ז יש בכ\"י שענין השינה הוא שתשוב הנפש למקורה ושרשה הראשון בחי' אוא\"ס ב\"ה חיי החיים כו' וע\"ז הוא שארז\"ל יפה שעה א' בתשו' ומעש\"ט בעוה\"ז<sup data-n=\"504\">501</sup>, פי' וענין תשובה זו הוא לשון תשוב שהוא פי' החזרה, וה\"ז אות ומופת על המעשים שהם טובים כו'.",[["503","500","<b>תשובו איש אל אחוזתו</b>: בהר שם, יג."],["504","501","<b>בעוה\"ז</b>: ניתוסף בפנים ע\"פ המשך יונתי הנדפס."]]],[2000480130,"<h3>[ובחודש השביעי] ויובן ענין הטוב</h3>\n<b>ר\"ה</b>\n<b>ויובן</b> ענין הטוב<sup data-n=\"505\">502</sup> הזה מענין ההפרש שבין אבנים טובות לאבנים פשוטים ששניהם מין דומם ואין שום יתרון לאבן הטוב על האבן הפשוט שיעלה להיות מסוג אחר כמו הצומח גם הפחות שבמין הצומח ה\"ה סוג אחר ומובדל מבחי' הדומם להיות נושא ע\"ע שם צומח כו', משא\"כ האבן הטוב אין לו יתרון בזה, ומ\"מ ה\"ה יקר מאד שלא בערך נגד האבן הפשוט שזהו מפני בהירותו ומיעוט מציאותו בעולם והטורח הרב וסכנת הנפש שיש במציאותו כו' זהו המרבה שכרו בריבוי שלא בערך נגד האבן הפשוט, ועד\"ז יובן במעשה המצות שענין בחי' המעשה ה\"ה כח היותר אחרון כמו הצומח<sup data-n=\"506\">503</sup> שהוא בחי' היותר אחרונה, ועכ\"ז מעשה גדול לפי גודל מעלת בחי' הכפיה<sup data-n=\"507\">505</sup> שיש בו, מל' גט מעושה<sup data-n=\"508\">506</sup>, או מעשין על הצדקה<sup data-n=\"509\">507</sup> כמ\"ש",[["505","502","<b>ויובן ענין הטוב</b>: מכאן מתחיל מאמר הח' מהמשך יונתי (הכולל פרקים כא<sup data-n=\"e84\">א</sup>-כב).\nלקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) נדפס א) רשימת ראשי פרקיםב ממאמר דידן<sup data-n=\"e85\">ג</sup>. ב) הנחת<sup data-n=\"e86\">ב</sup> כ\"ק אדמו\"ר מהורש\"ב ממאמר זה ”נכתב בשנת תרמ\"ב כפי ששמעתי מר\"ן מוויליז\".\nבמאמר זה<sup data-n=\"e87\">ד</sup> נאמר אז אפילו א צדיק גמור וואס ער איז מתבטל מתלמוד תורה מחמת חלישות הגוף דארף ער טאן תשובה שלימה מעומקא דלבא (משיחת שמח\"ת תרצ\"ה<sup data-n=\"e88\">ה</sup>). ס' התולדות כ\"ק אדמו\"ר מהר\"ש הוצאת תש\"ז ע' 53."],["506","503","<b>הצומח</b>: אוצ\"ל: הדומם."],["507","505","<b>מעשה. . הכפיה</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת הב' ובהערה 14."],["508","506","<b>גט מעושה</b>: גיטין פח, ב (במשנה)."],["509","507","<b>מעשין על הצדקה</b>: ב\"י לטור יו\"ד סרמ\"ח. ראה לקו\"ש ל\"ג בעומר כרך יב ע' 238 ובהנסמן שם.\n\n<b>א</b>  חלק מפרק כא נכנס בדרוש ומעתה כו' אני לדודי ועלי תשוקתו (פ' נצבים תר\"מ).\n\n<b>ג</b>  אלא ששם נרשם בהנחה זו גם פכ\"ד מההמשך.\n\n<b>ב</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>ד</b>  כנראה הכוונה לפכ\"ג על יד הערה 584 — והוא המאמר שנדפס לאח\"ז שנרשם עליו שנאמר מוצאי ר\"ה. ואולי הכוונה שבעת אמירת הדרוש נאמר זה בהמאמר דר\"ה. אלא שבהכתב נרשם זה בפכ\"ג. אבל גם לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב לא נרשם זה במאמר דר\"ה. וראה בהכותרת שם נעתקה גם כאן בפנים ההערה.\n\n<b>ה</b>  נדפס בלקוטי דיבורים ח\"א ע' קפג."]]],[2000480131,"מזה בד\"ה ושננתם באריכות<sup data-n=\"510\">504</sup>, ואמנם כשעושה מעהמ\"צ בקרירות בדרך מצות אנשים מלומדה<sup data-n=\"511\">508</sup>, דהיינו שמניח תפילין מפני שיודע מקטנותו שאביו הרגילו לילך בבקר לביהכנ\"ס וללבוש טו\"ת ולהתפלל, אמנם מתפלל הוא &lt;34&gt;\nּ במהירות גדול עד שאינו שומע מה שהוא מדבר כלל ומחמת רוב רגילותו באותיות ותיבות התפלה ה\"ה שגור בפיו כ\"כ עד שא\"צ לחשוב בהן כלל, אשר ע\"כ יקרה שא\"י באיזהו זמר או פסוק הוא עומד, וכן עטיפת הטלית ש\"מ<sup data-n=\"512\">509</sup> והנחת תפילין הוא ע\"צ<sup data-n=\"513\">510</sup> ההרגל ואינו זוכר כלל שמונחים על ראשו ולכן יקרה באנשים רבים שאינם מרגישים כלל שהתפילין אינם מונחי' על מקומן וכהנה רבות בכל פרטי המצות אפי' בנתינת צדקה שזה הוא מרגיש אבל אינו מקיים כמ\"ש ואל ירע לבבך<sup data-n=\"514\">511</sup> בתתך לו, ואשר הוא נותן זהו מפני כי א\"א באו\"א שחבירו נמנה לדבר מצוה והוא לא ימנה<sup data-n=\"515\">512</sup> כו', או שא\"ד המכריחו כו', שההכרח זו עצמו הי' טוב שהי' בכלל אתכפיא אם לא הי' מרע לבבו בנתינתו, אבל כשהרע לבבו ה\"ז אינו כדבעי במצות הצדקה וגמ\"ח, וכן בשארי מצות, וע\"ז הוא שאה\"כ כי פנו אלי עורף<sup data-n=\"516\">513</sup> פי' שהגם במה שפנו אלי דהיינו בהלכו לבהכנ\"ס ומתעטף בציצית ולובש תפילין ומתפלל שזהו מה שפונה אלי, כי בעת שהוא עוסק במו\"מ בהלכו בשוק וכדומה ה\"ה משוקע בהבלי עולם, וכשמכוין בכדי שירויח שיוכל לפרנס א\"ע וב\"ב שיוכל לעבוד את הבורא ה\"ז טוב, אבל ראיתי בני עלייה כזו ומועטי' המה<sup data-n=\"517\">514</sup>, כ\"א שטרוד וקשור במוחו ולבו עד ששוכח על הכל כו', ונמצא כי באופן נורא כזה ה\"ה רחוק בתכלית מה' עושיהו, כ\"א בעת שהולך לבהכנ\"ס כנ\"ל שזהו מה שפונה אליו ית' כו' מ\"מ ה\"ה פונה עורף ולא פנים, פי' פנים הוא כמו אדם המדבר עם זולתו ומסביר לו פנים ומדבר בנחת בכדי שיקובלו דבריו ושיראה זולתו שמחשיבו כו', משא\"כ עורף הוא כאדם הנותן לחבירו בחי' המותרות שלו ובהכרח כמאן דשדי בתר כתפוי<sup data-n=\"518\">515</sup> כו', כך הבא לבהכנ\"ס ומחפז בכל מיני חיפוזים למהר להתפלל שאינו ממתין עד שיקבצו עשרה אנשים או שדוחק את כולם שימהרו כמוהו כו', ומתפלל במהירות מאד ואינו שומע כלל וכנ\"ל ה\"ז אות ומופת שמחמת הרגילו מוכרח להתפלל, אבל העיקר אצלו מה שצריך לעשות אח\"כ, רק שא\"א כ\"א שיתפלל תחלה כו', זהו מה שצווח הנביא שהגם כי פנו אלי אבל זהו רק בבחי' עורף לבד בחי' אחוריי' וחיצוני' כו', שמעשה המצות כאלו ה\"ז אינם טובים כלל, שא\"א לכחד ולומר שאין זה מצוה ח\"ו, כ\"א שעושה מצוה ולא כמוטל",[["510","504","<b>מעשה גדול. . בחי' הכפיה. . בד\"ה ושננתם באריכות</b>: ראה סה\"מ תרל\"ו ע' רפט ואילך. ע' תקלח. ריש ע' תקמא."],["511","508","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם תניא פל\"ט (נג, ב). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי'. . נביאים וכתובים הערה 12."],["512","509","<b>ש\"מ</b>: של מצוה."],["513","510","<b>ע\"צ</b>: על צד."],["514","511","<b>ואל ירע לבבך</b>: ראה גם לקו\"ת שה\"ש מד, ב־ לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי הב' על יד הערה 29 [ושם: אל]. סה\"מ תרכ\"ז ע' קצ. תרכ\"ח ע' קז (ב\"פ). פ' ראה טו, י [ושם: ולא]."],["515","512","<b>שחבירו נמנה לדבר מצוה והוא לא ימנה</b>: ראה ברכות כו, סע\"א."],["516","513","<b>כי פנו אלי עורף</b>: ירמי' ב, כז. ראה גם לעיל הערה 423."],["517","514","<b>ראיתי בני עלייה. . ומועטי' המה</b>: ע\"פ סוכה מה, ב."],["518","515","<b>כמאן דשדי בתר כתפוי</b>: ראה תניא פכ\"ב."]]],[2000480132,"עליו שזהו אינו טוב, משא\"כ כשלובש טו\"ת לקיים מצות בוראו ולשעבד הלב והמוח, ופרטי הכוונות שיש בהם כמ\"ש בכהאריז\"ל, ועצם העשי' צ\"ל בקעומ\"ש דוקא כמ\"ש במ\"א בד\"ה ועתה יגדל נא, וביאורו<sup data-n=\"519\">516</sup>, ובכלל הכוונה הוא להעלות הקלף וצמר הציצית והם יעלו את האדם הנושאם ועושה אותם למצוה כו' שזהו ענין תשובה להשיב הניצוץ שבצמר וקלף הבהמה ולהעלות נפשו כו' אז המעשים דמעשה המצות הם טובים כו', &lt;35&gt;\nּ וכן בשארי המצות כו' וע\"ז הוא שכיוונו רז\"ל באמרם תשובה ומעש\"ט שע\"י התשובה נעשו המעשים דמעהמ\"צ טובים ומאירים<sup data-n=\"520\">517</sup> כבהירת האבן הטוב כו' ועי\"ז הוא כ\"י בתשובה שכ\"י היותו ה\"ה מקיים מצות, וכן בעולת התמיד בתפלה שכנגד תמידין תקנו<sup data-n=\"521\">518</sup> כשמתפלל ושב לה' בכל לבו<sup data-n=\"522\">519</sup> ובכל נפשו ובכל מאודו הרי ע\"י תפלה זו מתעלים כל מעהמ\"צ שעשה ביום ההוא וכמ\"ש בד\"ה את שבתותי תשמורו הנדפס בלק\"ת<sup data-n=\"523\">520</sup>.\n<b></b>קיצור. שמיטה ויובל זהו ג\"כ תשובה וכמו\"כ בכל השבת נפשו בפקדון לאביו שבשמים, וכשמשיבה בטוב ז\"ע תשו' ומע\"ט שע\"י התשובה שמעלה הניצוצות ונפשו עי\"ז הוא אות ומופת שהמעשים הם טובים, וזהו כ\"י בתשובה כו'.\nךב) <b>וביאור</b> הענין יובן ע\"פ מ\"ש רז\"ל במד\"ר<sup data-n=\"524\">521</sup> בראשית פי\"ד<sup data-n=\"525\">522</sup> ע\"פ ויפח באפיו נשמת<sup data-n=\"526\">523</sup> חיים<sup data-n=\"527\">524</sup>, לפי שבעוה\"ז בנפיחה לפיכך מת, אבל לע\"ל<sup data-n=\"528\">525</sup> בנתינה שנא' ונתתי רוחי בכם וחייתם<sup data-n=\"529\">526</sup>, ולבא לבחי' זו זהו ע\"י תשובה וכמ\"ש והרוח תשוב אל האלקי' אשר נתנה, אומרו נתנה דוקא לפי ששרש ענין ירידת הנשמה גם עכשיו בעוה\"ז היא בנתינה ולכן א\"א אלקי נשמה שנתת בי<sup data-n=\"530\">527</sup> נתת דוקא, רק שבגוף שאינו מאיר כ\"א הארת הנשמה לבד לכן אומרים אח\"כ ואתה נפחת<sup data-n=\"531\">528</sup> וכמ\"ש ויפח באפיו, ומפני שהיא בנפיחה הארה מועטת כאדם הנופח שנופח רק דבר מועט לכן מת, אבל ע\"י התשובה שהיא החזרת הנפש בכל לילה מליאה מצות כרמון<sup data-n=\"532\">529</sup>, וכאשר התשובה היא כדבעי אזי מובן כי מעשיה<sup data-n=\"533\">530</sup> שעשה בקיום התומ\"צ",[["519","516","<b>העשי' צ\"ל בקעומ\"ש. . בד\"ה ועתה יגדל נא וביאורו</b>: לקו\"ת שלח לט, א. מ, א."],["520","517","<b>תשובה ומעש\"ט. . ומאירים</b>: אבות פ\"ד, מי\"ז. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה אחת הג' על יד הערה 88. ד\"ה ובחודש השביעי הב' על יד הערה 48. שע\"ת עב, ד ובהערה 26. פלח הרמון תזריע ע' קסד."],["521","518","<b>בתפלה שכנגד תמידין תקנו</b>: ראה ברכות כו, ב. לקו\"ת פינחס עז, ג."],["522","519","<b>לה'. . לבו</b>: בהמשך יונתי הנדפס: אל ה'. . לבבו."],["523","520","<b>בד\"ה את שבתותי. . בלק\"ת</b>: בהר מא, א."],["524","521","<b>במד\"ר</b>: בהמשך הנדפס: ובמד\"ר."],["525","522","<b>במד\"ר בראשית פי\"ד</b>: ס\"ח. ראה לקו\"ת האזינו עב, ב. המשך תער\"ב ח\"ב ע' תשעח."],["526","523","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["527","524","<b>נשמת חיים</b>: בב\"ר ובלקו\"ת ליתא."],["528","525","<b>לע\"ל</b>: שם: לעתיד."],["529","526","<b>ונתתי רוחי בכם וחייתם</b>: יחזקאל לז, יד."],["530","527","<b>אלקי נשמה שנתת בי</b>: ברכת אלקי נשמה (מברכות ס, ב)."],["531","528","<b>ואתה נפחת</b>: ראה גם לקו\"ת כאן. מאמרי אדה\"א בראשית ע' עא. וש\"נ. תו\"ח וארא ח\"א עג, ג ובהערה 77."],["532","529","<b>מליאה מצות כרמון</b>: ע\"פ ברכות נז, א. וש\"נ."],["533","530","<b>מעשיה</b>: בהמשך יונתי הנדפס: מעשיו."]]],[2000480133,"הם טובים כנ\"ל שז\"ע והרוח תשוב כו' אשר נתנה דוקא עי\"ז מאיר מלמעלה בחי' נתינה והוא אשר בגמר הבירורים של הנשמה תשוב להחיות הגוף בבחי' נתינה שיהי' חי וקיים לעולם כו', וע\"ד שארז\"ל נותן בעין יפה נותן<sup data-n=\"534\">531</sup>, שבחי' עין יפה שלמעלה הוא בחי' עינא פקיחא דלא נאים<sup data-n=\"535\">532</sup>, וז\"ע עין לא ראתה<sup data-n=\"536\">533</sup> אלקי' זולתך כו'<sup data-n=\"537\">534</sup>.\n<b>ויובן</b> ענין בחי' והרוח תשוב שבכל לילה נשמת האדם עולה למעלה בעת שישן ועולה להתכלל בשרשה ומקורה למי שזוכה לזה וכמ\"ש מי יעלה בהר ה'<sup data-n=\"538\">535</sup> נקי כפים ובר לבב<sup data-n=\"539\">536</sup> כו', שחשיב במזמור זה דברים כללים שהם ג\"כ אות ומופת על כל מעשה בני האדם אם טוב הם כו', ולכן זהו עבודת האדם בכ\"י להיות בבחי' תשובה לשרשו ומקורו, ובכדי לבוא לבחי' זו בק\"ש באמרו ה' אחד<sup data-n=\"540\">537</sup> למס\"נ באחד<sup data-n=\"541\">538</sup> ולשפוך נפשו לה' בתפלה הקדימו פסוד\"ז קודם התפלה איך שהשמים והארץ וכל אשר בהם אומרים שירה, ואח\"כ ברכת יוצר אור איך שהמלאכים שרפי' ואופנים אומרים שירה ובטלים בתכלית הביטול לפי ערכם שנתהוו מבחי' הדבור<sup data-n=\"542\">540</sup> כמ\"ש במ\"א<sup data-n=\"543\">539</sup> כו', בכדי שעי\"ז תתעורר התשוקה<sup data-n=\"544\">541</sup> מקרב איש ולב עמוק למס\"נ באחד בדביקות ותשוקה נפלאה כו', והנה ההתבוננות לבוא לבחי' תשוקה זו, זהו ע\"י שיתבונן בעצמו איך שהוא אוהב א\"ע ורוצה בטובתו מאד כשמשכיל להבין מה הוא אוהב אם הגוף או הנפש, שא\"א &lt;36&gt;\nּ לומר שאוהב את הגוף שהרי בצאת הנפש מן הגוף מלבד מה שאינו שייך כלל ענין האהבה שמתבטל לגמרי ענין בחי' האהבה הנה לאדם החי מובן בטוב טעם שאינו שייך לאהוב גוף בלתי חי, כ\"א האהבה היא להארת הנפש המחי' את הגוף, וגם ממקומו מוכרח שענין האהבה מכחות הנפש היא, וכשאוהב א\"ע הנה זהו הנפש שהנפש הוא בחי' העצם של הארת האהבה שהיא כח מכחות הנפש כו', וכמו שהוא בגוף ונפש כ\"ה בכל דברים הגשמיים שנבראו בעולם שהאדם אוהב אותם זהו מצד שנהנה מטעמם או מריחם וכדומה שכ\"ז הוא מצד החיות המחי' את הדבר ההיא ולא מבחי' גשם הדבר ההיא כו', וכשיתבונן בזה היטב איך שהוא ית' הוא המחי' ומהוה הכל ובטובו מחדש בכי\"ת מע\"ב שכל מה שנברא ונוצר ונעשה במע\"ב הוא מחדש חיותו בכ\"י תמיד אשר עי\"ז מהוה אותו וכמ\"ש ואתה מחי' את כולם<sup data-n=\"545\">542</sup> א\"ת מחי' אלא מהוה<sup data-n=\"546\">543</sup>, וכולא חד באמת שהחיות",[["534","531","<b>נותן בעין יפה נותן</b>: ראה ב\"ב סה, א. לקו\"ת כאן ובהנסמן במ\"מ לשם."],["535","532","<b>עינא פקיחא דלא נאים</b>: ראה זהר אד\"ר נשא קכט, סע\"ב. הנסמן במאמרי אדה\"א נ\"ך ע' תג."],["536","533","<b>עין לא ראתה</b>: ישעי' סד, ג."],["537","534","<b>כו'</b>: בהמשך הנדפס ליתא. בלקו\"ת כאן הובא המשך הכתוב."],["538","535","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."],["539","536","<b>נקי כפים ובר לבב</b>: תהלים שם, ד."],["540","537","<b>ה' אחד</b>: ואתחנן ו, ד."],["541","538","<b>למס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["542","540","<b>שהמלאכים. . שנתהוו מבחי' הדבור</b>: ראה אגה\"ת פ\"ד. ש\"א ח, ב ובהערה 39."],["543","539","<b>הקדימו פסוד\"ז. . ברכת יוצר אור. . כמ\"ש במ\"א</b>: ראה גם לקו\"ת תצא לה, ד ואילך. סה\"מ תרכ\"ט ע' רפד. וש\"נ."],["544","541","<b>התשוקה</b>: בהמשך הנדפס: התשובה."],["545","542","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["546","543","<b>א\"ת מחי' אלא מהוה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."]]],[2000480134,"מהווהו<sup data-n=\"547\">544</sup> כו', ואי לזאת מה לו לאהוב אם פרט איזה דבר או את בחי' אוא\"ס ב\"ה חיי החיים המחי' ומהוה הכל, ועד\"מ כשאוהב איזה דבר שערב לו הנה אם הי' בא אחד ואומר לו שיש ממין זה עצמו עוד משובח<sup data-n=\"548\">545</sup> יותר שלא בערך הי' מתמלא תאוה לאותו הדבר בתשוקה רבה כ\"ש כשיתבונן שאוא\"ס ב\"ה בחי' חיי החיים הנה הארת דבורו היא אשר מחי' ומהוה כל הנבראים והיצורים והנעשים כ\"ש שצ\"ל בבחי' אהבה ותשוקה לאוא\"ס ב\"ה בכליות<sup data-n=\"549\">*546</sup> הנפש ממש, וכמ\"ש מי לי בשמים<sup data-n=\"550\">546</sup> ועמך לא חפצתי שכל מה שהוא עמך פי' בטל וטפל לך אינו רוצה כלל כ\"א אותך אוא\"ס עצומ\"ה מקור לכל הארה והשפעה כו' וזהו שמע ישראל פי' שמע הוא מל' הסכת ושמע, וישמע שאול, שהוא לשון אסיפה וקיבוץ שיאסוף ויקבץ כל הכחות מכחות הנפש המפוזרים ומלובשי'<sup data-n=\"551\">547</sup> במחשבות ורצונות הזרות שכאו\"א כשעושה חשבון הנפש בינו לבין קונו יודע ומכיר מקומו היטב איך שהוא רחוק בתכלית הריחוק מאלקות אשר בכחו הגדול שניתנה ובנפשו היקרה חלק אלקה ממעל הי' יכול לבוא לדבקה בו אוא\"ס חיי החיים ב\"ה וכנ\"ל, וע\"י העמקת הדעת בהתבוננות הנ\"ל איך שהוא אוהב חיי נפשו כו' עי\"ז יבין היטב איך שתועה בדרך לא לו כלל, ואז ישוב לה' בכל לבו ובכל נפשו וכמשל מי שהולך בדרך והבין בטוב שטעה<sup data-n=\"552\">548</sup> ולא הלך בדרך שצריך לילך כ\"א תועה במדבריות ויערות וא\"י להיכן ילך שיבא על הדרך הישר, שאם מזדמן לו אז אחד הולך לנגדו והראה לו הדרך ילך בה דרך הישר מתמלא עונג גדול ומחזיק טובה מאד להאיש שהראה לו הדרך הישר, ועד\"ז יובן שההולך ברצונותיו הזרות עד שמוחו ולבו נעשים שממה כמדבר, וכשמתבונן כנ\"ל ההתבוננות זהו כמו האיש שמראה לו דרך הישר, שצ\"ל אצלו ענג נפלא ממה שבא בדרך הישר דרך ה' לדבקה בו ית' אוא\"ס חיי החיים כו', וזהו שתקנו ק\"ש שעהמ\"ט<sup data-n=\"553\">549</sup> מלבד ק\"ש דשחרית ודערבית, שצ\"ל כנ\"ל בחי' עולת תמיד<sup data-n=\"554\">550</sup> כו' כשבא לשכב עהמ\"ט לישן שמוסר נפשו בפקדון לאבשב\"ש, מלבד שא\"י אם יזכה שיוחזר לו נפשו שצריך לשוב כמו קודם מותו שז\"ע שוב יום אחד לפני מיתתך<sup data-n=\"555\">551</sup>, שקאי על עבודה &lt;37&gt;\nּ של כל היום בג\"פ ק\"ש, הנה קודם שישן צריך האדם לחשוב כל מחשבותיו וכל דבוריו וכל עשיותיו שעשה כל היום מאז עמדו בבקר עד הערב עת השינה וימצא שהלך בחשך וסכל מעשיו ע\"י רצונותיו הזרים, ואז ישוב לה' בכל לבו",[["547","544","<b>וכולא חד באמת שהחיות מהווהו</b>: ראה גם סה\"מ מלוקט ו' ריש ע' צה ובהערה לשם."],["548","545","<b>שיש. . משובח</b>: בהמשך הנדפס: שיש לו ממין זה עצמו משובח עוד."],["549","*546","<b>בכליות</b>: כ\"ה גם בהמשך הנדפס."],["550","546","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לעיל פי\"ד. לקמן מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 153. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול ובהערה 65. תו\"א נח ט, א. ספר המצות להצ\"צ קלח, א<sup data-n=\"e89\">ו</sup>. תו\"ח תצוה ח\"ב שנו, ב. וש\"נ. סה\"מ תרל\"ח ע' מו. וש\"נ. תרס\"ח ע' רנב. סה\"מ מלוקט ו' ע' צט ובהערה 78."],["551","547","<b>ומלובשי'</b>: בהמשך יונתי הנדפס ליתא."],["552","548","<b>לבו. . שטעה</b>: שם: לבבו. . שתועה."],["553","549","<b>ק\"ש שעהמ\"ט</b>: ראה זהר קרח קעח, א. מאמרי אדה\"ז תק\"ע בהוספות (ע' ט) קפד [ג]. וש\"נ. נדפס גם באוה\"ת ואתחנן ע' קסט. לקמן רפכ\"ג."],["554","550","<b>כנ\"ל. . תמיד</b>: ספכ\"א."],["555","551","<b>שוב. . לפני מיתתך</b>: אבות פ\"ב, מ\"י.\n\n<b>ו</b>  ראה גם סה\"מ באתי לגני ח\"ב ע' קג וע' קה. סה\"מ מלוקט ו' ע' קלה. מגדל עז ע' קעג."]]],[2000480135,"ובכל נפשו, וע\"י תשובה זו יעלה כל המעשים הטובים שעשה שז\"ע בתשו' ובמעש\"ט כנ\"ל וע\"י בחי' והרוח תשוב זה אל האלקים אשר נתנה פי' האלקי' דוקא לפי שזבחי אלקים רוח נשברה<sup data-n=\"556\">552</sup> לב נשבר ונדכה, דכה לא נא' כ\"א נדכה<sup data-n=\"557\">553</sup>, והיינו ע\"י ההתבוננות שמתבונן איך שהוא רחוק כו' ואיך שטוב וישר לפני כל מבין ויודע לבא לדבקה בו כו', ואם לעוברי רצונו כך<sup data-n=\"558\">554</sup> לעושי רצונו עאכו\"כ פי' עוברי רצונו הוא ההשפעה הנמשך בעניני העוה\"ז הגשמיי' שהם עוברי רצונו פי' שאינם רצה\"ע כמו המצות שהם רצה\"ע ב\"ה, לעושי רצונו שהוא בחי' התומ\"צ עאכו\"כ שאוא\"ס ב\"ה מתלבש בהם ובהם יש בחי' בעל הרצון שכולל כלל כל הרצונות והנושא ע\"ע בחי' הכלל הזה כו', שהוא אוא\"ס עצומ\"ה שלמעלה מבחי' רצון כללי ג\"כ, וגם ע\"י תשובה זו ארז\"ל במקום שבע\"ת עומדין<sup data-n=\"559\">555</sup> אין צ\"ג יכולים לעמוד שם שהרי גם הצ\"ג צריך שיהי' בבחי' תשובה זו כו' שהוא ענין בחי' ההחזרה והרוח תשוב שהרי בע\"כ הוא חי בחיים הגשמי' ולא ימלט כו', וכמ\"ש כי אין אדם צדיק בארץ ולא יחטא<sup data-n=\"560\">557</sup>, וזהו תכלית ירידת הנשמה בגוף הגשמי בכדי לבוא לבחי' ומדריגת תשובה שע\"ז אמרו נמצא כ\"י בתשובה כו'<sup data-n=\"561\">556</sup>, וזהו ג\"כ שרש ענין השבת ג\"כ שיוחזרו המוחין למקורן, כי בראשית נמי מאמר הוא וכנ\"ל רק מי שטרח בע\"ש יאכל בשבת שצ\"ל הכנה<sup data-n=\"562\">558</sup> בששת ימי החול כו', והוא בחי' השבת שיש בימי החול שהוא התפלה<sup data-n=\"563\">559</sup> שנק' עולת תמיד ע\"י בחי' הק\"ש שמע ישראל לאסוף כל הכחות לבוא לדבקה בו במס\"נ באחד כו', ואז עולת שבת בשבתו<sup data-n=\"564\">560</sup> שבשבת עולים כל העבודה שבששת ימי החול לבחי' שבתו של שבת כו', ועי\"ז יזכה לע\"ל שינתן לו נפשו בנתינה נותן בעין יפה נותן בחי' עין לא ראתה אלקים זולתך כו'.\n<b></b>קיצור. בעוה\"ז בנפיחה, ולע\"ל בנתינה ע\"י והרוח תשוב כו', נתנה דוקא, פי' והרוח תשוב בק\"ש ג\"פ ביום ע\"י התבוננות שאוהב חיי נפשו כ\"ש בחי' אור א\"ס חיי החיים כו', אל האלקים בחי' לב נשבר ונדכה, ע\"י התבוננות, וזהו כ\"י בתשובה כו'.",[["556","552","<b>שזבחי אלקים רוח נשברה</b>: תהלים נא, יט. ראה אגה\"ת פ\"ז. תניא פי\"ז."],["557","553","<b>דכה. . נדכה</b>: ראה גם מאמרי אדה\"ז הקצרים ע' רטו. נדפס בשינויים בלקו\"ת ר\"ה סב, סע\"א<sup data-n=\"e90\">ז</sup> ואילך. אוה\"ת חוקת ע' תתנח. סה\"מ תר\"ל ע' קצא. תרס\"ד ע' רמא. תרע\"ח ע' קיז."],["558","554","<b>ואם לעוברי רצונו כך</b>: ראה מכות בסופה. לקו\"ת בהעלותך לג, ד. שלח מז, א."],["559","555","<b>במקום שבע\"ת עומדין</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. תו\"ח שמות ח\"א מא, א. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח."],["560","557","<b>כי אין אדם. . יחטא</b>: קהלת ז, כ [ושם: אדם אין. בדילוג]."],["561","556","<b>וכמ\"ש. . כו'</b>: בהמשך הנדפס ליתא. ואולי נשמט מפני תיבות הדומות: כו'. . כו'."],["562","558","<b>מי שטרח. . הכנה</b>: ע\"ז ג, א. ביצה ב, ב."],["563","559","<b>השבת שיש בימי החול שהוא התפלה</b>: ראה תו\"א ויקהל פח, א. לקו\"ת האזינו עב, ג. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות ובהערה 23."],["564","560","<b>עולת שבת בשבתו</b>: פינחס כח, י. ראה תו\"א תרומה פ, ב. לקו\"ת בהר מא, א.\n\n<b>ז</b>  ראה גם מפתח ענינים ללקו\"ת מערכת דכא ושם: ”דכא: דסבא (ד. נדכא)\" — תיבת נדכא באל\"ף. ולהעיר מסה\"מ תרפ\"ט ע' 77: ונדכא. אגה\"ת מהדו\"ק ע' תקלא מכת\"י ז ”ונדכא\". אבל באגה\"ת פ\"ז צז, א: ונדכה."]]],[2000480136,"<h3>וזהו אני לדודי</h3>\n<b>מוצאי ר\"ה</b>\nךג) <b>וזהו</b> אני לדודי<sup data-n=\"565\">561</sup> פי' אני לדודי ע\"י קיום המצות והעלאתן ע\"י בחי' תשובה שהוא ההחזרה בבחי' והרוח תשוב אל האלקי' אשר נתנה בק\"ש דשחרית וערבית, וק\"ש שעהמ\"ט לאחר בחי' חשבון הנפש שעושה בינו לבין עצמו במה שבינו לבין קונו ושב לה' בכל לבו כנ\"ל שז\"ע אני לדודי ועי\"ז ודודי לי שמחזיר לו הפקדון שהפקיד אצלו ית' ושואבת לו חיים מלמעלה מבחי' אוא\"ס ב\"ה חיי החיים כו', ועיקר פי' אני לדודי לפי' זה הוא כמ\"ש בילקוט אני לדודי בעוה\"ז ודודי לי בעוה\"ב לפי שבעוה\"ז ימי שנותינו בהם<sup data-n=\"566\">562</sup> שבעים שנה<sup data-n=\"567\">563</sup> ואם בגבורות שמונים כו' זהו הכל לפי ערך הבירורי' שצריך לברר שבשביל זה ירדה נפשו להתלבש בגוף ונה\"ב בכדי להיות בחי' תשו' זו כנ\"ל, ועי\"ז ודודי לי לעוה\"ב שיהי' בנתינה שיהי' חי וקיים לעולם פי' שלא יצטרך להיות בבחי' העלאות כ\"א כמארז\"ל הקב\"ה עושה להם כנפים<sup data-n=\"568\">564</sup> ושטים ע\"פ המים וכמשי\"ת מזה לקמן<sup data-n=\"569\">565</sup> בס\"ד.\n&lt;38&gt;\nּ<b>והנה</b> כמו שהוא בכי\"ת<sup data-n=\"570\">566</sup> בחי' תשובה שבק\"ש שעהמ\"ט, כן הוא בכלליות החיות בכל ערב ר\"ה עם חשיכה<sup data-n=\"571\">567</sup> עולה חיות שנה העברה שנקצבה לפי ערך בחי' העלאת מ\"ן משנה שלפניה, והעלאת חיות זה צ\"ל עולה עם כל מה שפעל בהיותו בעולם בשנה העברה, והיינו כי עיקר דין ומשפט דר\"ה הוא בבחי' חיי הגוף וכמ\"ש בפייט בר\"ה יכתבון<sup data-n=\"572\">569</sup> כו' מי יחי' כו' וכן תיקנו להוסיף בתפלת שמו\"ע זכרינו לחיים כו' זוכר יצוריו<sup data-n=\"573\">570</sup> לחיים ברחמים, וכדומה לפי שהדין דר\"ה",[["565","561","<b>וזהו אני לדודי</b>: מכאן מתחיל מאמר הט' מהמשך יונתי (הכולל פרקים כג-כה).\nראשי פרקים ממאמר זה נרשמו לעיל בשולי היריעה ספי\"ב. פי\"ג. וראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי הא'.\nראה גם לעיל הערה 502."],["566","562","<b>ימי שנותינו בהם</b>: תהלים צ, י. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ספכ\"ט (ובהנסמן שם)."],["567","563","<b>שנה</b>: ניתוסף ע\"פ המשך יונתי הנדפס."],["568","564","<b>הקב\"ה עושה להם כנפים</b>: ראה סנהדרין צב, ריש ע\"ב. ילקוט שמעוני ישעי' מ, לא (רמז תמז). מאמרי אדה\"א בראשית ע' עז. וש\"נ. ס\"ע פז ואילך."],["569","565","<b>וכמשי\"ת מזה לקמן</b>: ההמשך לא נגמר."],["570","566","<b>בכי\"ת</b>: בכל יום תמיד."],["571","567","<b>בכל ערב ר\"ה עם חשיכה</b>: ראה אגה\"ק סי\"ד (קכ, ב. קכא, רע\"א). לקו\"ת ר\"ה נג, ד. לקמן מאמר ד\"ה רני ושמחי על יד הערה 32. המשך וככה תרל\"ז רפפ\"א. סה\"מ תשי\"א ע' 33. סה\"מ מלוקט ה' ע' ה. לקו\"ש האזינו כרך ט ע' 220."],["572","569","<b>בפייט בר\"ה יכתבון</b>: מוסף לימים נוראים קודם קדושת כתר."],["573","570","<b>וכן תיקנו. . זכרינו. . זוכר יצוריו</b>: ראה שו\"ע אדה\"ז הל' ר\"ה סתקפ\"ב, ס\"ו."]]],[2000480137,"הוא לחיי הגוף, והיינו לבחי' החיות שנמשך בחי' הארת הנפש להחיות הגוף, הן ברוחניות והן בגשמיות שכולל גם כל עשיית הטוב שלו בעשיית התומ\"צ בסור מרע ועשה טוב כו', משא\"כ דין הנשמות הוא בצאת הנפש מהגוף<sup data-n=\"574\">571</sup> כמ\"ש בהגמ\"י<sup data-n=\"575\">568</sup>, ואי לזאת דעת לנבון נקל שבעלות החיות למעלה למקור חוצבה אחר שעשה שליחותו מוכרח להראות פעולתו מה שעושה בשליחותו, ולכן כשם שהחזרת הנפש בפקדון שבכל לילה צ\"ל נקי מכל לכלוך ופסולת וכנ\"ל<sup data-n=\"576\">572</sup> בענין בחי' התשו' שבכ\"י, כ\"ש וק\"ו שכלליות החיות שמכל השנה שעולה ונכלל באוא\"ס חיי החיים צ\"ל מנוקה מכל פסולת ולכלוך ודבר זר, שאל\"כ אינו ראוי להעלות כלל לפני ממה\"מ הקב\"ה<sup data-n=\"577\">573</sup>, וכמ\"ש הקריבהו נא לפחתך<sup data-n=\"578\">574</sup> כו'<sup data-n=\"579\">575</sup> הירצך או הישא פניך, וכ\"ש לפני ממה\"מ הקב\"ה, ותשו' זו היא אפי' גם בצ\"ג<sup data-n=\"580\">576</sup> שלא חטא מימיו בפו\"מ ואפי' בהרהור כו', ומ\"מ הנה גם נפש הצ\"ג מלובשת בגוף כו' אי לזאת מחויב כאו\"א לעשות חשבון הנפש מכלליות השנה מה עשה בשנה וידע אינש בנפשו שעם היות שלא פגם ח\"ו בפו\"מ ואפי' הרהור עבירה שה\"ה קשה מעבירה כנ\"ל, מ\"מ ימצא כמה דברים שלא עשה<sup data-n=\"581\">577</sup> לש\"ש, שג\"ז משוקץ ומתועב נגדו ית', שלא אמרו בלימוד התו' והמצות שלא לשמה רק מפני שמתוך שלא לשמה בא לשמה<sup data-n=\"582\">578</sup>, אבל לא שישאר בלא לשמה, ובענוה התירו עוד יותר<sup data-n=\"583\">579</sup> מפני שענוה גדולה מכולם<sup data-n=\"584\">580</sup>, וכמ\"ש בירושלמי פ\"א דשבת, שמה שעשאה<sup data-n=\"585\">581</sup> החכ' עטרה לראשה עשתה ענוה עקב לסוליסה שנא' עקב ענוה יראת ה'<sup data-n=\"586\">582</sup>, מה שבחכ' נא' ראשית חכ' יראת ה', וע' בתוס' בעירוכין דט\"ז רע\"ב, אבל לא בשאר כל המצות כו', וגם אם יברור א\"ע בי\"ג נפות<sup data-n=\"587\">583</sup> ימצא שפ\"א או שתים קרה לו שהי' יכול לעשות מצוה ולא עשה, וכ\"ש בעון ביטול תורה שנמנע ולא עשה שתלה בחלישות גופו<sup data-n=\"588\">584</sup> כו' וכדומה<sup data-n=\"589\">585</sup> במה שיוכל למחות ולא מיחה<sup data-n=\"590\">586</sup>, שצריך לשוב ע\"ז מעומקא דלבא, שפי' תשובה זו היא חרטה ועזיבת<sup data-n=\"591\">587</sup> החטא ולא",[["574","571","<b>דין הנשמות הוא בצאת הנפש מהגוף</b>: רמב\"ן בשער הגמול בתחלתו (כתבי הרמב\"ן ח\"ב ע' רסה)."],["575","568","<b>עיקר דין ומשפט דר\"ה. . חיי הגוף. . בהגמ\"י</b>: רפ\"ג מהל' תשובה בשם הרמב\"ן<sup data-n=\"e91\">א</sup> הובא בלקו\"ת<sup data-n=\"e92\">ב</sup> ר\"ה נט, ב<sup data-n=\"e93\">ג</sup>. וראה גם לקו\"ש ר\"ה כרך יט ע' 292 ואילך. (לקמן בחלק ההנחות) הנחה ד\"ה שובה ישראל הב' על יד הערה 60 ואילך."],["576","572","<b>וכנ\"ל</b>: פכ\"ב."],["577","573","<b>ממה\"מ הקב\"ה</b>: ברכות כח, ב."],["578","574","<b>הקריבהו נא לפחתך</b>: מלאכי א, ח."],["579","575","<b>כו'</b>: כ\"ה גם בהמשך יונתי הנדפס."],["580","576","<b>ותשו'. . גם בצ\"ג</b>: [תיבת ”גם\" ניתוספה בין השיטין. בהמשך הנדפס ליתא]. ראה גם המשך מים רבים תרל\"ו פקל\"ה."],["581","577","<b>עשה</b>: בהמשך הנדפס ניתוסף: בשנה. ואולי תיבת בשנה נסרחה מלעיל שו\"ה הנפש."],["582","578","<b>בלימוד. . בא לשמה</b>: ראה פסחים נ, ב. לקו\"ש תולדות כרך ג ע' 781. וש\"נ. ויגש כרך ה ע' 245 הערה 37. עקב כרך יט ע' 122 הערה 15. פיה\"מ פו, ג. תו\"ח תצוה ח\"ב שמב, א ואילך."],["583","579","<b>ובענוה התירו עוד יותר</b>: ראה המצויין בסמוך בפנים לתוס' עירוכין דט\"ז, ריש ע\"ב."],["584","580","<b>שענוה גדולה מכולם</b>: ע\"ז כ, ב."],["585","581","<b>בירושלמי פ\"א דשבת שמה שעשאה</b>: ראה שם סה\"ג. ראה גם מאמרי אדה\"ז הקצרים ע' שסג."],["586","582","<b>עקב ענוה יראת ה'</b>: משלי כב, ד."],["587","583","<b>בי\"ג נפות</b>: מנחות סו, א־ עו, ב (במשנה — בנוגע לעומר)."],["588","584","<b>בעון ביטול תורה. . בחלישות גופו</b>: ראה גם לעיל הערה 502."],["589","585","<b>וכדומה</b>: בהמשך הנדפס ניתוסף: כו'."],["590","586","<b>במה שיוכל למחות ולא מיחה</b>: ראה תניא פ\"א<sup data-n=\"e94\">ד</sup> ובמ\"מ הגהות והע\"ק שם טז, ב. שו\"ע אדה\"ז הל' משא ומתן סקנ\"ו, ס\"ז. לקו\"ש בא כרך ו ע' 274 ואילך. פקודי כרך יא ע' 179 הערה 22."],["591","587","<b>היא חרטה ועזיבת</b>: בהמשך הנדפס: הוא החרטה הוא עזיבת.\n\n<b>א</b>  בשער הגמול בתחלתו (כתבי הרמב\"ן ח\"ב ע' רסה).\n\n<b>ב</b>  הובא גם לעיל בשולי היריעה לפ\"כ אות כג ע\"ש. אוה\"ת בראשית ח\"א ע' יט. מלכים ע' סב. סה\"מ מלוקט ד' ע' רצב.\n\n<b>ג</b>  ראה גם סה\"ש תנש\"א ח\"א ע' 36 בהערה 68. ח\"ב ע' 869 בשולי היריעה.\n\n<b>ד</b>  לקוטי לוי יצחק הערות לתניא שם."]]],[2000480138,"ישוב לכסלה<sup data-n=\"592\">588</sup> עוד, ועי\"ז יהי' תשובתו פי' לשון החזרה הוא החזרת החיות באופן נקי ומנוקה כו', וז\"ע כל הוידוים בעשי\"ת<sup data-n=\"593\">589</sup> גם לצ\"ג שלא חטא בפגמים הרבים המסודרים בנוסח הע\"ח שלכאו' הצ\"ג רחוק מהם בתכלית, ועכ\"ז<sup data-n=\"594\">591</sup> צריך גם לאומרם<sup data-n=\"595\">590</sup> ולשוב עליהם, שזהו מפני כי הי' בידו למחות וכדומה, או שמנע עצמו מלידע דברים כאלו שלכן גם הוא צריך לפורטם ולשוב עליהם באמת לאמיתו בכדי שיוכל להשיב חלקו<sup data-n=\"596\">592</sup> בחיות העולם דשנה העברה בתשובה שלימה היינו החזרה שלימה נקי' מכל לכלוך &lt;39&gt;\nּ ופסולת, ועי\"ז יומשך לו חיות חדש מלמעלה כמו שהאדם בשעה שנפשו עולה שואבת לו חיים מלמעלה כ\"ש בכלליות השנה ששואבת לו חיים מבחי' אוא\"ס ב\"ה חיי החיים כו', ולכן כמו שבכ\"י נעשה ברי' חדשה<sup data-n=\"597\">593</sup>, אשר ע\"כ תיקנו<sup data-n=\"598\">594</sup> ח\"י ברכות בברכת השחר<sup data-n=\"599\">595</sup> שהוא מפני שנעשה ברי' חדשה וצריך לברך<sup data-n=\"600\">596</sup> על כל פרט ופרט שנתחדש בו בבחי' חידוש הישינות מפני שחיות יום העבר הלך לו וכמארז\"ל אדם נידון בכ\"י<sup data-n=\"601\">597</sup> והיינו דין הגוף כמו שבכל שנה הוא בכלל כמו\"כ בכ\"י הוא בפרט שבא מן הכלל כו', ולכן כשהחזירו לו הפקדון מחדש ומתחדשים בו הכחות בבחי' חידוש הישנות צ\"ל פוקח עורים ומתיר אסורים וזוקף כפופים וכן כולם כו', כ\"ה בכלליות החיות על כל השנה בר\"ה יום ברוא אדה\"ר שנק' תחילת מעשיך, צ\"ל ברכת השחר גם בכוונה כלליות נוסף על הפרט באותו יום עצמו, ואשר מטעם זה מברכין גם ביום שני בהש\"ח<sup data-n=\"602\">598</sup> הגם שב' ימים דר\"ה כיומא",[["592","588","<b>ולא ישוב לכסלה</b>: ע\"פ תהלים פה, ט."],["593","589","<b>כל הוידוים בעשי\"ת</b>: ראה גם לקו\"ת נצבים מח, ד. שמ\"ע פד, א. פז, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתצו. תקס\"ו ע' תב. מאמרי אדה\"א דברים ח\"ד ע' א'שסג בהערה. הנחות תקע\"ז ע' שלח. מאמרי אדמו\"ר הצ\"צ הנחות ע' קצג וס\"ע קצה. סה\"מ תרכ\"ז ע' תא. תרל\"ב ח\"ב ע' תקפ. ריש ע' תקפד."],["594","591","<b>ועכ\"ז</b>: בהמשך יונתי הנדפס: וע\"ז."],["595","590","<b>הוידוים. . הצ\"ג. . לאומרם</b>: ראה גם סה\"מ מלוקט ד' ע' יח ובהנסמן שם. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצא<sup data-n=\"e95\">ה</sup> וס\"ע תתצו. תקס\"ו ע' שסד. ע' שצז וע' תב. סה\"מ תרנ\"ט ע' סד. המשך תער\"ב ח\"א ע' קג. (לקמן בחלק ההנחות) הנחה ד\"ה שובה ישראל (הא' והב' על יד הערות 72-73)."],["596","592","<b>חלקו</b>: שם: לחלקו."],["597","593","<b>שבכ\"י נעשה ברי' חדשה</b>: ראה ב\"ר רפע\"ח. שו\"ת הרשב\"א ח\"א סקצ\"א (ב\"י לטאו\"ח ס\"ד ד\"ה ומשמע). שו\"ע אדה\"ז מהדו\"ק דיני נט\"י ס\"ד, ס\"א. סי\"ג. סי\"ד. רס\"ו. רס\"ז. סידור סדר הנטילה ד\"ה אם עשה בסופו."],["598","594","<b>ברי' חדשה. . תיקנו</b>: ראה גם לקמן מאמר ד\"ה ויאמר כו' לך לך על יד הערה 60 ואילך. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמוכים לעד פ\"ב על יד הערה 29 ואילך. (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך פיסקא ובזה יובן פי'. המשך תער\"ב ח\"ב ע' תשלז ואילך."],["599","595","<b>ח\"י ברכות בברכת השחר</b>: ראה גם תו\"ח וארא ח\"א נ, א ובהערה 25. סה\"מ תרכ\"ח ריש ע' ע. ע' עח. וראה גם מאמר ד\"ה אני לדודי תשט\"ו."],["600","596","<b>לברך</b>: בהמשך הנדפס: לברר."],["601","597","<b>אדם נידון בכ\"י</b>: ר\"ה טז, א. ראה גם אגה\"ק סכ\"א. לקו\"ת קרח נה, ג ואילך. סידור שחרית לשבת קפ, ג-ד. פיה\"מ יד, ד ואילך. מאמרי אדה\"א בראשית ס\"ע רפד ואילך. שע\"ת ה, סע\"ד ואילך ובהערה 60. סה\"מ תרכ\"ז ע' סד. וש\"נ. לקו\"ש ח\"ט ע' 375 ואילך."],["602","598","<b>מברכין גם ביום שני בהש\"ח</b>: כ\"ה גם בהמשך הנדפס. ראה גם שיחת ר\"ה תשי\"ב (שיחות קודש תשי\"ב כרך ג ע' 2 ס\"ג).\n\n<b>ה</b>  ובמ\"מ לשם תתקמב, ב שו\"ה ”קדושים יט, יח.\" צ\"ל: מה שאמר האריז\"ל על עצמו: טעמי המצות קדושים יט, יח."]]],[2000480139,"אריכתא דמי<sup data-n=\"603\">599</sup><sup data-n=\"604\">600</sup> והי' מקום שלא לברך בהש\"ח, וספק ברכות להקל<sup data-n=\"605\">601</sup> אלא שזהו על הכלל שמתחדש<sup data-n=\"606\">602</sup> שבזה חלוק יום ראשון מיום שני, שיום שני הוא דינא רפיא<sup data-n=\"607\">603</sup> כו', ומ\"מ מפני שבר\"ה יש יתרון על כל יום שבכ\"י הוא רק בפרט מן הכלל שכבר נמשך אלא שדנים בכ\"י אם יומשך מרוחניות לגשמיות וכדומה או אם יומשך למטה בעוה\"ז השפל והגשמי כו' כמ\"ש מזה במ\"א, אבל בכלל נמשך בר\"ה על כל השנה, משא\"כ בר\"ה נמשך חיות חדש לגמרי<sup data-n=\"608\">604</sup> שלא נמשך בשנה העברה עליו כלל כו' לכן תקנו ט' ברכות<sup data-n=\"609\">605</sup>, ומצות תקיעת שופר שהם ג\"כ תשע תקיעות<sup data-n=\"610\">606</sup> בכדי להמשיך חיות חדש, כי הנה התקיעה היא בחי' צעקה בקול פשוט<sup data-n=\"611\">607</sup>, כמשל הצועק מתוך פנימיות נקודת לבבו שאינו נשמע שום הברת אותיות כלל בצעקתו כ\"א הצעקה מעומקא דלבא, וכ\"ה ענין הצעקה בקול שופר שהוא מתוך תוך פנימיות נקודת נפשו שנוגע לו עד הנפש ועד בכלל כנ\"ל להשיב חיות כחות נפשו מכלליות שנה העברה עם כל פעולותי' שעי\"ז מתעלה חלקו בעולם כמ\"ש גם את העולם נתן בלבם<sup data-n=\"612\">608</sup> כו', והשברים תרועה הם גנוחי גניח וילולי יליל<sup data-n=\"613\">609</sup> שזהו בחי' התשובה על הרגשת חולי הנפש וכמשל החולה שגונח מחמת חולי הלב ושארי חולשות ויליל מרוב כאביו, ושוב צועק עוד בקול פשוט שזה\"ע תקיעה אחרונה שהוא כמשל הצועק תחלה בקול פשוט ושוב מתחיל לגנוח וליליל מחמת רוב כאביו עד שצועק שנית כו', וכ\"ז הוא בקרן בהמה גשמיית דוקא להיות אדם ובהמה תושיע ה'<sup data-n=\"614\">611</sup> וכמארז\"ל בנ\"א שהם ערומים בדעת כאדם ונמשכים אחריך כבהמה<sup data-n=\"615\">612</sup> כו', וכמ\"ש",[["603","599","<b>כיומא אריכתא דמי</b>: ראה<sup data-n=\"e96\">ו</sup> שו\"ע או\"ח הל' שבת סשצ\"ג, ס\"א. ב\"י לטאו\"ח הל' ר\"ה סת\"ר ד\"ה וכתב. ט\"ז שם סק\"ב. סה\"מ תרכ\"ט ס\"ע קסז ואילך. תרל\"ב ח\"ב ע' תקי. לקמן (בחלק ההנחות) הנחה ד\"ה יפה שעה הב' הערה 75."],["604","600","<b>דמי</b>: בהמשך הנדפס: דמיא."],["605","601","<b>וספק ברכות להקל</b>: שו\"ע אדה\"ז דיני נט\"י מהדו\"ת ס\"ד, ס\"א. מהדו\"ק הל' ציצית ס\"י, סט\"ז. סי\"ז, ס\"ב. ועוד. אגה\"ת פי\"א ובמ\"מ הגהות והע\"ק שם."],["606","602","<b>שמתחדש</b>: בהמשך הנדפס: שמתחלק."],["607","603","<b>שיום שני הוא דינא רפיא</b>: ראה זהר פינחס רלא, ב. רנד, ב (ובאוה\"ח ומק\"מ שם). פע\"ח שער ר\"ה שכ\"ד, פ\"א. פ\"ב. פ\"ד. פ\"ה. שער הכוונות דרושי ר\"ה. דרוש ב. ג."],["608","604","<b>בר\"ה. . חדש לגמרי</b>: ראה גם אגה\"ק סי\"ד."],["609","605","<b>ט' ברכות</b>: ראה רמב\"ם הל' תפלה פ\"ב, ה\"ו. שו\"ע אדה\"ז הל' ר\"ה סתקצ\"א, ס\"א. וראה גם אוה\"ת בלק ס\"ע א'כד."],["610","606","<b>תשע תקיעות</b>: ראה ר\"ה לג, ב (במשנה). שו\"ע אדה\"ז שם סתק\"צ, ס\"א. וראה גם אוה\"ת שם."],["611","607","<b>התקיעה. . בקול פשוט</b>: שו\"ע אדה\"ז שם. ראה לקו\"ת נצבים מד, ב ואילך. ר\"ה נד, ג. נו, ד. נח, ד ואילך. סידור שער האלול רלא, ד. שער ר\"ה רלה, א. לעיל פי\"ח."],["612","608","<b>גם את העולם נתן בלבם</b>: קהלת ג, יא. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 397."],["613","609","<b>גנוחי גניח וילולי יליל</b>: ר\"ה לג, ב. לד, א."],["614","611","<b>אדם ובהמה תושיע ה'</b>: תהלים לו, ז. ראה גם המשך תער\"ב ח\"ב ע' תרנב."],["615","612","<b>בנ\"א. . כבהמה</b>: ראה חולין ה, ב. לקו\"ת בחוקותי נ, רע\"ג.\n\n<b>ו</b>  ראה גם ביצה ל, סע\"ב. שו\"ע אדה\"ז הל' ציצית ס\"ח, סכ\"ז."]]],[2000480140,"מזה בכ\"ד<sup data-n=\"616\">610</sup>, וכן מל' זכרונות שופרות שהוא שמביאים ראי' מן התורה<sup data-n=\"617\">613</sup> שצ\"ל בחי' זו כו'.\n<b></b>קיצור. וזהו אני לדודי מלמטלמ\"ע ועי\"ז ודודי לי, עוה\"ז ועוה\"ב, וכמו שהוא בכ\"י כ\"ה בר\"ה שתתעלה חיות שנה העברה ונמשך חיות כללי על שנה הבע\"ל ומפני שזהו בכלליות לכן תיקנו ט' ברכות, ומצות ט' תקיעות הוא ג\"כ לכוונה זו כו'.\n&lt;40&gt;\nּךד) ועדיין<sup data-n=\"618\">614</sup> צ\"ל בענין מלכיות זכרונות שופרות שארז\"ל א' הקב\"ה אמרו לפני מלכיות<sup data-n=\"619\">615</sup> כדי שתמליכוני עליכם זכרונות כדי שיעלה זכרוניכם לפני ובמה בשופר, וכן תקנו בנוסח התפלה לומר תחלה מלכיות ואח\"כ זכרונות ואח\"כ שופרות, ולכאו' הצ\"ל תחלה זכרונות<sup data-n=\"620\">616</sup> שיזכור אותנו תחלה ואח\"כ נמליך אותו עלינו, שלכאו' לאחר שכבר המלכנו אותו עלינו אינו שייך לבקש שיזכור אותנו שא\"כ על מי המלכנו אותו, והיתכן שמלך על עם לא יזכור עמו, וגם בעצם ענין הזכרונות צ\"ל הלא אין שכחה לפני כסא כבודו<sup data-n=\"621\">617</sup>.\n<b>ויובן</b> בהקדם ענין ר\"ה שנק' יום הזכרון<sup data-n=\"622\">618</sup> כמו שחותמין בשמ\"ע<sup data-n=\"623\">619</sup> ובקידוש וברכת ההפטורה מלך כו' מקדש כו' ויום הזכרון<sup data-n=\"624\">620</sup>, שזהו מפני שאה\"כ יום זכרון תרועה מקרא קדש<sup data-n=\"625\">621</sup>, אמנם לפי פי' הפסוק ע\"פ דרשת רז\"ל במד\"ר פ' אמור<sup data-n=\"626\">623</sup> שפסוק זה קאי על ר\"ה שחל להיות בשבת, שהרי כתוב א' אומר יום",[["616","610","<b>בקרן בהמה גשמיית. . בכ\"ד</b>: ראה לקו\"ת ר\"ה נה, ד. נו, ד. נט, ב. סידור שער ר\"ה רלה, ד. שער התקיעות רמב, א ואילך. עט\"ר כא, ב ואילך. סב, א ואילך. המשך תער\"ב ח\"ג ע' א'שכז."],["617","613","<b>מל'. . ראי' מן התורה</b>: ראה לקו\"ת ר\"ה נו, ג. מאמרי אדה\"ז תקס\"ד ע' ריז ואילך. וש\"נ. עט\"ר ע' יג ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'שס. וש\"נ. אוה\"ת ר\"ה ע' א'רצו. סה\"מ תרל\"ג ח\"א ע' רמ. המשך וככה תרל\"ז פפ\"ג."],["618","614","<b>ועדיין</b>: ראשי פרקים מפרק זה נרשמו לעיל בשולי היריעה לפי\"ג."],["619","615","<b>א' הקב\"ה אמרו לפני מלכיות</b>: ראה ר\"ה טז, סע\"א. לד, ב."],["620","616","<b>הצ\"ל תחלה זכרונות</b>: ראה גם המשך תער\"ב ע' תרלז."],["621","617","<b>אין שכחה לפני כסא כבודו</b>: ע\"פ ברכת זכרונות. ברכות לב, ב."],["622","618","<b>ר\"ה שנק' יום הזכרון</b>: ראה גם אוה\"ת ר\"ה ע' א'שיז."],["623","619","<b>ר\"ה. . שחותמין בשמ\"ע</b>: כן מובא בכ\"מ ומהם: מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתפא. אוה\"ת תהלים כרך ג ע' א'שכב. המשך וככה תרל\"ז פפ\"ג. קונט' מאמרים תרפ\"ב ע' 5. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי הא' על יד הערה 3. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1792."],["624","620","<b>שחותמין. . ויום הזכרון</b>: וכן בברכת המזון — ראה שו\"ע אדה\"ז הל' ברהמ\"ז סקפ\"ח, סי\"א. וכן בהדלקת הנרות — ראה ”היום יום\" א' תשרי. לקו\"ש ר\"ה כרך ט ע' 371. כרך יד ע' 378. נדפס גם באגרותיו ח\"ג ע' קמ. ח\"ו ע' קכה."],["625","621","<b>יום זכרון תרועה מקרא קדש</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתי. פסוקים המובאים בסמוך. נוסח ותתן לנו (בתפלת העמידה לר\"ה)."],["626","623","<b>במד\"ר פ' אמור</b>: ויק\"ר פכ\"ט, יב (בשינוי). ראה גם ירושלמי ר\"ה פ\"ד, ה\"א. פסיקתא ופסיקתא דר\"כ בחודש השביעי. ילקו\"ש אמור (כג, כד. רמז תרמה) ופינחס (כט, א. רמז תשפב).\nראה גם ר\"ה כט, ב. אוה\"ת ר\"ה ע' א'שה ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' קעו. סה\"מ תרנ\"ט ע' א. לקו\"ש ר\"ה כרך יט ע' 540-541. ע' 605 הערה ד\"ה יום טוב. כרך כט ע' 530 הערה ד\"ה יום הזכרון. לקוטי לוי יצחק אגרות ע' רפט."]]],[2000480141,"תרועה יהי' לכם<sup data-n=\"627\">624</sup> וכתוב א' אומר זכרון תרועה<sup data-n=\"628\">622</sup>, שבחול תוקעין ומתריעין כו' אבל בשבת שאין תוקעי' מזכירים את התרועה לבד ולא מתריעין, א\"כ מובן שהעיקר הוא התרועה עצמה שהוא מצות תקיעת שופר שהעיקר הם ג' תר\"ת<sup data-n=\"629\">625</sup> (אלא שמספק תוקעין ג\"פ<sup data-n=\"630\">626</sup> תשר\"ת תש\"ת תר\"ת) רק שבשבת שא\"א לתקוע מזכירין התרועה, וכמ\"ש הרא\"ש בסוף ר\"ה, וכ\"ה במ\"ס פי\"ט<sup data-n=\"631\">627</sup>, ולפי\"ז אינו מובן למה קראו יו\"ט דר\"ה יום הזכרון כמ\"ש בנוסח התפלה ותתן לנו כו' את<sup data-n=\"632\">628</sup> יום הזכרון הזה<sup data-n=\"633\">629</sup>, וכן בחתימת הברכה וכנ\"ל, ויותר הי' צ\"ל ותתן לנו כו' יום התרועה כו' וכן בחתימת הברכה<sup data-n=\"634\">630</sup> כו', אלא שעיקר ענין מה שנק' יום הזכרון זהו כמו מה שתקנו במוסף לומר זכרונות אתה זוכר מעשה עולם כו', שטעם א' להם כו', רק שלפ\"ז אינו מובן שהי' צ\"ל זכרונות קודם מלכיות, וגם בכהאריז\"ל ענין ר\"ה הוא בנין המל'<sup data-n=\"635\">631</sup> שז\"ע ט' ברכות וט' תקיעות בכדי להמשיך ט\"ס במל' כנודע, ולא מה שהוא יום הזכרון כו'.\n<b>אך</b> הענין יובן ע\"פ משארז\"ל במד\"ר<sup data-n=\"636\">632</sup> ע\"פ זכור לעבדיך<sup data-n=\"637\">633</sup> לאברהם ליצחק וליעקב הה\"ד גפן ממצרים תסיע<sup data-n=\"638\">634</sup>, מה הגפן הזה הוא עצמו חי ונשען על עצים מתים, כך ישראל כו' ונשענים על המתים זכור לעבדיך כו', פי' הגפן עצמו הוא אילן נמוך מאד<sup data-n=\"639\">635</sup>, והענבים גדילים על ענפים דקים מאד שא\"א להם להעמיד כובד האשכול, ולכן בהכרח להעמידם ע\"י שהם נשענים על עצים שכבר נקצצו שזהו שקורא אותם עצים מתים, שאינם מקבלים יותר חיותם ממקום גידולם על הארץ, והמשיל המשל הזה לפי דכתי' כי האדם עץ השדה<sup data-n=\"640\">636</sup>, ולכן כשהוציא את ישראל ממצרים ואירע מה שאירע התחיל משה לבקש בזכות אבות שכבר מתו שזהו כמשל עצים מתים, ועכ\"ז הם עיקר המעמידי' את הגפן שבלעדי זה א\"א שיתקיים הענף כלל מפני כובד האשכול, ואינו דומה לשאר אילנות שצריכים ג\"כ חיזוק ע\"י עצים שסומכים אותם, מ\"מ אינו מוכרח כ\"כ שהענפי' הם עבים קצת, משא\"כ הגפן ענפו הוא דק<sup data-n=\"641\">637</sup> מאד ולכן בלתי הסמיכה הי' נתלש הענף מן האילן כו', ואמנם בעיקר ענין הזכירה על אברהם יצחק יעקב<sup data-n=\"642\">638</sup> צ\"ל האיך שייך שישכח ח\"ו עליהם, ומלבד שאין שכחה &lt;41&gt;\nּ לפני כסא כבודך הרי אחד הי' אברהם<sup data-n=\"643\">639</sup>, וכן כולם כו', אך",[["627","624","<b>יום תרועה יהי' לכם</b>: פינחס כט, א."],["628","622","<b>זכרון תרועה</b>: אמור כג, כד. ראה שו\"ע אדה\"ז הל' ר\"ה סתקפ\"ב, ס\"ט. סט\"ו."],["629","625","<b>מצות תקיעת שופר. . ג' תר\"ת</b>: שו\"ע אדה\"ז שם סתק\"צ, ס\"א."],["630","626","<b>שמספק תוקעין ג\"פ</b>: שו\"ע שם, ס\"ב."],["631","627","<b>במ\"ס פי\"ט</b>: ה\"ח."],["632","628","<b>את</b>: בהמשך יונתי הנדפס ליתא."],["633","629","<b>הזה</b>: שם: כו'."],["634","630","<b>הברכה</b>: שם ניתוסף: כו'."],["635","631","<b>ר\"ה הוא בנין המל'</b>: פרע\"ח שער ר\"ה שכ\"ד, פ\"א ואילך. שער הכוונות שם. ראה לקו\"ת נצבים נא, ב. ר\"ה נו, ב ואילך. סה\"מ תרכ\"ט ע' שמא ואילך. וש\"נ. תרל\"ח ס\"ע שעג ואילך. סה\"מ מלוקט ב' ע' קה ואילך. סה\"מ מלוקט ה' ע' ד. מאמר ד\"ה אתם נצבים תשכ\"ט."],["636","632","<b>במד\"ר</b>: שמו\"ר רפמ\"ד [בשינויים. ושם מתחיל: זכור לאברהם]."],["637","633","<b>זכור לעבדיך</b>: עקב ט, כז."],["638","634","<b>גפן ממצרים תסיע</b>: תהלים פ, ט."],["639","635","<b>מאד</b>: בהמשך הנדפס ליתא."],["640","636","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["641","637","<b>ענפו הוא דק</b>: בהמשך הנדפס: ענפיו הם דקים."],["642","638","<b>יעקב</b>: שם: ויעקב."],["643","639","<b>אחד הי' אברהם</b>: יחזקאל לג, כד."]]],[2000480142,"הענין הוא שאין הבקשה שיזכור אותם בשביל עצמם כ\"א לבניהם אחריהם כו', ושרש הענין הוא דהנה אברהם הי' מרכבה למדת החסד<sup data-n=\"644\">640</sup> כנ\"ל<sup data-n=\"645\">642</sup> שבעבודה הוא בחי' אהבה<sup data-n=\"646\">641</sup> לאלקות, והי' מקושר תמיד בבחי' אהבה זו עד שאמרה מדה\"ח כל ימי היות אברם בארץ לא הוצרכתי לעשות מלאכתי שהרי אברם עומד ומשמש במקומי וכמ\"ש מזה במ\"א בד\"ה ואעשך לגוי גדול<sup data-n=\"647\">643</sup> שהחליף מקום מדת החסד ולא מרכבה לבד כו', וכן יצחק הקריב א\"ע לעולה ע\"ג המזבח לקיים רצה\"ע ב\"ה, ויעקב הי' מרכבה למדת הת\"ת<sup data-n=\"648\">644</sup> שהוא בריח התיכון המבריח מן הקצה אל הקצה מלמעלמ\"ט ומצדדי' כמ\"ש בזח\"ב תרומה דקע\"ה ב'<sup data-n=\"649\">645</sup>, ולכן הוליד י\"ב שבטים שרומזי' על י\"ב ג\"א<sup data-n=\"650\">647</sup> דז\"א דאצי', וכמ\"ש במ\"א בענין ששם עלו<sup data-n=\"651\">646</sup> שבטים שבטי י\"ה<sup data-n=\"652\">648</sup> כו', וכנגדן בעבודה יש עכשיו בכל יום ג' בחי' אהבות בק\"ש שזהו מ\"ש ואהבת כו' בכל לבבך כנגד אברהם, ובכל נפשך כנגד<sup data-n=\"653\">650</sup> יצחק, ובכל מאדך כנגד יעקב<sup data-n=\"654\">649</sup>, והענין הוא דשייכות בכל לבבך לאברהם דהנה הלב הוא משכן המדות<sup data-n=\"655\">651</sup>, ועם היות כי אברהם הי' מרכבה למדה\"ח כנ\"ל עכ\"ז הנה נודע כי החסד הוא כולל כל הששה מדות וכמ\"ש בזהר ע\"פ יומם יצוה ה' חסדו<sup data-n=\"656\">652</sup>, יומם בתוס' מ\"ם שהוא יומא דאזיל עם כולא יומין כו', שהם כל הששה מדות, ולכן נא' על אברהם ומצאת את לבבו נאמן לפניך<sup data-n=\"657\">653</sup> להיות שע\"י בחי' החסד שלו נעשה כל לבבו לה' אחד עד שאחד הי' אברהם כו', ולכן בכל לבבך בעבודה זהו מדתו של אברהם כו', ובכל נפשך הוא בחי' יצחק, כי בכל נפשך ארז\"ל במשנה אפי' נוטל<sup data-n=\"658\">654</sup> כו' שיצחק קיים כן ופשט את צוארו",[["644","640","<b>אברהם. . למדת החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["645","642","<b>כנ\"ל</b>: ניתוסף בפנים ע\"פ המשך יונתי הנדפס. באם תיבה זו מתייחסת ללפנ\"ז, ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו על יד הערה 1367 ועל יד הערה 1598. בהערה הבאה."],["646","641","<b>החסד. . אהבה</b>: ראה פרדס שער עה\"כ שכ\"ג, פ\"א מערכת אהבה."],["647","643","<b>שאמרה מדה\"ח. . בד\"ה ואעשך לגוי גדול</b>: אולי הכוונה ללעיל ח\"א (בחלק המאמרים) מאמר ד\"ה זה (שנדפס לעיל) בתחילתו."],["648","644","<b>ויעקב הי' מרכבה למדת הת\"ת</b>: ראה זהר סתרי תורה ויצא קנז, ב. ח\"ג תוספות שב, א. לעיל ד\"ה ואעשך לגוי גדול שם ובהערה 16."],["649","645","<b>הת\"ת שהוא בריח התיכון. . בזח\"ב תרומה דקע\"ה ב'</b>: ע\"פ תרומה כו, כח. ויקהל לו, לג. הובא גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1529."],["650","647","<b>י\"ב ג\"א</b>: ראה ס\"י פ\"ה, מ\"א. ס' הבהיר סמ\"ב. ונמנו בפרדס שער פרטי השמות שכ\"א פ\"ו-ח. לקו\"ת מסעי צד, א ואילך. פ' ראה כז, ג. סה\"מ תרל\"ח ע' עא. וש\"נ."],["651","646","<b>י\"ב שבטים. . ששם עלו</b>: ראה ספר הבהיר סמ\"ב. זהר במדבר קיח, ב ובביאוה\"ז לשם פה, א ואילך. לקו\"ת פקודי ז, ג. מאמרי אדה\"א דברים ח\"ב ע' תסז ואילך. וש\"נ. סה\"מ תרל\"ה ח\"ב ע' שלא. וש\"נ."],["652","648","<b>ששם עלו שבטים שבטי י\"ה</b>: תהלים קכב, ד."],["653","650","<b>כנגד</b>: בהמשך הנדפס: נגד."],["654","649","<b>ג' בחי' אהבות בק\"ש. . יעקב</b>: ראה ספרי ואתחנן ו, ה. בעל הטורים שם. וראה גם (באופן אחר) מאמרי אדה\"ז תקס\"ב ח\"א ע' קנג ואילך. תו\"ח משפטים ח\"ב רפז, א ואילך."],["655","651","<b>הלב הוא משכן המדות</b>: ראה תניא פ\"ט."],["656","652","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט. לעיל ח\"א (בחלק המאמרים) בסוף מאמר ד\"ה ואעשך לגוי גדול מציין: זח\"ג אמור קג, ע\"ב. ראה גם הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'לה."],["657","653","<b>ומצאת את לבבו נאמן לפניך</b>: נחמי' ט, ח."],["658","654","<b>בכל נפשך. . אפי' נוטל</b>: ברכות נד, א. ספרי ואתחנן שם."]]],[2000480143,"כשעקדו אביו אברהם ממעל לעצים<sup data-n=\"659\">655</sup> כו', ובכל מאדך היא בחי' אה\"ר שבלי גבול זהו מדתו של יעקב שהנחיל לו הקב\"ה נחלה בלי מצרים<sup data-n=\"660\">656</sup> כמ\"ש ופרצת ימה וקדמה<sup data-n=\"661\">657</sup> וצפונה ונגבה, וגם היותו בריח התיכון ה\"ה מחבר ב' קצוות שזהו מפני שהוא למעלה מההגבלה, שהרי גבול החסדן הוא הגבורה וכן להיפך ויעקב מחברם יחד שלא ינגדו זל\"ז כו', ולכן כשישראל מקיימין לאהוב אותו ית' בג' בחי' אהבה אלו הרי מעשה אבותיהם בידיהם<sup data-n=\"662\">658</sup> שמעשה אבות סימן לבנים<sup data-n=\"663\">659</sup>, ולכן כאשר ישראל עובדי' להקב\"ה בג' בחי' אהבות אלו ה\"ה כדוגמת האבות בעבודתם כו'.\n<b></b>קיצור. מל' וזכרונות לכאו' ה\"צ להקדים זכרונות למל', ר\"ה נק' יום הזכרון, שצ\"ל שלכאו' הי' צ\"ל יום התרועה, זכור לעבדיך, היתכן שישכח עליהם אלא הבקשה שגם לנו יזכור זכותם, ג' אהבות בכל לבבך ובכל נפשך ובכל מאדך הם דוגמת ג' אבות אברהם יצחק יעקב כו'.\nךה) <b>ואמנם</b> הנה כ\"ז הוא כשישראל בעבודתן הם מקיימים<sup data-n=\"664\">660</sup> ג' בחי' אהבה הנ\"ל כל חד לפום שיעורא דילי'<sup data-n=\"665\">661</sup>, אבל כשקורא ואינו שומע כלל מה שהוא מדבר, וכ\"ש שלא נתעורר בבחי' אהבה, ואפי' בכל לבבך בשני יצריך לא פעל בעצמו כלל מפני כי יצרו הרע &lt;42&gt;\nּ עדיין עומד בתקפו לבלי יניחו להתבונן כלל שז\"ע טמטום המוח<sup data-n=\"666\">662</sup> שהמוח אטום מלקבל דבר חכ', והגם שיש מי שאינו בבחי' טמטום המוח, והוא לומד ומתבונן עכ\"ז אינו מתפעל כלל מההתבוננו' שמתבונן בגדולת הבורא, וזהו שהנביא צווח אני ה' לא שניתי<sup data-n=\"667\">663</sup> ואתם ב\"י לא כליתם פי' שמחמת ההתבוננו' בבחי' אני ה' לא שניתי הי' צ\"ל בחי' התפעלות כו', ומ\"מ אתם בנ\"י לא כליתם שאין לכם כליות הנפש, והיינו מפני שהם בני יעקב היינו שהנביא קורא אותם בני יעקב שהוא ע\"ש וידו אוחזת בעקב עשו<sup data-n=\"668\">664</sup>, והו\"ע עקוב הלב מכל ואנוש הוא<sup data-n=\"669\">665</sup> פי' אנוש הוא חלוש שחלושי' הם מפני בחי' העוונות שאדם דש בעקביו<sup data-n=\"670\">666</sup> מפני ההרגל שהרגיל עצמו בהם עד שמדמה בנפשו שצ\"ל כן, וז\"ע ג'",[["659","655","<b>שיצחק. . כשעקדו. . ממעל לעצים</b>: וירא כב, ט."],["660","656","<b>נחלה בלי מצרים</b>: שבת קיח, סע\"א."],["661","657","<b>ופרצת ימה וקדמה</b>: ויצא כח, יד."],["662","658","<b>מעשה אבותיהם בידיהם</b>: לשון הגמ' ברכות ז, א."],["663","659","<b>שמעשה אבות סימן לבנים</b>: ראה תו\"א וישלח כו, רע\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' צא. רמב\"ן לך יב, ו. לקו\"ש תולדות כרך כה ע' 123. וש\"נ."],["664","660","<b>הם מקיימים</b>: בהמשך הנדפס: הם, ומקיימים."],["665","661","<b>כל חד לפום שיעורא דילי'</b>: ראה תניא בהקדמה (ד, א) ע\"פ זהר וירא קג, ריש ע\"ב. וראה גם זהר ח\"ש קכט, ב."],["666","662","<b>טמטום המוח</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 343."],["667","663","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה תו\"א יתרו סז, א. תו\"ח שמות ח\"א ז, ג. וש\"נ. לקמן מאמר ד\"ה וזהו שרש יונתי על יד הערה 40. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו על יד הערה 31. (בחלק ההנחות) בהנחה שם על יד הערה 34. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 154."],["668","664","<b>וידו אוחזת בעקב עשו</b>: תולדות כה, כו."],["669","665","<b>עקוב הלב מכל ואנוש הוא</b>: ירמי' יז, ט."],["670","666","<b>העוונות שאדם דש בעקביו</b>: ראה ע\"ז יח, א. זהר מקץ קצח, ב. תניא פ\"ל. אגה\"ת פ\"ז (צז, ב). מ\"מ הגהות והע\"ק לשם. לקמן מאמר ד\"ה וזהו שרש יונתי על יד הערה 44."]]],[2000480144,"שרי פרעה שהם קנה ושט ורידין<sup data-n=\"671\">667</sup> שהם התאוה באכו\"ש שלא לש\"ש כ\"א לענג א\"ע בתענוגי בנ\"א בגשמיות כמארז\"ל בענין חמרא דפרגיתא ומיא דיומסס קיפחו עשרת השבטים כו' וכנודע מענין ר\"א כו' שקרא החרש הי' לבם<sup data-n=\"672\">668</sup>, וטעה בזה לפי שע\"י הנ\"ל נעשה לבו אטם כחרש שאזנו אטומים כו', והורידין ז\"ע רתיחת הדמים בהבלי עולם כי כל מעשה אדם ותחבולותיו וריבוי טרדותיו השונות הבל וריק הם, ואינם אלא מייגעים את האדם בלבד ומדויל ידי' משתלים כו'<sup data-n=\"673\">669</sup>, וכל הענינים בצרכי עוה\"ז אפשר לקיים בלא לב ולב<sup data-n=\"674\">670</sup>, וכאשר ג\"ד אלו מעכבי' ז\"ע טמטום הלב<sup data-n=\"675\">671</sup>, ואי לזאת כשלא אכשיר דרי<sup data-n=\"676\">672</sup> זהו זכור לאי\"י, שהם במס\"נ צ\"ל קיים לבניהם לעולם. ועפ\"ז יובן ענין זכרונות, שהגם שכבר מלכו אותו, אמנם הבקשה גלה<sup data-n=\"677\">673</sup> כמו לע\"ל וזה לא נתקיים עדיין בע\"ה<sup data-n=\"678\">674</sup>, לכן הבקשה שיזכור לקיים חשף ה' ונגלה<sup data-n=\"679\">675</sup> כו' ולא יהי' אלביש שמים קדרות<sup data-n=\"680\">676</sup>, ואז ובאו במערות צורים<sup data-n=\"681\">677</sup>, וע\"ש ב' בחי' אלו נק' יום הזכרון ע\"ש זכור לעבדיך כשלא אכשיר, וגם כשאכשיר צ\"ל ז\"א<sup data-n=\"682\">678</sup> על העלי', וע\"ש הזכרון שיגלה מל' מל'<sup data-n=\"683\">679</sup> דא\"ס, ולכן הגם כי יום תרועה הוא עכ\"ז חותמי' יום הזכרון שזהו העיקר ובמה בשופר שע\"י שופר באי' למ\"ה ביטול. וזהו ובחדש השביעי באחד לחדש<sup data-n=\"684\">680</sup> שאז מאיר אור<sup data-n=\"685\">681</sup> בבחי' חידוש השנה ע\"י הביטול דבחי' יחידה שבנפש ליחיד נמשך יש אחד ואין שני לו<sup data-n=\"686\">682</sup>, והוא יום תרועה דוקא אדם ובהמה כו', ועכ\"ז ותתן לנו<sup data-n=\"687\">683</sup> כו' וכן החתימה יום הזכרון דוקא ע\"ש שיזכרינו להגלות כ' מלכותך<sup data-n=\"688\">684</sup> מל' דא\"ס.",[["671","667","<b>ג' שרי פרעה שהם קנה ושט ורידין</b>: ראה תו\"א ויחי קב, ג. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 271."],["672","668","<b>חמרא דפרגיתא. . לבם</b>: ראה שבת קמז, ב. אוה\"ת בא ע' רעו. סה\"מ תרכ\"ו ע' ל ואילך. תרל\"ד ע' קסד."],["673","669","<b>ומדויל ידי' משתלים כו'</b>: ניתוסף ע\"פ המשך יונתי הנדפס — פסחים כח, א."],["674","670","<b>בלא לב ולב</b>: ניתוסף ע\"פ המשך הנדפס — לשון הכתוב דהי\"א יב, לג."],["675","671","<b>טמטום הלב</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 343."],["676","672","<b>כשלא אכשיר דרי</b>: ע\"פ יבמות לט, ב. חולין צג, ב."],["677","673","<b>הבקשה גלה</b>: מוסף ליו\"ט וימים נוראים."],["678","674","<b>בע\"ה</b>: בעוונותינו הרבים."],["679","675","<b>ונגלה</b>: ישעי' מ, ה."],["680","676","<b>אלביש שמים קדרות</b>: ישעי' נ, ג."],["681","677","<b>ובאו במערות צורים</b>: ישעי' ב, יט."],["682","678","<b>ז\"א</b>: זכרון אבות."],["683","679","<b>מל' מל'</b>: בכת\"י זה נכתב תיבת מל' הן בסיום השורה, והן בהתחלת שורה שלאח\"ז. ואולי אחד מהם מיותר."],["684","680","<b>ובחדש השביעי באחד לחדש</b>: פינחס כט, א."],["685","681","<b>אור</b>: בהמשך יונתי הנדפס: אחד."],["686","682","<b>יש אחד ואין שני לו</b>: קהלת ד, ח [בדילוג]."],["687","683","<b>ותתן לנו</b>: תפלת העמידה לר\"ה."],["688","684","<b>כ' </b>[בהמשך הנדפס: כבוד]<b> מלכותך</b>: תהלים קמה, יא."]]],[2000480145,"<h3>שובה ישראל כו'</h3>\n<b>פ' ש\"ש</b>\n<b></b>פדר\"א אילו של יצחק כו' שופר קטן, גדול כו' ענוה\nוילך ש\"ש\n<b>שובה</b> ישראל<sup data-n=\"689\">1</sup> עד<sup data-n=\"690\">2</sup> כו', וצ\"ל מ\"ע ה' אלקיך ב' שמות<sup data-n=\"691\">3</sup>, ויש להקדים מ\"ש במד\"ר ויצא<sup data-n=\"692\">4</sup> ע\"פ והי' הוי' לי לאלקים<sup data-n=\"693\">5</sup> נטל הקב\"ה שיחתן כו' ועשאן מפתח לגאולתם כו' חייך כל הטובות<sup data-n=\"694\">6</sup>, והי' ביום ההוא יצאו מ\"ח<sup data-n=\"695\">7</sup> כו' והי' ביום ההוא יתקע בשו\"ג<sup data-n=\"696\">8</sup>, וצ\"ל מהו המעלה של גדול לכאו' קטן הוא יותר מעלה ע\"ד קטן יעקב<sup data-n=\"697\">9</sup>, קטן אין אביו מעלה עליו<sup data-n=\"698\">10</sup>, וכן מלמעלה צמצם שכינתו<sup data-n=\"699\">11</sup> כו', אך הענין יובן ע\"פ מה &lt;43&gt;\nּ דאיתא בילקוט<sup data-n=\"700\">12</sup> בשם פדר\"א אילו ש\"י<sup data-n=\"701\">13</sup> לא הי' בו דבר כו' אפרו יסוד מזה\"פ<sup data-n=\"702\">14</sup>, גידיו לכנורות דדוד, עורו אזור<sup data-n=\"703\">15</sup> אליהו כו' קרנו של שמאל למ\"ת",[["689","1","<b>שובה ישראל</b>: בספר התולדות מאדמו\"ר מהר\"ש — ברשימת מאמרי שנה זו — ע' 53 כותב כ\"ק אדמו\"ר אודות מאמר זה: ”פדר\"א אילו של יצחק כו' שופר קטן, גדול כו' ענוה\".\nבמפתח שמופיע בריש המשך יונתי הנדפס נרשם: ”מכאן ואילך מאמרים בודדים. נראה אשר המאמר שובה והמאמר כנשר יעיר — נרשמו כאן בקצור\".\nראה גם סה\"מ תרמ\"ג ע' נב: ”וע' בד\"ה שובה (שנר' בקצרה) הוא בד\"ה יונתי מ\"ם\".\nראשי פרקים ממאמר זה נרשמו לעיל בסוף דרוש דפ' שופטים בשולי היריעה.\nשתי הנחות אחרות ממאמר זה נדפסו לקמן במקומם בחלק ההנחות.\nהכותרת נעתקה מהמשך יונתי הנדפס. וכנראה צ\"ל: פ' וילך ש\"ש — כנרשם במפתח שם.\nבבוך זה נרשם תחלה התחלת המאמר (עד להלן התיבות והי' הולך על יד הערה 27) בהוספת שורה הועתק לקמן במקומו בשולי היריעה שם.\nמאמר זה נזכר לקמן במאמר ד\"ה ויאמר כו' לך לך בפיסקא ראשונה. ד\"ה ויהי כו' והאלקי' נסה. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו על יד הערה 68. לקו\"ש כ' מנ\"א כרך כט ע' 269 הערה 45."],["690","2","<b>שובה ישראל עד</b>: הושע יד, ב."],["691","3","<b>ה' אלקיך ב' שמות</b>: ראה גם סה\"מ מלוקט ד' ע' ג. וש\"נ. (לקמן בחלק ההנחות) בהנחה הא' כאן ובהערה 3."],["692","4","<b>במד\"ר ויצא</b>: פ\"ע, ו. (נטל. . לגאולתם — במדרש הוא על התחלת הפסוק: ושבתי בשלום אל בית אבי — ראה לקמן בחלק ההנחות) בהנחה הב' כאן הערה 4)."],["693","5","<b>והי' הוי' לי לאלקים</b>: ויצא כח, כא."],["694","6","<b>הטובות</b>: במדרש: טובות. וכ\"ה בלקו\"ת מטות פג, ד. ר\"ה ס, ג."],["695","7","<b>והי' ביום ההוא יצאו מ\"ח</b>: זכרי' יד, ח."],["696","8","<b>והי' ביום ההוא יתקע בשו\"ג</b>: ישעי' כז, יג."],["697","9","<b>קטן יעקב</b>: ראה עמוס ז, ה. חולין ס, ב. סה\"מ תר\"ל ע' שו ואילך. (לקמן בחלק ההנחות) בהנחה הא' כאן ובהערה 15."],["698","10","<b>קטן אין אביו מעלה עליו</b>: ראה שהש\"ר פ\"ח, ח. ראה מאמרי אדה\"ז הקצרים ע' שעג ואילך. ונו\"א שם ס\"ע שעד ואילך. אוה\"ת בלק ע' א'קב ואילך. סה\"מ תר\"ל שם."],["699","11","<b>צמצם שכינתו</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["700","12","<b>בילקוט</b>: מלכים-ב א, ח (רמז רכד) — בשינויים. וראה גם שם וירא כב, יג (רמז קא). ישעי' כז, יג (רמז תלו)."],["701","13","<b>פדר\"א אילו ש\"י </b>[בהמשך יונתי הנדפס: של יצחק]: ספל\"א. הלשון ראה לקמן הערה 25."],["702","14","<b>אפרו יסוד מזה\"פ</b>: ראה גם לקמן מאמר ד\"ה סוכה שחמתה מרובה מצלתה על יד הערה 21. ד\"ה ביום השמע\"צ על יד הערה 7 ואילך. ד\"ה ויאמר כו' לך לך בפיסקא ראשונה. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויאמר כו' לך לך. (בחלק ההנחות) בהנחה הא' כאן פיסקא עפ\"ז."],["703","15","<b>אזור</b>: ניתוסף ע\"פ המשך יונתי הנדפס. וכ\"ה גם לקמן על יד הערה 23־ קרוב לסיום המאמר — מלכים-ב א, ח."]]],[2000480146,"ושל ימין לע\"ל שופר גדול<sup data-n=\"704\">16</sup>, וצ\"ל מהו ההפרש בין ימין ושמאל הלא ע\"י השופר ממשיכים מבחי' דלית<sup data-n=\"705\">17</sup> שמאלא<sup data-n=\"706\">18</sup> כו'. והענין הוא דכתי' לשארית<sup data-n=\"707\">19</sup>, למי שמשים עצמו כשיריים<sup data-n=\"708\">20</sup> ולכאו' צ\"ל ג\"כ מאחר שביגמה\"ר אינו תופס מקום, ולמה למי שמשים, ובברכות דנ\"ח הרואה שופר בחלום<sup data-n=\"709\">21</sup> יצפה לישועה<sup data-n=\"710\">22</sup> והי' ביום ההוא יתקע כו', אמרו סתם שופר, והביאו משופר גדול*, אך הנה איתא עוד בפדר\"א<sup data-n=\"711\">24</sup> שאיל ש\"י<sup data-n=\"712\">25</sup> נברא ברה\"ש<sup data-n=\"713\">26</sup> והי' הולך<sup data-n=\"714\">27</sup> ומתקרב תמורת יצחק וסבך בקרניו, ופשט ידו<sup data-n=\"715\">28</sup> בטליתו של אברהם<sup data-n=\"716\">29</sup> שלכאו' אינו מובן מ\"ע פשיטת רגליו<sup data-n=\"717\">30</sup>, והענין כי בחי' קטן הוא בסדר השתלשלות מן הקצה אל הקצה<sup data-n=\"718\">31</sup>, ולכן אני הוי' לא שניתי<sup data-n=\"719\">32</sup>, אבל החזרה זהו לנתנה ששרשו למעלה מהשתלשלות קדמו לכ\"ד. וזהו שורש ענין שופר סתם עיקר מצותו לא ע\"י התשובה כ\"א צעקה על<sup data-n=\"720\">33</sup> ההעלאה לדבקה בו א\"ס<sup data-n=\"e17\">*</sup>",[["704","16","<b>קרנו של שמאל. . ימין. . שופר גדול</b>: ראה גם בענין קרנו של שמאל. . ימין עט\"ר פכ\"א-כב. אוה\"ת ישעי' כרך ב ע' תשפח ואילך. (יהל אור) תהלים ע' תכו. סה\"מ מלוקט ו' ס\"ע ד ואילך. ד' ע' ט. לקו\"ש פינחס כרך כג ע' 196 ואילך. נזכר בלקו\"ש כ' מנ\"א כרך כט ע' 169 הערה 42."],["705","17","<b>ע\"י השופר ממשיכים מבחי' דלית שמאלא</b>: ראה גם לקו\"ת ר\"ה נו, ג-ד. נז, א (ספ\"ג). שם, סע\"ד. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תקל."],["706","18","<b>דלית שמאלא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["707","19","<b>לשארית</b>: מיכה ז, יח."],["708","20","<b>למי שמשים עצמו כשיריים</b>: ר\"ה יז, ריש ע\"ב. ראה גם לקמן מאמר ד\"ה ויובן כו' הני ששה ועשרים הודו פיסקא ועפ\"ז."],["709","21","<b>ובברכות דנ\"ח הרואה שופר בחלום</b>: כ\"ה גם בהמשך יונתי הנדפס. ולפנינו בדף נו, ב. אבל כנראה הכוונה לילקוט שמעוני ישעי' כז, יג (רמז תלו). וראה הערה הבאה."],["710","22","<b>יצפה לישועה</b>: וכ\"ה (לקמן בחלק ההנחות) בשתי ההנחות כאן. וכ\"ה בילקוט שם. אבל בברכות שם, הובא זה לגבי הרואה חמור."],["711","24","<b>בפדר\"א</b>: ספל\"א — בשינויים. הובא בילקו\"ש וירא כב, יג (רמז קא)."],["712","25","<b>שאיל ש\"י</b>: הלשון ראה פדר\"א רפי\"ט. תויו\"ט אבות פ\"ה, מ\"ו."],["713","26","<b>ברה\"ש</b>: וכן הוא גם בהמשך יונתי הנדפס. בהנ\"ל ובאבות (בערב שבת) בין השמשות. ואולי גם כאן צ\"ל: ביה\"ש. או אולי הכוונה שר\"ה חל אז ביום וא\"ו."],["714","27","<b>והי' הולך</b>: ע\"כ נרשם בפעם הראשון — ראה לעיל הערה 1."],["715","28","<b>ופשט ידו</b>: בילקוט: פשט את ידו ואת רגלו."],["716","29","<b>ופשט ידו בטליתו של אברהם</b>: ראה גם (בנוסף על המובא להלן בפנים בין הערות 53-54) המשך תער\"ב ח\"א ע' קטז. ח\"ב ע' א'רג. סה\"מ תרע\"ח ע' צט."],["717","30","<b>פשיטת רגליו</b>: ראה הערה 28."],["718","31","<b>קטן. . אל הקצה</b>: ראה גם תו\"א וישב כט, ד."],["719","32","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["720","33","<b>שופר. . עיקר מצותו. . צעקה</b>: ראה גם (לקמן בחלק ההנחות) בהנחה שני' כאן ובהערה *35."],["e17","*","בשולי היריעה בהעתק הא' כאן (ראה לעיל הערה 1) ניתוסף:\nע' באגה\"ק סי' א נה\"י שרשם ממ\"ה החדש שממצחא דא\"ק, והוא ג\"כ בפנימיות, גידיו לכנור דוד מל', ארוממך לרדל\"א, עורו אזור דאלי', אמונה, המל' כו'<sup data-n=\"6341\">23</sup>\nוכ\"ה בסה\"מ תרל\"ג ח\"א ס\"ע קנ."],["6341","23","<b>ע' באגה\"ק. . כו'</b>: השווה להלן (על יד הערה 61) בשינוי הסדר."]]],[2000480147,"חיי החיים<sup data-n=\"721\">*34</sup>, החזרה, אך כשחטא מועיל זה ג\"כ שזהו ענין תשובה צעקה, אך אינו דומה צעקתם כמו צעקת החולה שזהו מצד החסרון לצעקת הרוצה איזה דבר טוב, ובשופר בהמה<sup data-n=\"722\">34</sup> דוקא ערום בדעת כאדה\"ר<sup data-n=\"723\">35</sup>, ערום ביראה<sup data-n=\"724\">36</sup>, דאני חכ' שכנתי ערמה<sup data-n=\"725\">37</sup>, שחכ' רק שכן לערום, שהערום חכ' אינו ניכרת חכמתו שהולך מסביב, עד\"ז ביראה יש יראה בולטת ויכול להיות הבליטה במותרות ג\"כ ע\"ד ראו מה<sup data-n=\"726\">38</sup> וכשאינו במותרות מ\"מ כשנראה ז\"ע יר\"ת, אבל ערום ביראה שאינו נראה כלל, והצנע לכת<sup data-n=\"727\">39</sup> כו' ז\"ע יר\"ע, ענוה גדולה מכולם<sup data-n=\"728\">40</sup> שיראה עקב לסוליסה<sup data-n=\"729\">41</sup> ע' בפרד\"ס<sup data-n=\"730\">42</sup> בעה\"כ<sup data-n=\"731\">43</sup> מה שפי' בזה, ועכ\"ז י\"ל שגם יר\"ע היא עקב, שהרי זהו מה שראשית חכ' יראת<sup data-n=\"732\">44</sup>, שזהו ח\"ס, נמצא צ\"ל שענוה זהו יחידה שבנפש שכל האו\"פ אפי' מו\"ס זהו רק עקב היינו הארה שנמשך בפנימיות, שיריים מותר בעולם ענוה ועי\"ז שיריים מקיף שלא נכנס בפנימי' כ\"א נשאר מקיף מפני גבהותו כנפש יחידה כו', והנה האות<sup data-n=\"733\">45</sup> שבא לבחי' זו זהו והי' הוי' לי לאלקי', חלקי ה' אמרה נפשי<sup data-n=\"734\">46</sup>, חלק ה' עמו<sup data-n=\"735\">47</sup>, וכשמברר הכל אזי כלליות ד' אותיות דש' הוי' נעשו פנימי' גם יו\"ד שהוא מקיף דחיה, וזהו שנעשה לאלקי' אלקה שלי<sup data-n=\"736\">48</sup> ע\"ד כח הפועל בנפעל<sup data-n=\"737\">49</sup>, ואז נמשך שם הוי' יותר עליון, וזהו בעבודה כשהוא ערום בדעת כאדה\"ר מו\"ס עכ\"ז נמשך כבהמה כמ\"ש בסש\"ב שהכל כפתיים נגדו<sup data-n=\"738\">50</sup> וכמ\"ש במד\"ר על משה פתי יאמין<sup data-n=\"739\">51</sup> לכל דבר<sup data-n=\"740\">52</sup>, והיינו לפי שהי' עניו מכל האדם<sup data-n=\"741\">53</sup> &lt;44&gt;\nּ וז\"ע רגלי האיל",[["721","*34","<b>חיי החיים</b>: יומא עא, א. ראה גם תניא פמ\"ד (סג, א)."],["722","34","<b>ובשופר בהמה</b>: ראה לקו\"ת ר\"ה נה, ד. נו, ד. נט, ב. לעיל המשך יונתי הערה 610."],["723","35","<b>ערום בדעת כאדה\"ר</b>: ראה חולין ה, ב. לקו\"ת בחוקותי נ, רע\"ג."],["724","36","<b>ערום ביראה</b>: ברכות יז, א."],["725","37","<b>דאני חכ' שכנתי ערמה</b>: משלי ח, יב. ראה גם סה\"מ תרל\"ב ח\"א ע' קצג. ח\"ב ע' תקסד."],["726","38","<b>ע\"ד ראו מה</b>: ראה וירא כב, כד. (לקמן בחלק ההנחות) בהנחה ראשונה כאן הערה 104."],["727","39","<b>והצנע לכת</b>: מיכה ו, ח."],["728","40","<b>ענוה גדולה מכולם</b>: ע\"ז כ, ב."],["729","41","<b>שיראה עקב לסוליסא</b>: ראה ירושלמי שבת פ\"א, סה\"ג."],["730","42","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["731","43","<b>בפרד\"ס בעה\"כ</b>: שכ\"ג, פט\"ז מערכת ענוה."],["732","44","<b>שראשית חכ' יראת</b>: תהלים קיא, י."],["733","45","<b>האות</b>: בהמשך יונתי הנדפס: האמת."],["734","46","<b>חלקי ה' אמרה נפשי</b>: איכה ג, כד."],["735","47","<b>חלק ה' עמו</b>: האזינו לב, ט."],["736","48","<b>לאלקי' אלקה שלי</b>: ראה גם תו\"א תצוה פב, רע\"ג. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני ובהערה 11. סה\"מ תרע\"ח ס\"ע קמ ואילך."],["737","49","<b>כח הפועל בנפעל</b>: בלקו\"ת שלח מז, א: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף ש\"ג."],["738","50","<b>בסש\"ב שהכל כפתיים<sup data-n=\"e97\">א</sup> נגדו<sup data-n=\"e98\">ב</sup></b>: פי\"ח."],["739","51","<b>במד\"ר על משה פתי יאמין</b>: שמו\"ר רפ\"ג. ראה קיצורים והערות לתניא ע' קא ואילך. סה\"מ תרל\"ג ח\"א ס\"ע קנא ואילך. המשך וככה תרל\"ז פמ\"ב (ע' נט)."],["740","52","<b>פתי יאמין לכל דבר</b>: משלי יד, טו."],["741","53","<b>עניו מכל האדם</b>: בהעלותך יב, ג [בדילוג].\n\n<b>א</b>  ראה מ\"מ הגהות והע\"ק לסש\"ב שם (ע' קכב).\n\n<b>ב</b>  בתניא: אצלו* — אבל כמובא בפנים כ\"ה גם בהמשך וככה תרל\"ז פמ\"א (ע' נו). בהנחה ראשונה כאן על יד הערה 119."]]],[2000480148,"בטליתו של אברהם טלית זהו מקיף, ומפני כי האיר<sup data-n=\"742\">54</sup> המקיף בפנימי ע\"י מס\"נ שעשה את יצחק כבהמה קרבן לכן פשט האיל ידיו ונגע בטליתו כו', ושרשו הוא בחי' העיגול שלפני הק\"ו, וז\"ע ג\"כ ההפרש בין מ\"ת ללע\"ל שמ\"ת הוא בשביל בירורים שלמטה נטה שמאלו וברא ארץ<sup data-n=\"743\">55</sup>, ובכדי לברר זהו ע\"י שופר דקרן שמאל להיות שמאלא אכליל בימין<sup data-n=\"744\">56</sup> כו', אבל לע\"ל יהי' ימין כי יאיר למטה בחי' דלית שמאלא, וזהו שופר גדול שהוא ג\"כ צעקה אבל זהו מלמעלמ\"ט לקבץ כולם, שיבוא להתעלות ע\"ד בידך אפקיד רוחי<sup data-n=\"745\">57</sup>, ולא רוחי<sup data-n=\"746\">58</sup> לבד כ\"א גופי<sup data-n=\"747\">59</sup> ג\"כ ומלמטלמ\"ע ז\"ע העלייה לדבקה בו בגוף ונפש כו', שופר בחלום חלום הוא בשינה, שינה עצמה כעין שופר, ושופר בחלום ז\"ע שופר גדול, ועד\"ז יובן אפרו מזבח הפנימי, קטורת בחד קטירא<sup data-n=\"748\">60</sup> כו', גידיו לכינור<sup data-n=\"749\">62</sup> דוד מל'<sup data-n=\"750\">63</sup>, ארוממך לרדל\"א<sup data-n=\"751\">64</sup>, עורו איזור דאלי', אמונה<sup data-n=\"752\">65</sup> ע' באגה\"ק סי' א' נה\"י שרשם ממ\"ה החדש שממצחא דא\"ק<sup data-n=\"753\">*66</sup>, והוא ג\"כ בפנימיות<sup data-n=\"754\">61</sup> המל' כו', ואז והי' ו\"ה קודמים, ו\"ה שרש הגשמיות יתעלו לשרשם שהם קודם ויהי' נזונים מזיו השכינה זיו קדושתו שיהי' חשף ה'<sup data-n=\"755\">66</sup> כו', וזהו שובה ישראל שובה לב' הפירושים<sup data-n=\"756\">67</sup> והשיעור עד שהוי' יהי'<sup data-n=\"757\">68</sup> בבחי' אלקיך בבחי' פנימיות ואז יתקע בשו\"ג כו'.",[["742","54","<b>האיר</b>: בהמשך יונתי הנדפס: האירו. וכשצ\"ל כבפנים."],["743","55","<b>נטה שמאלו וברא ארץ</b>: ראה פדר\"א פי\"ח. הנסמן בתו\"א וארא נו, ב."],["744","56","<b>שמאלא אכליל בימין</b>: ראה זהר ר\"פ קרח."],["745","57","<b>בידך אפקיד רוחי</b>: תהלים לא, ו."],["746","58","<b>רוחי</b>: בהמשך יונתי הנדפס: רוחו."],["747","59","<b>גופי ג\"כ</b>: בהמשך יונתי הנדפס: גופו."],["748","60","<b>בחד קטירא</b>: ראה זהר אד\"ז האזינו רפח, א. סידור ערב שבת קסג, א. שע\"ת נד, ד ובהערה 44."],["749","62","<b>לכינור. . מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"א מערכת כנור."],["750","63","<b>דוד. . מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["751","64","<b>ארוממך לרדל\"א</b>: ראה גם תו\"א מקץ מא, ב."],["752","65","<b>אזור. . אמונה</b>: ישעי' יא, ה."],["753","*66","<b>ממ\"ה החדש שממצחא דא\"ק</b>: ראה ע\"ח שער שבה\"כ ש\"ט, פ\"ו. שער התיקון ש\"י, פ\"ב ופ\"ד."],["754","61","<b>גידיו. . בפנימיות</b>: השווה לעיל בפנים בשולי היריעה על יד הערה 23."],["755","66","<b>חשף ה'</b>: ישעי' נב, י."],["756","67","<b>שובה לב' הפירושים</b>: ראה גם (לקמן בחלק ההנחות) בהנחה ראשונה כאן בסופה פיסקא וזהו תשובה."],["757","68","<b>שהוי' יהי'</b>: בהמשך יונתי הנדפס: שיהי' הוי'."]]],[2000480149,"<h3>כנשר יעיר כו'</h3>\n<b></b><b>בס\"ד ש\"פ האזינו תרמ\"א לפ\"ק ליובאוויץ</b>\n<b></b>ר\"ר כו' אור תורה, טל תורה כו' רשימה\nהאזינו\n<b>כנשר</b> יעיר<sup data-n=\"758\">1</sup>, כנפיו, ישאהו על אברתו<sup data-n=\"759\">2</sup>, פרש\"י<sup data-n=\"760\">3</sup> כו', ובנמשל הגם שאין לו דמות הגוף<sup data-n=\"761\">4</sup>, זאת התורה אדם<sup data-n=\"762\">5</sup>, רמ\"ח ושס\"ה<sup data-n=\"763\">6</sup> כו' על אברתו למעלה מרמ\"ח, שז\"ע בחי' התעוררות זכור לעבדיך אי\"י<sup data-n=\"764\">7</sup>, נשר רח\"ר<sup data-n=\"765\">8</sup> דיעקב<sup data-n=\"766\">9</sup> שכולל א\"י<sup data-n=\"767\">10</sup>, שגם צ\"ג צריך לר\"ר, שהרחמנות גם על עולמות עליונים, ממ\"כ עולמים<sup data-n=\"768\">11</sup>, כי שם עולם ל' העלם<sup data-n=\"769\">12</sup>, ועד\"ז בכ\"ע<sup data-n=\"770\">13</sup> כמו גוף הצדיק מסתיר ג\"כ, ולכן משה הניח גופו ביצי'<sup data-n=\"771\">14</sup> רק אלי' ש' ב\"ן<sup data-n=\"772\">15</sup> מפני שהי' בעיבור יב\"ח<sup data-n=\"773\">16</sup> גם גופו עלה<sup data-n=\"774\">17</sup>,",[["758","1","<b>כנשר יעיר</b>: בספר התולדות מאדמו\"ר מהר\"ש תש\"ז — ברשימת מאמרי שנה זו — ע' 53 אודות מאמר זה נרשם: ”פדר\"א אילו של יצחק כו' שופר קטן, גדול כו' ענוה\".\nבמפתח המאמרים שמופיע בריש המשך יונתי הנדפס כתב כ\"ק אדמו\"ר: ”נראה. . והמאמר כנשר יעיר — נרשמו כאן בקצור\".\nבמאמר ד\"ה זה משנת תשמ\"ו אומר: וידוע מאמר בעל ההילולא בד\"ה זה משנת תרמ\"א. שבהמשך יונתי תר\"מ (שנמשכה אמירתו לתוך שנת תרמ\"א) שכבר נדפס ממנו צילום כת\"י הר\"ש סופר. ונראה שהוא העתק מגוכתי\"ק בעל ההילולא, והוא רק קיצור ממאמר ד\"ה זה כנשר (אבל הרי הקיצור הוא של בעל המאמר עצמו).\nראה גם סה\"מ תרמ\"ד ע' קצב: ע' ברישו' דברי' ד\"ה כנשר שבסוף ס' מ\"ם. ובמהדורת תשס\"ב ע' שנט מציין לד\"ה זה בשם: כמ\"ש בד\"ה יונתי ר\"מ (בהרישומים דשובה).\nלמאמר זה ראה מאמר ד\"ה זה בסה\"מ מלוקט א' ע' פג וע' תז. ד\"ה זה משנות תשי\"ט. תשכ\"ה. תשמ\"ו. מאמר ד\"ה לה\"ע הסוכות וד\"ה חסידים ואנשי מעשה תשכ\"ט.\nשני הנחות אחרות ממאמר זה נדפסו לקמן והם: א) הנחת<sup data-n=\"e99\">*</sup> כ\"ק אדמו\"ר מהורש\"ב (נדפסה לקמן בחלק הנחותיו). ב) הנחה אחרת (נדפסה לקמן בחלק ההנחות).\nהכותרת שמופיעה בריש המאמר נעתקה מההנחות הנ\"ל."],["759","2","<b>כנשר יעיר. . על אברתו</b>: האזינו לב, יא."],["760","3","<b>פרש\"י</b>: האזינו שם."],["761","4","<b>שאין לו דמות הגוף</b>: ע\"פ פיוט יגדל. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערה 31."],["762","5","<b>זאת התורה אדם</b>: חוקת יט, יד. ראה זהר רע\"מ משפטים קיז, ב. צו כט, ב. תו\"א תרומה עט, ג. מאמרי אדה\"א דברים ח\"ד ע' א'שכז. וש\"נ."],["763","6","<b>רמ\"ח ושס\"ה</b>: אהלות פ\"א, מ\"ח. תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב."],["764","7","<b>זכור לעבדיך אי\"י</b>: ע\"פ עקב ט, כז."],["765","8","<b>נשר רח\"ר</b>: ראה לקו\"ת במדבר י, א. יא, ב. האזינו עז, ג. שה\"ש מט, ב. אוה\"ת האזינו ע' א'תרפה ואילך. קהלת יעקב מערכת נשר."],["766","9","<b>רח\"ר דיעקב</b>: ראה זהר לך פז, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 18."],["767","10","<b>דיעקב שכולל א\"י</b>: ראה תו\"א תולדות יז, ג. לעיל ד\"ה ואעשך לגוי גדול שם ובהערה 109."],["768","11","<b>ממ\"כ </b>[בהמשך יונתי הנדפס: מל' מל' כל]<b> עולמים</b>: תהלים קמה, יג."],["769","12","<b>עולם ל' העלם</b>: ראה ספר הבהיר ס\"י. תו\"ח שמות ח\"א יח, ד הערה 783."],["770","13","<b>בכ\"ע</b>: בכל עולם בכל ענין"],["771","14","<b>משה הניח גופו ביצי'</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 43. (בחלק ההנחות) בהנחה כאן על יד הערה 82. המשך וככה תרל\"ז פפ\"ח. סה\"מ תרח\"ץ ע' ריד. מאמר ד\"ה ונגלה כבוד הוי' ש\"מ אייר תשכ\"ב. ד\"ה כנשר תשי\"ט. תשכ\"ה."],["772","15","<b>אלי' ש' ב\"ן</b>: ראה פע\"ח שער הק\"ש ש\"ח, פ\"ח. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 156."],["773","16","<b>אלי'. . בעיבור יב\"ח</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' רסה. וש\"נ. ח\"ב ע' תקלה (בשם הע\"ח). שע\"ת מו, ג. שער האמונה צח, ב בשם (ס' הקבלה להאריז\"ל) תו\"ח תולדות קמח<sup data-n=\"e100\">א</sup>, ד ובהערה 53."],["774","17","<b>אלי'. . גם גופו עלה</b>: מלכים-ב ב, יא. ראה פרדס שער היכלות שכ\"ד, פי\"ג. פי\"ד. לקמן בשני ההנחות כאן. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ד ובהערה 157. וראה גם דרושים שבהערה 14. לקו\"ש יו\"ד שבט ח\"ב ע' 516 ובהערה 9."],["e99","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>א</b>  וכן צ\"ל בשער האמונה שם."]]],[2000480150,"שהי' הביטול בחיצוניות, וצ\"ל יערוף כמטר<sup data-n=\"775\">18</sup> ואד יעלה אתעדל\"ת<sup data-n=\"776\">19</sup> והגוף מונע, וזהו שברו הבריות את ערפם<sup data-n=\"777\">20</sup>, אתכפי' חרישה דמרפי<sup data-n=\"778\">21</sup>, ואח\"כ הגשם מרוה, ואח\"כ תזל כטל<sup data-n=\"779\">22</sup> בחי' טל תורה<sup data-n=\"780\">23</sup>, אור תורה מחייהו<sup data-n=\"781\">24</sup>, גשם אור זה\"י פרש\"י שמ\"ג<sup data-n=\"782\">25</sup>, טל תורה, שזהו גבוה יותר, משיורא טלא דבדולחא<sup data-n=\"783\">26</sup> ב' מזלות ונוצר<sup data-n=\"784\">28</sup> ונקה<sup data-n=\"785\">27</sup>, ועכ\"ז כדי שיתעלה מגשמיותו צ\"ל התעוררות וזהו כנשר יעיר, כי גם במ\"ת נא' ג\"כ ואשא כו' נשרים<sup data-n=\"786\">29</sup>, ואז ודאי לא חטאו<sup data-n=\"787\">30</sup> שהרי זהו קמ\"ת<sup data-n=\"788\">31</sup> רק שמיצ\"מ עד מ\"ת רק נו\"ן יום<sup data-n=\"789\">32</sup> כו', ועד\"ז בעשי\"ת ל' החזרה, ולכן כל מי שאינו בוכה<sup data-n=\"790\">33</sup> כו'<sup data-n=\"791\">34</sup>, שלימות זהו כשמתעלה כו', ולזה צריך בכי' התעוררות, מ\"ת בוכים<sup data-n=\"792\">35</sup>, וגם לע\"ל כתי' בבכי יבואו<sup data-n=\"793\">36</sup> כו' שקאי גם על צ\"ג, וכ\"ש כשידע אינש כו' שחטא פי' חסר והעביר כו' שצ\"ל תשובה חרטה כאדם &lt;45&gt;\nּ שרוחץ בנהר והתחיל לטבע כו' שמתחרט<sup data-n=\"794\">37</sup> למה הלך לרחוץ, כך הורידו הנשמה בגוף בעוה\"ז שהוא במים רבים טרדת הפרנסה<sup data-n=\"795\">38</sup> שמונע, ובאמת מ\"ר לא יוכלו לכבות, וכשכבה והולך משומם מריבוי הדאגה כו' שע\"י הפגמי' יורד ח\"ו לבאר שחת, וע\"ז עוברי",[["775","18","<b>יערוף כמטר</b>: האזינו לב, ב."],["776","19","<b>ואד יעלה אתעדל\"ת</b>: בראשית ב, ו. ראה ת\"ז רתנ\"ב."],["777","20","<b>שברו הבריות את ערפם</b>: ב\"ר פי\"ג, יד<sup data-n=\"e101\">ב</sup>. ראה גם לקמן בשני ההנחות כאן. המשך מים רבים תרל\"ו פקכ\"ו."],["778","21","<b>חרישה דמרפי</b>: ראה מועד קטן ב, ב. לקו\"ת האזינו עה, ד. שה\"ש לח, ד. שע\"ת סג, ב ואילך. המשך מים רבים שם. לקמן בשני ההנחות כאן."],["779","22","<b>תזל כטל</b>: האזינו לב, ב."],["780","23","<b>טל תורה</b>: ראה לקו\"ש כד טבת כרך יא ע' 193 [נדפס גם באגרותיו חכ\"ב ע' צז]."],["781","24","<b>אור תורה מחייהו</b>: כתובות קיא, ב."],["782","25","<b>אור זה\"י פרש\"י שמ\"ג</b>: ראה גם לקמן בשני ההנחות כאן. וש\"נ."],["783","26","<b>משיורא טלא דבדולחא</b>: זהר ויקרא מט, א."],["784","28","<b>מזלות ונוצר</b>: כ\"ה בכ\"מ ומהם — מאמרי אדה\"א בראשית ע' רנה. במדבר ח\"ב ע' תעו. דברים ח\"ב ע' שעז. וש\"נ."],["785","27","<b>ב' מזלות ונוצר ונקה</b>: ראה לקו\"ת האזינו עג, ג. סה\"מ תרל\"ח ע' קג. וש\"נ."],["786","29","<b>ואשא כו' נשרים</b>: יתרו יט, ד."],["787","30","<b>ודאי לא חטאו</b>: ראה ערכין טו, א ואילך."],["788","31","<b>קמ\"ת</b>: קודם מתן תורה."],["789","32","<b>שמיצ\"מ. . עד מ\"ת רק נו\"ן יום</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1217."],["790","33","<b>כל מי שאינו בוכה</b>: ראה פע\"ח שער השופר שכ\"ו, פ\"ה. לקו\"ש האזינו כרך ט ע' 206. מאמרי אדה\"א דברים ח\"א ע' שיט. וש\"נ. תו\"ח וישב ר, ג הערה 35."],["791","34","<b>כו'</b>: בהמשך יונתי הנדפס ליתא."],["792","35","<b>מ\"ת בוכים</b>: ראה ת\"ז ת\"ה (יט, ב). לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ט. וש\"נ."],["793","36","<b>בבכי יבואו</b>: ירמי' לא, ח."],["794","37","<b>כאדם שרוחץ בנהר. . שמתחרט</b>: ראה בשם אדה\"ז (לקמן בחלק ההנחות) בהנחה כאן ובהערה 119."],["795","38","<b>במים רבים. . טרדת הפרנסה</b>: שה\"ש ח, ז. תו\"א ר\"פ נח.\n\n<b>ב</b>  ושם: בריות. וכ\"ה בלקו\"ת האזינו עה, ד. אבל כ\"ה גם לקמן בשני ההנחות כאן. לקו\"ת שם עז, ג. סה\"מ תרל\"ב ח\"ב ע' תקע. וע' תקעג. ע' תרב. המשך מים רבים שם. סה\"מ תרל\"ו ח\"ב ע' רסח. המשך תער\"ב ח\"ב ע' א'ע. סה\"ש תש\"ה ע' 61 [והסיום שם: מיד גשמים יורדין — הוא כנראה ע\"פ ירושלמי תענית פ\"ב, ה\"א]."]]],[2000480151,"בעמק הבכה<sup data-n=\"796\">39</sup> ב' פי' הא' בכי' בגיהנם<sup data-n=\"797\">40</sup> הב' על עולי רגלים<sup data-n=\"798\">41</sup>, שהוא הבכי' מריבוי הדינים קשים שמייסרים אותו, אמנם לאחר הבירור מעיי' ישיתוהו שתמורת מעיין הדמעות יבוא לבחי' מעייני הישועה<sup data-n=\"799\">42</sup> שמשם היו שואבי' רוה\"ק<sup data-n=\"800\">43</sup>, שהוא כמו המעיין שנובע תמיד בלי הפסק, וזהו כשלא שב רק נזדכך ע\"י יסורי גיהנם, אבל כששב אין לך דבר שעומד<sup data-n=\"801\">44</sup> כו' וע\"י חרטה וידוי פה<sup data-n=\"802\">45</sup>, שז\"ע קחו עמכם דברים<sup data-n=\"803\">46</sup> ובכיות התעוררות זהו כנשר יעיר עד שמתעלה על אברתו למעלה מרמ\"ח, כי הרי פגם ולא המשיך לבושי' ע\"י רמ\"ח מ\"ע<sup data-n=\"804\">47</sup> עכ\"ז נושאי' אותו למעלה מהם כו' ונותנים לו לבושי' מבחי' כתנות אור באלף<sup data-n=\"805\">48</sup>, וזהו יפרוש כנפיו יקחהו כנפים הם כלים לרצה\"ע<sup data-n=\"806\">49</sup>, ושרש הכלים גבוהים יותר כמו הלבושי', ולכן שרשם מהרשימו<sup data-n=\"807\">50</sup> שהוא רושם הא\"ס כמו קודם הצומ\"פ<sup data-n=\"808\">52</sup> שבאמת הם אור מעין המאור שלפני הצמצום כו' ועז\"נ הנה מקום אתי<sup data-n=\"809\">53</sup>, הוא מקומו ש\"ע<sup data-n=\"810\">54</sup> הוא נעלם אור הרשימה שהוא בהעלם שהוא נושא וסובל כלליות אבי\"ע והוא מקור כל הלבושי' כמשנ\"ת בד\"ה אז ישיר שבמצה זו<sup data-n=\"811\">51</sup>, וזהו העלי' לבחי' האלקי' אשר נתנה<sup data-n=\"812\">55</sup> בחי' נשמה שנתת בי<sup data-n=\"813\">56</sup> טהורה היא בחי' טה\"ע<sup data-n=\"814\">57</sup> רשימה<sup data-n=\"815\">58</sup> כו', ולפי פי' רשימה רושם הא\"ס כמו קודם הצמצם קאי על אוא\"ס כמו קודם הצמצום שהי' א\"ס ממלא כל החלל<sup data-n=\"816\">59</sup>, וי\"ל שז\"ע מח' ש\"י קדמו לכ\"ד<sup data-n=\"817\">60</sup>, דבר הוא הצמצום",[["796","39","<b>עוברי בעמק הבכה</b>: תהלים פד, ז."],["797","40","<b>פי' הא' בכי' בגיהנם</b>: ראה ערובין יט, א. שמו\"ר פ\"ז, ד. מדרש תהלים פד, ג."],["798","41","<b>פי'. . הב' על עולי רגלים</b>: ראה מצודת דוד ואבן עזרא לתהלים שם."],["799","42","<b>מעייני הישועה</b>: ישעי' יב, ג."],["800","43","<b>שמשם היו שואבין רוח הקודש</b>: נסמן (לקמן בחלק ההנחות) בהנחה כאן הערה 130."],["801","44","<b>אין לך דבר שעומד</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. לקו\"ש בא כרך ו ע' 66 הערה 54."],["802","45","<b>וידוי פה</b>: ראה אגה\"ת פ\"א. לקו\"ת תצא לז, א. שע\"ת ו, ג. ובהערה 34. ש\"א ח, א ובהערה 3."],["803","46","<b>קחו עמכם דברים</b>: הושע יד, ג."],["804","47","<b>רמ\"ח מ\"ע</b>: מכות כג, סע\"ב."],["805","48","<b>כתנות אור באלף</b>: בראשית ג, כא. ראה ב\"ר פ\"כ, יב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ערבים עלי דברי דודיך הערה 61."],["806","49","<b>כנפים הם כלים לרצה\"ע</b>: ראה לעיל המשך יונתי בתחילתו."],["807","50","<b>הכלים. . שרשם מהרשימו</b>: ראה גם שעה\"י קל, א ובהנסמן במ\"מ לשם. לקמן (בחלק ההנחות) בהנחה כאן ובהערה 149."],["808","52","<b>הצומ\"פ</b>: [בהמשך יונתי הנדפס: הצמצום ומ\"פ]. ראה ע\"ח דרוש עגוי\"ש ש\"א, ענף ב."],["809","53","<b>הנה מקום אתי</b>: תשא לג, כא. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה משה קבל תורה מסיני בתחילתו. ראה גם בענין מקום לקמן מאמר ד\"ה סוכה שחמה מרובה מצלתה על יד הערה 68 ואילך."],["810","54","<b>הוא מקומו ש\"ע</b>: ב\"ר פס\"ח, ט. ראה מאמרי אדה\"א דברים ח\"א ע' רצא. וש\"נ. תו\"ח בראשית מג, א הערה 2. סה\"מ תרכ\"ט ע' קסט. וש\"נ."],["811","51","<b>מהרשימו. . בד\"ה אז ישיר שבמצה זו</b>: נדפס לעיל ח\"א בחלק המאמרים — ראה שם פ\"ו. פ\"ז."],["812","55","<b>האלקי' אשר נתנה</b>: קהלת יב ז."],["813","56","<b>נשמה שנתת בי</b>: ברכת אלקי נשמה (מברכות ס, ב)."],["814","57","<b>נשמה. . טהורה. . טה\"ע</b>: ראה גם לעיל המשך יונתי הערה 211."],["815","58","<b>נשמה. . רשימה</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה שובה ישראל הא' על יד הערה 184."],["816","59","<b>א\"ס ממלא כל החלל</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 215."],["817","60","<b>מח' ש\"י קדמו לכ\"ד</b>: ב\"ר פ\"א, ד. ראה סה\"מ תרמ\"ד ע' שנט (מהדורת תשס\"ב)."]]],[2000480152,"וקדמו לכ\"ד זהו כמו קודם הצמצום וזהו ע\"י העבודה לדבקה בו<sup data-n=\"818\">61</sup> כו', ולפ\"ז צ\"ל מהו העלי' שע\"י הירידה, אך משנת\"ל<sup data-n=\"819\">62</sup> שהעלי' מגרמוהי לחיוהי זהו לפי' רשימה שלא נשאר רק רשימה, והגם שזהו מלפני הצמצום מ\"מ מאחר שהוא רק רושם לבד הארה שייך לחלק בין גרמוהי וחיוהי, אבל לפמשנ\"כ<sup data-n=\"820\">63</sup> הרשימו זהו רושם הא\"ס כמו שהי' ממלא כו' אינו שייך לחלק בין גרמוהי לחיוהי רק שזהו ע\"י העבודה לדבקה בו, ומ\"מ גם בזה יש עלי' ע\"י הירידה אך אינו שייך חילוק שמות, וזהו לע\"ל בנתינה רוחי כנ\"ל<sup data-n=\"821\">64</sup> שלא נא' של מי וזהו וחי'<sup data-n=\"822\">65</sup> חיות נש\"י שעי\"ז תהי' חי לעולם כו'.\nהמשך ציוני העמודים להמשך יונתי הנדפס, נמצא להלן ע' תקצד]",[["818","61","<b>לדבקה בו</b>: עקב יא, כב [ושם: ולדבקה]."],["819","62","<b>משנת\"ל</b>: המשך יונתי פ\"י."],["820","63","<b>לפמשנ\"כ</b>: בהמשך יונתי הנדפס: לפי משנ\"ת כי."],["821","64","<b>לע\"ל בנתינה רוחי כנ\"ל</b>: המשך יונתי פכ\"ב."],["822","65","<b>וחי'</b>: יחזקאל לז, יד. בהמשך יונתי הנדפס: וחי. וכנשצ\"ל כבפנים."]]],[2000480153,"<h3>סוכה שחמתה כו'</h3>\n<b></b>אפר אילו ש\"י יסוד מזה\"פ כו' נשר יונה ב' דעות במקום\nסוכה שחמתה מרובה מצלתה<sup data-n=\"823\">1</sup> פסולה<sup data-n=\"824\">2</sup>, וצ\"ל כוכבים נראים מתוכה<sup data-n=\"825\">3</sup>, וצ\"ל מ\"ע כוכבים לסוכה, ויובן בהקדם הפסוקים יסובבנהו<sup data-n=\"826\">4</sup> יבוננהו כו', כנשר יעיר קנו<sup data-n=\"827\">5</sup> ה' בדד ינחנו<sup data-n=\"828\">6</sup>.\n<b>והנה</b> בת\"י פי' כנשר יעיר קנו היך נשרא ומחיש<sup data-n=\"829\">7</sup> לשרכפתיה, ועל חסילו<sup data-n=\"830\">8</sup> מחופף, כדין שכינתיה מעורר למשרייתהון דישראל וחפא עליהן מטול<sup data-n=\"831\">9</sup> שכינתיה, והיכמא דנשרא פריש<sup data-n=\"832\">10</sup> גדפוי על בנוי וטעין יתהון על איברי' כדין",[["823","1","<b>סוכה שחמתה מרובה מצלתה</b>: בספר התולדות מאדמו\"ר מהר\"ש מהדורת תש\"ז — ברשימת מאמרי שנה זו — ע' 53 אודות מאמר זה כותב כ\"ק אדמו\"ר: ”אפר אילו ש\"י יסוד מזה\"פ כו' נשר יונה כו' ב' דעות במקום\" ובהערה 2 שם: ”כנראה הוא קיצור מדרוש הנאמר\".\nלפיסקא ראשונה (מהתיבות וביאור הענין) ראה גם לקמן מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 37 ואילך.\nמאמר זה הובא בסה\"מ מלוקט ב' ע' קכא [ושם: ומבאר אדמו\"ר מהר\"ש בעל ההילולא בהמאמרים דחג הסוכות שנאמרו לפני מאה שנה].\nמאמר זה לא נדפס בהמשך יונתי הנדפס."],["824","2","<b>סוכה שחמתה מרובה מצלתה פסולה</b>: ראה סוכה ב, א במשנה."],["825","3","<b>כוכבים נראים מתוכה</b>: ראה סוכה כב, א (במשנה). שו\"ע אדה\"ז הל' סוכה סתרל\"א, ס\"ה ועה\"ג שם: ירושלמי סוכה פ\"ב, ה\"ג. וראה גם לקו\"ש ברכה כרך ט ע' 231 בשולי הגליון שם. לקו\"ת ויקרא א, ד. פ' ראה כז, ג. סה\"מ תרל\"ח ע' נח ואילך."],["826","4","<b>יסובבנהו יבוננהו</b>: האזינו לב, י."],["827","5","<b>כנשר יעיר קנו</b>: שם לב, יא."],["828","6","<b>ה' בדד ינחנו</b>: האזינו שם, יב."],["829","7","<b>ומחיש</b>: בת\"י שם: דמעורר ומחיש."],["830","8","<b>חסילו</b>: שם: חסילוי."],["831","9","<b>מטול</b>: שם: טול."],["832","10","<b>פריש</b>: שם: פריס."]]],[2000480154,"טענינון וסכלונון<sup data-n=\"833\">11</sup> ואשרינון על תקוף ברכא<sup data-n=\"834\">12</sup> ארעא דישראל, ובפ' יתרו ע\"פ ואשא אתכם על כנפי נשרים<sup data-n=\"835\">13</sup> פי' וטענינון<sup data-n=\"836\">14</sup> יתכון על עננין היך<sup data-n=\"837\">15</sup> כעל גדפי נשרין, והיינו כי שם העיקר הוא הכנפיי' לכן פי' על העננים, ובכאן נא' ישאהו על אברתו שהוא גופו לכן ביאר ענין בחי' רחמים דנשר<sup data-n=\"838\">16</sup>. ושרש הענין נושא פסוקי' אלו יסובבנהו יבוננהו, קאי על חה\"ס<sup data-n=\"839\">17</sup> זכר לענני כבוד<sup data-n=\"840\">18</sup>, ופסוק כנשר קאי גם על אחר חורבן בהמ\"ק<sup data-n=\"841\">19</sup>, שע\"י ההנהגה שמנהיגם ברחמי' יבואו שה' בדד ינחנו כו', וכמו שביצ\"מ הי' על עננין כעל גדפי נשרין כן לע\"ל כתי' מי אלה כעב תעופינה<sup data-n=\"842\">20</sup>, וביאור הענין דהנה נת\"ל שאפר האיל זהו יסוד מזבה\"פ<sup data-n=\"843\">21</sup>, אפר הוא הנשאר אחר בירור הד\"י<sup data-n=\"844\">23</sup>, אמ\"ר יוצאין בעשן<sup data-n=\"845\">22</sup>, אפר הנשאר עם היות שהוא היסוד הנמוך יותר אמנם הוא העצם, הכל הי' מן העפר<sup data-n=\"846\">24</sup>, ושרש הגוף מסוכ\"ע<sup data-n=\"847\">25</sup>, א\"כ זהו עצם הסובב, וגוף הבע\"ח בשרשן גבוהי'<sup data-n=\"848\">26</sup>, אלא שגם גוף האדם הי' תחילה דומם<sup data-n=\"849\">27</sup> בכדי שיוכל להעלות הכל<sup data-n=\"850\">28</sup>, וכששורף הכל בשלהובא דרחימותא<sup data-n=\"851\">29</sup>, ונשאר האפר זהו עצם מה שנשאר אחר הבירור כו', ולכן מזה נעשה יסוד מזה\"פ קטרת התקשרות<sup data-n=\"852\">30</sup> בחד קטירא<sup data-n=\"853\">31</sup> כו', מהקטרת יש עשן, והענן נעשה מעשן זה שהאדם המבורר מברר שאמ\"ר שבסמי הקטרת יתעלו להיות עשן ונק' ענן הקטרת<sup data-n=\"854\">32</sup>, כי בענן<sup data-n=\"855\">33</sup>, ומבחי' ענן זה נעשה מקיף דסוכה<sup data-n=\"856\">34</sup> ולכן כשחמתה מרובה",[["833","11","<b>וסכלונון</b>: שם: וסבלינון."],["834","12","<b>ברכא</b>: שם: כרכי."],["835","13","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד."],["836","14","<b>וטענינון</b>: בת\"י שם: וטענית."],["837","15","<b>היך</b>: וכ\"ה באוה\"ת (יהל אור) תהלים ע' רלה. בת\"י שם: הי. ובתרגום ירושלמי שם: היך."],["838","16","<b>רחמים דנשר</b>: ראה לעיל מאמר ד\"ה כנשר יעיר ובהערה 8."],["839","17","<b>יסובבנהו יבוננהו. . חה\"ס</b>: ראה גם לקו\"ת ר\"ה סג, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתצו. תקס\"ו ע' שסד. מאמרי אדה\"א הנחות תקע\"ז ע' שלט."],["840","18","<b>חה\"ס זכר לענני כבוד</b>: ראה שו\"ע אדה\"ז הל' סוכה סתרכ\"ה. סה\"מ מלוקט ב' ע' קכא. וש\"נ."],["841","19","<b>כנשר. . אחר חורבן בהמ\"ק</b>: ראה גם לקו\"ת האזינו עז, ג. מאמרי אדה\"ז תקס\"ד ע' רכד."],["842","20","<b>מי אלה כעב תעופינה</b>: ישעי' ס, ח."],["843","21","<b>נת\"ל שאפר. . יסוד מזבה\"פ</b>: ראה לעיל מאמר ד\"ה שובה ישראל על יד הערה 14."],["844","23","<b>הד\"י</b>: ראה שה\"א סו, א ובהערה 17. סה\"מ תרכ\"ט ע' קעט. וש\"נ. תרל\"ח ע' תצא."],["845","22","<b>אפר. . אמ\"ר יוצאין בעשן</b>: ראה גם לקמן מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 39."],["846","24","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["847","25","<b>ושרש הגוף מסוכ\"ע</b>: ראה תו\"א מג\"א צ, ב. סע\"ג. צא, ג. צב, ג ואילך. לקו\"ת פ' ראה כ, ד. מאמרי אדה\"א דברים ח\"ד ע' א'רפו ואילך. סהמ\"צ להצ\"צ קמ, ב. סה\"מ תרל\"ח ע' נא. לקמן מאמר ד\"ה ולקחתם לכם רפ\"ג. ד\"ה ויאמר כו' לך לך על יד הערה 35. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויאמר כו' לך לך על יד הערה 52."],["848","26","<b>וגוף הבע\"ח בשרשן גבוהי'</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הב' ובהערה 86."],["849","27","<b>גוף האדם הי' תחלה דומם</b>: בראשית ב, ז."],["850","28","<b>בכדי שיוכל להעלות הכל</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ערבים עלי דברי דודיך ובהערה 68."],["851","29","<b>בשלהובי דרחימותא</b>: זהר קדושים פד, א."],["852","30","<b>קטרת התקשרות</b>: ראה לקמן מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 41."],["853","31","<b>בחד קטירא</b>: ראה זהר אד\"ז האזינו רפח, א. סידור ערב שבת קסג, א. שע\"ת נד, ד ובהערה 44."],["854","32","<b>ענן הקטרת</b>: אחרי טז, יג."],["855","33","<b>כי בענן</b>: אחרי שם, ב."],["856","34","<b>בענן. . מקיף דסוכה</b>: ראה גם עט\"ר כח, א. לו, סע\"א. תו\"ח נח נח, א ובהערה 16. סה\"מ מלוקט ב' ע' קכא. וש\"נ. לקמן שם על יד הערה 46."]]],[2000480155,"פסולה שזהו הוכחה שעדיין לא בירר שהרי תוקף החום זהו השלהבת הנ\"ל, וענין קטרת זהו התקשרות בלא הרגש חום כ\"א דביקות וביטול ההרגשה כו', כ\"א כוכבי' צ\"ל נראין שענין כוכבי' הם ברקיע תמינאה<sup data-n=\"857\">35</sup> וכוכב<sup data-n=\"858\">37</sup> המאיר<sup data-n=\"859\">38</sup> זהו בחי' האור המאיר בבינה<sup data-n=\"860\">36</sup> שזהו מבחי' אור זה\"י ז\"ת דעתיקא<sup data-n=\"861\">39</sup>.\n<b>והנה</b> נת' במ\"א שנשר הוא בינה<sup data-n=\"862\">40</sup> שכ\"ע<sup data-n=\"863\">41</sup> וע' פרדס ע' נשר בסופו, רחמני על בניו ודינא לגבי אחרנין<sup data-n=\"864\">43</sup>, בינה דינין מתערין<sup data-n=\"865\">44</sup> כו' על ההיפך, וחרה אף<sup data-n=\"866\">45</sup> שבק\"ש שכאשר תשמעו<sup data-n=\"867\">46</sup> אוזן שומעת<sup data-n=\"868\">47</sup> אזי וחרה על ההיפך, והפרדס פי' נשר<sup data-n=\"869\">42</sup> ת\"ת י\"ל כנפי יונה כנס\"י<sup data-n=\"870\">48</sup> וכנפי נשרים מז\"א מלמעלמ\"ט, שמהלך על כנפי רוח<sup data-n=\"871\">49</sup>, וי\"ל כנפי יונה רצו\"ש שנמשך ע\"י לאסתכלא דעיניך יונים<sup data-n=\"872\">51</sup>, וזהו יונתי בחגוי<sup data-n=\"873\">52</sup> ואז אינה יכולה לפרוח מחמת נה\"ב והעצה לזה הראני השמיעני תומ\"צ<sup data-n=\"874\">53</sup> רצה\"ע והרצון<sup data-n=\"e18\">*</sup>",[["857","35","<b>כוכבי'. . ברקיע תמינאה</b>: ראה זהר ויצא קסב, ב. רמב\"ם רפ\"ג מהל' יסוה\"ת. חגיגה יב, ב. פרדס שער סדר עמידתן ש\"ו, פ\"ג. לקו\"ת פ' ראה כז, ג. שיחת כ' כסלו תשי\"ז סל\"א."],["858","37","<b>וכוכב. . בבינה</b>: ראה גם המשך מים רבים תרל\"ו פקל\"ו."],["859","38","<b>וכוכב המאיר</b>: ראה גם פסחים ב, א. תו\"ח ויחי רמו, א ובהערה 4."],["860","36","<b>ברקיע תמינאה. . בבינה</b>: ראה זהר ויצא קסב, ב ובמפרשים שם. ויקהל ריג, א ובהגהות מהרח\"ו שם."],["861","39","<b>אור זה\"י ז\"ת דעתיקא</b>: ראה סידור שער חהמ\"צ רצא, ד."],["862","40","<b>שנשר הוא בינה</b>: ראה גם פרדס שער עשר ולא תשע ש\"א. אוה\"ת האזינו ע' א'תרסח."],["863","41","<b>בינה שכ\"ע </b>[ שכינתא עילאה]: ראה פרדס שער עה\"כ שכ\"ג, פכ\"א מערכת שכינה. זהר הרקיע בראשית א, א [שער מאמרי הרשב\"י לזהר שם (טו, א)]. סה\"מ תרל\"ח ע' רז. וש\"נ."],["864","43","<b>נשר. . רחמני על בניו ודינא לגבי אחרנין</b>: ראה זהר יתרו פ, ב."],["865","44","<b>בינה דינין מתערין</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א. מאמרי אדה\"א דברים ח\"ב ע' שעז. וש\"נ."],["866","45","<b>וחרה אף</b>: עקב יא, יז. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה פ\"ב."],["867","46","<b>תשמעו</b>: עקב שם, יג."],["868","47","<b>אוזן שומעת</b>: משלי טו, לא. כ, יב."],["869","42","<b>פרדס ערך נשר</b>: שער עה\"כ שכ\"ג, פי\"ד."],["870","48","<b>כנפי יונה כנס\"י</b>: ראה גם לעיל המשך יונתי בתחילתו."],["871","49","<b>שמהלך על כנפי רוח</b>: ע\"פ תהלים קד, ג."],["872","51","<b>דעיניך יונים</b>: שה\"ש א, טו. ד, א."],["873","52","<b>יונתי בחגוי</b>: שם ב, יד. ראה בריש המאמר שלאח\"ז (סיום יונתי)."],["874","53","<b>הראיני. . תומ\"צ</b>: ראה במאמר שם ובהערה 3."],["e18","*","קטרת בבגדי לבןא, גוון עצמיב, בד עולה יחידיג כו'.\nקטרת בבגדי לבן: ראה יומא לא, א-ב. רמב\"ם הל' עבודת יוה\"כ רפ\"ב. מאמרי אדה\"א דברים ח\"ג ע' א'קלט.\nלבן גוון עצמי: ראה לקו\"ת אחרי כח, ג. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1436.\nבד עולה יחידי: ראה רש\"י ותוס' זבחים יח, ב. תו\"ח תרומה ח\"ב שז, א."]]],[2000480156,"מנהיג הכנפי'<sup data-n=\"875\">54</sup> ברצו\"ש, והענין זוג יונים כל הענג מההסתכלות<sup data-n=\"876\">55</sup>, כן בישראל ישמח ישראל<sup data-n=\"877\">56</sup> ע\"י לאסתכלא ביקד\"מ<sup data-n=\"878\">50</sup> ע\"י התבוננות, מה רבו<sup data-n=\"879\">57</sup> ומה גדלו<sup data-n=\"880\">58</sup>, שאו מרום עיניכם<sup data-n=\"881\">59</sup> וראו, הסתכל בג\"ד בד\"ה ואלה המשפטי'<sup data-n=\"882\">60</sup>, ובד\"ה יהודה אתה<sup data-n=\"883\">61</sup> ובד\"ה חכלילי<sup data-n=\"884\">62</sup> נת' שז\"ע אה' בתענוגי', ובד\"ה לבבתני<sup data-n=\"885\">63</sup> באחד מעיניך, ועיקר פי' עיניך יונים שאינם שבעי' בההסתכלות מלהפסיק בכ\"י יהיו בעיניך כחדשים<sup data-n=\"886\">64</sup>, עיני האדם לא תשבענה, ההסתכלות באוא\"ס ומי איכא זקנה<sup data-n=\"887\">66</sup>, זקנה זמן נברא ומחודש<sup data-n=\"888\">67</sup>, ואוא\"ס למעלה מהזמן, והזמן אינו פועל בו, ע' בד\"ה אני ישינה<sup data-n=\"889\">65</sup> גבי יונתי.\n<b>ולבאר</b><sup data-n=\"890\">68</sup> פי' הנה מקום אתי<sup data-n=\"891\">*69</sup>, העקרים מ\"ב פי\"ז<sup data-n=\"892\">69</sup> הביא ב' דיעות מה\"ע המקום שי\"א שהמקום הוא דבר המקיף את הגשם מבחוץ, והוא ז\"ל חלק עליו והעלה שהמקום הוא הפנוי והריקות שיכנס בו הגשם, וי\"ל שכמו\"כ ברוחניות<sup data-n=\"893\">70</sup> שבעה\"מ דף א' כ'<sup data-n=\"894\">72</sup> הוא מש\"ע<sup data-n=\"895\">73</sup> היינו העיגול הג' שבתוכו החלל ומק\"פ והרשימו",[["875","54","<b>והרצון מנהיג הכנפי'</b>: ראה גם לעיל המשך יונתי בתחילתו."],["876","55","<b>זוג יונים. . מההסתכלות</b>: ראה מאמרי אדה\"ז תקס\"ד ע' קלז. לקו\"ת שה\"ש יד, ב. תו\"ח ח\"ש קלב, סע\"א ואילך ובהנסמן לשם. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תקפז."],["877","56","<b>ישמח ישראל</b>: תהלים קמט, ב."],["878","50","<b>לאסתכלא. . ביקד\"מ</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["879","57","<b>מה רבו</b>: שם קד, כד. ראה תו\"א וארא נו, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהנסמן שם."],["880","58","<b>ומה גדלו</b>: תהלים צב, ו. ראה בהערה שלפנ\"ז."],["881","59","<b>שאו מרום עיניכם</b>: ישעי' מ, כו."],["882","60","<b>הסתכל בג\"ד בד\"ה ואלה המשפטי'</b>: תו\"א משפטים עה, א ראה הנסמן לקמן במאמר ד\"ה וזהו שרש יונתי הערה 47."],["883","61","<b>ובד\"ה יהודה אתה</b>: ראה תו\"א ויגש מה, א."],["884","62","<b>ובד\"ה חכלילי</b>: ראה שם ויחי מז, ג."],["885","63","<b>ובד\"ה לבבתני</b>: ראה לקו\"ת שה\"ש כט, ג."],["886","64","<b>בכ\"י יהיו בעיניך כחדשים</b>: ראה לקח טוב ואתחנן שם. מאמרי אדה\"א דברים ח\"א ע' רסו ואילך. וש\"נ. הנחות תקע\"ז ע' שו ואילך וע' שיט."],["887","66","<b>ומי איכא זקנה</b>: ראה יבמות טז, ב. מאמרי אדה\"א קונטרסים ע' צב ד\"ה והנה. שעה\"י קפו, ג. שע\"ת כט, ב. תו\"ח תולדות קנג, א הערה 9."],["888","67","<b>זמן נברא ומחודש</b>: ראה סידור שער הק\"ש עה, סע\"ד בשם הה\"מ. שער היחוה\"א פ\"ז ובמ\"מ, הגהות והע\"ק שם ע' שעה. מאמרי אדה\"א דברים ח\"ג ע' תשצג. וש\"נ."],["889","65","<b>עיני האדם לא תשבענה. . בד\"ה אני ישינה</b>: נסמן לקמן מאמר ד\"ה וזהו שרש יונתי הערה 64."],["890","68","<b>ולבאר</b>: בהבוך נמצא ריווח בין פיסקא זו לפיסקא שלפנ\"ז לערך 7 שורות.\nמכאן ועד הסיום נמצא גם בגוכתי\"ק כ\"ק אדמו\"ר מהורש\"ב (הצילום מטושטש בכ\"מ)."],["891","*69","<b>הנה מקום אתי</b>: תשא לג, כא."],["892","69","<b>העקרים<sup data-n=\"e102\">א</sup> מ\"ב פי\"ז</b>: ראה לקו\"ת ויקרא בהוספות נ, סע\"ב ואילך. אוה\"ת בחוקותי כרך ב ע' תרנט. ספר החקירה מערכת מקום<sup data-n=\"e103\">ב</sup> ע' 148 ואילך. סה\"מ תרס\"ג ח\"ב ע' תו ואילך. המשך תרס\"ו ע' לו. סה\"מ תרע\"ט ע' קג. הנסמן בשולי היריעה."],["893","70","<b>הביא ב'. . ברוחניות</b>: השווה אוה\"ת בחוקותי שם."],["894","72","<b>שבעה\"מ דף א' כ'</b>: ראה שם. ספר החקירה שם ע' עה ס\"ג<sup data-n=\"e104\">ג</sup>."],["895","73","<b>הוא מש\"ע</b>: ב\"ר פס\"ח, ט. ראה מאמרי אדה\"א דברים ח\"א ע' רצא. וש\"נ. תו\"ח בראשית מג, א הערה 2. סה\"מ תרכ\"ט ע' קסט. וש\"נ.\n\n<b>א</b>  מובא גם באוה\"ת בחוקותי כרך ב ע' תרנט. ספר החקירה ע' 152. סה\"מ תרמ\"ג ע' צד ואילך. תרנ\"ז ע' קכו ואילך. פר\"ת ע' קפה. תרפ\"ז ע' פד ואילך. תש\"י ע' 79. מאמר ד\"ה פדה בשלום י\"ט כסלו תשי\"ג. ד\"ה קטנתי מכל החסדים י\"ט כסלו תש\"ל.\n\n<b>ב</b>  נדפס גם באוה\"ת יחזקאל כרך א ע' תב ואילך.\n\n<b>ג</b>  ומעתיק לשונו בהנוגע לענינינו (וכן להלן)."]]],[2000480157,"והקו, ובשער שמיני<sup data-n=\"896\">74</sup> קרא אותו בעהר\"צ, וככ\"ע<sup data-n=\"897\">75</sup> שי\"ג פמ\"ו<sup data-n=\"898\">76</sup> וסוף שט\"ו פ' קנ\"ב<sup data-n=\"899\">77</sup> שלכן מקום גימ' הקף<sup data-n=\"900\">78</sup> עה\"כ<sup data-n=\"901\">71</sup>, וקרוב לזה נת' בפי' בכה\"מ ממקורו ושרשו<sup data-n=\"902\">79</sup>, ובלק\"ת מהאריז\"ל פ' תשא<sup data-n=\"903\">80</sup> פי' הוא מש\"ע בסוד הצמצום שנת' אצלינו שעשה הקב\"ה מקום בתוך הצמצום<sup data-n=\"904\">81</sup> לעולמות שזהו כפי' הזהר<sup data-n=\"905\">82</sup>, וי\"ל שי\"א שבעקרים זהו כהעה\"מ, ודעת העיקרי' זהו כמ\"ש בלק\"ת. ובפרד\"ס<sup data-n=\"906\">83</sup> פי' שהכתר נק' מקום ות\"ת נק' מקום<sup data-n=\"907\">84</sup>, ובמאו\"א מ' סק\"ח<sup data-n=\"908\">85</sup> פי' מקומו בינה מקום ז\"א, ורבינו ז\"ל נ' שמפרש מקום מל' ממכ\"ע, כ\"פ בד\"ה והתהלכתי<sup data-n=\"909\">86</sup>, ובלק\"ת שלח<sup data-n=\"910\">87</sup> בביאור מקושש ובפ' בחוקתי בד\"ה בשברי<sup data-n=\"911\">88</sup>, ובת\"א בד\"ה אכלוהו היום<sup data-n=\"912\">89</sup>, ובד\"ה וארא<sup data-n=\"913\">90</sup> בפי' הוי' אחד, ובד\"ה כי אברהם לא ידענו<sup data-n=\"914\">91</sup>, וע' בד\"ה בהעלותך<sup data-n=\"915\">92</sup> שמפרש שסוכ\"ע הוא למעלה מבחי' מקום, ובעצם פי' תי' מקום פי' הרמב\"ם במ\"נ מקום ע\"ד מדריגה ומעלה<sup data-n=\"916\">93</sup>, ובמד\"ר<sup data-n=\"917\">94</sup> שהמקום שוכן אצלו כמו האדם שוכן על המקום, מקום אותיות משל לגבור שרוכב על הסוס, ונראה שרבינו ז\"ל מפרש ממכ\"ע לפי הפי' שהק\"ו",[["896","74","<b>ובשער שמיני</b>: היינו שער אדם קדמאה סתם רפ\"ט — ספר החקירה שם. אוה\"ת בחוקותי שם."],["897","75","<b>וככ\"ע</b>: וכן כתב עוד."],["898","76","<b>שי\"ג פמ\"ו</b>: בשער או\"א פמ\"ו דע\"ט סע\"ב — ספר החקירה שם."],["899","77","<b>וסוף שט\"ו<sup data-n=\"e105\">ד</sup> פקנ\"ב</b>: בספר החקירה שם: וכ\"כ בשער קרית ארבע ר\"פ קנ\"ב. באוה\"ת כבפנים."],["900","78","<b>מקום גימ' הקף עה\"כ </b>[ עם הכולל]: בעמה\"מ שם: קפ\"ו עולה מקו\"ם וכמנין הק\"ף עם המלה. מובא גם באוה\"ת בחוקותי שם. סה\"מ תרנ\"ז שם. ראה גם אוה\"ת יחזקאל כרך א ריש ע' תז. ספר החקירה שם ע' 152 מספר מגן דוד להרדב\"ז."],["901","71","<b>שבעה\"מ. . עה\"כ</b>: השווה אוה\"ת שם."],["902","79","<b>נת' בפי' בכה\"מ ממקורו ושרשו</b>: יחזקאל ג, יב. ראה לקו\"ת שה\"ש מז, ג. ספר החקירה שם סוס\"א. סה\"מ תרמ\"ג שם."],["903","80","<b>ובלק\"ת מהאריז\"ל פ' תשא</b>: עה\"פ הנה מקום אתי (לג, כא). ראה לקו\"ת ויקרא שם. אוה\"ת בחוקותי שם. סה\"מ תרמ\"ג ריש ע' צה. תרנ\"ז ע' קכח. וראה גם ספר החקירה שם ס\"ע 152."],["904","81","<b>בתוך הצמצום</b>: שם: בתוך אותו הצמצום. וכ\"ה באוה\"ת ובסה\"מ תרנ\"ז שם. המשך תער\"ב ח\"ג ס\"ע א'שלג."],["905","82","<b>שזהו כפי' הזהר</b>: ראה המשך תרס\"ו ע' לו שמציין לזהר בשלח דס\"ג ע\"ב [ואילך]. וראה גם ספר החקירה ע' 152: בשלח ס\"ג."],["906","83","<b>ובפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["907","84","<b>ובפרד\"ס פי' שהכתר. . ות\"ת נק מקום</b>: שער עה\"כ שכ\"ג, פי\"ג מערכת מקום."],["908","85","<b>ובמאו\"א מ' סק\"ח</b>: מובא גם בלקו\"ת ויקרא שם."],["909","86","<b>בד\"ה והתהלכתי</b>: מאמרי אדה\"ז הנחות הר\"פ ע' קנז. צויין אליו בספר החקירה עו, א (והועתק לשונו וכן להלן)."],["910","87","<b>ובלק\"ת שלח</b>: מג, א."],["911","88","<b>ובפ' בחוקתי בד\"ה בשברי</b>: לקו\"ת בחוקותי מח, ב."],["912","89","<b>ובת\"א בד\"ה אכלוהו היום</b>: בשלח סה, ב."],["913","90","<b>ובד\"ה וארא</b>: תו\"א וארא נה, סע\"ב ואילך."],["914","91","<b>ובד\"ה כי אברהם לא ידענו</b>: תו\"א מג\"א צג, ב"],["915","92","<b>ובד\"ה בהעלותך</b>: לקו\"ת בהעלותך כט, ד."],["916","93","<b>הרמב\"ם במ\"נ מקום ע\"ד מדריגה ומעלה</b>: ח\"א, פ\"ח."],["917","94","<b>ובמד\"ר</b>: ראה ב\"ר פס\"ח, ט. הלשון שבפנים ראה ספר החקירה ע' 150 קיצור ב.\n\n<b>ד</b>  שער או\"א נסמן שער י\"ג. שער קרית ארבע נסמן שער י\"ד. שער רישא דזעיר אנפין נסמן שער ט\"ז. ושער ט\"ו לא נסמן."]]],[2000480158,"נמשך ממל' דא\"ס<sup data-n=\"918\">95</sup> ולדעת מהרי\"ס<sup data-n=\"919\">97</sup> שנמשך מת\"ת<sup data-n=\"920\">96</sup> זהו כפי' הפרדס והכל על ממכ\"ע, והעה\"מ מפרש על סוכ\"ע ששרשו מהעיגול הג' כו', ולפי מ\"ש במ\"א בענין ואתה משמרה<sup data-n=\"921\">98</sup> שהעיקר הוא הסוכ\"ע צ\"ל כמ\"ש העה\"מ, ולפ\"ז י\"ל ופרוש עלינו סוכת שלומך<sup data-n=\"922\">99</sup> זהו בחי' מקום אתי לפי' העה\"מ שזהו תכלית השלימות וכל האזרח בישראל<sup data-n=\"923\">100</sup> עכשיו ישבו בסוכות כו'.\n<b>יו\"א</b><sup data-n=\"924\">101</sup> בעמדי בבקר נפל בפי מא' דפ\"ב דחגיגה<sup data-n=\"925\">102</sup> א\"ד<sup data-n=\"926\">103</sup> כו' ולא במע\"ב ולא במרכ'<sup data-n=\"927\">104</sup> ביחיד ולכן נמנעתי כו'.\n<b>ליל</b><sup data-n=\"928\">105</sup> א' דחגה\"ס (ש' תרמ\"א) סיפר לי את הנ\"ל שכ' ח' וכמעט יו\"ד פי' בענין הנה מקום אתי<sup data-n=\"929\">106</sup> שנים במל', וברדל\"א, ולפני הצמצום, על יסודות מכהאריז\"ל והזהר והפרד\"ס ומאו\"א, וערך ששה דרושים מרבינו ז\"ל שנמשכי' לפי פי' אחד, וריבוי משלים על ענין הנ\"ל מיחידה שבנפש, ומהתכללות המדות זב\"ז.",[["918","95","<b>שהק\"ו נמשך ממל' דא\"ס</b>: ראה סה\"מ תרס\"ד ע' קפב שמציין: לקו\"ת בהעלותך לו, א. . בע\"ח משמע. וראה גם תו\"א מקץ לט, סע\"ב. ויגש מד, ג. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ספס\"א. סה\"מ תרנ\"ט ותרס\"ה שבהערה הבאה."],["919","97","<b>מהרי\"ס</b>: מורינו הרב ר' ישראל סרוג. ראה אוה\"ת שה\"ש ח\"א ע' קצג: ומהר\"ר ר' מאיר פאפריס בזוהר הרקיע. . וקו\"ח נמשך מתפארת שבע\"ס הגנוזות. . זה הלשון הוא מקבלת ר\"י סרוג ואינו נזכר בדברי הרח\"ו ז\"ל."],["920","96","<b>שהק\"ו נמשך. . מת\"ת</b>: ראה סה\"מ תרס\"ד שם: בזוהר\"ק. המשך תער\"ב ח\"ב ע' תקנד ואילך: בזהר\"ק פ' בראשית על מאה\"ז דט\"ו. אוה\"ת (יהל אור) תהלים ע' קצ. קרח ע' תשכב. סה\"מ תרנ\"ט ע' עז הערה ד\"ה: נקודת הרושם. תרס\"ה ע' ש ואילך. תש\"ט ע' 55 (הב'). סה\"מ מלוקט ג' ע' רכג. בהערה הבאה."],["921","98","<b>ואתה משמרה</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה גם לקו\"ת דברים א, א. פ' ראה כ, סע\"ד ואילך. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה אחת הא' על יד הערה 117. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה ויאמר משה פיסקא וזהו דכתיב."],["922","99","<b>ופרוש עלינו סוכת שלומך</b>: נוסח ברכת השכיבנו."],["923","100","<b>וכל האזרח בישראל</b>: אמור כג, מב."],["924","101","<b>יו\"א</b>: יום א'"],["925","102","<b>בפי מא' דפ\"ב דחגיגה</b>: בגוכתי\"ק כ\"ק אדמו\"ר מהורש\"ב<sup data-n=\"e106\">ה</sup>: בפי' מא' פ\"ב דח'."],["926","103","<b>א\"ד</b>: [פרק] אין דורשין יג, ב."],["927","104","<b>ולא במרכבה</b>: בגוכתי\"ק ליתא."],["928","105","<b>ליל</b>: נרשם בגוכתי\"ק כ\"ק אדמו\"ר מהורש\"ב* בהמשך להנ\"ל."],["929","106","<b>הנה מקום אתי</b>: תשא לג, כא.\n\n<b>ה</b>  ראה לעיל הערה 68."]]],[2000480159,"<h3>וזהו שרש ענין יונתי בחגוי הסלע</h3>\n<b></b><b>סיום המשך ”יונתי בחגוי הסלע — תר\"ם\".\nנעתק מגוף כתי\"ק אדמו\"ר מהר\"ש נ\"ע.</b>\n&lt;59&gt;\nּ<b>וזהו</b> שרש ענין יונתי<sup data-n=\"930\">1</sup> בחגוי הסלע<sup data-n=\"931\">2</sup> שכאשר הנשמה היא בחגוי הסלע אז אינה יכולה לפרוח שמחמת הנה\"ב והגוף המסתיר ומעלים אין ביכולת הנה\"א להיות ברצו\"ש והעצה לזה הוא הראיני את מראיך השמיעני את קולך שהם בחי' תורה ומצות<sup data-n=\"932\">3</sup> כמשי\"ת לקמן בס\"ד<sup data-n=\"933\">4</sup> ושרשם בבחי' רצה\"ע, והרצון מנהיג הכנפים<sup data-n=\"934\">5</sup> ברצו\"ש, וזהו שרש ענין מה שנמשלה כנס\"י ליונה<sup data-n=\"935\">6</sup> שמה יונה כנפי' מגינות עלי'<sup data-n=\"936\">7</sup>, ומצילות אותה כך ישראל מצות מגינות עלי' ומצילם מכל צו\"צ כו', והענין הוא דהנה זוג יונים כל עיקר הענג שלהם הוא מההסתכלות<sup data-n=\"937\">8</sup> שמסתכלים זע\"ז וז\"ע יחודם להוליד בדומה להם, ועד\"ז יובן בענין ביום חתונתו זו מ\"ת<sup data-n=\"938\">9</sup> שהקב\"ה נק' בשם חתן וכנס\"י נק' כלה<sup data-n=\"939\">10</sup> עיקר הענג הוא מבחי' ההסתכלות שע\"י שכנס\"י היא בבחי' לאסתכלא ביקרא דמלכא<sup data-n=\"940\">11</sup>, עי\"ז ישמח ישראל בעושיו<sup data-n=\"941\">12</sup> כו'.\n<b>והנה</b> בכדי לבוא לבחי' ראי' זו בחי' לאסתכלא ביקרא דמלכא, צ\"ל תחילה בחי' התבוננות בגדולת ה', שעם היות שבחי' ההתבוננות זהו מבחי' שמיעה לבד עכ\"ז א\"א לבוא לבחי' ראי' הנ\"ל א\"ל שתחילה יהי' בבחי' התבוננות הנ\"ל, והיינו מפני שיש בנש\"י ב' בחי' נשמות<sup data-n=\"942\">13</sup>, שהם נשמות הגדולות הנק' בשם זרע אדם שעז\"נ",[["930","1","<b>וזהו שרש ענין יונתי</b>: מכאן מתחיל סיום המשך יונתי שנדפס לעיל<sup data-n=\"e107\">*</sup> (לא נגמר בגוכתי\"ק). נרשמו בו שני קיצורים אבל לא נסמנו פרקים.\nסיום זה לא הופיע בשעתו ביחד עם המשך הנדפס, רק בא בתור הוספה בספר התולדות אדמו\"ר מהר\"ש [קה\"ת — תש\"ז ע' 59-63 המסומנות כאן בצדדי הע'], ובהערת כ\"ק אדמו\"ר שם: ”המשך זה נדפס בשם ”לקוטי תורה תורת שמואל שער שמיני\". הסיום — מצאתי לאחר זמן\".\nפיסקא ראשונה לשון אוה\"ת שה\"ש ח\"א ע' שיג (בשינויים והוספות)."],["931","2","<b>יונתי בחגוי הסלע</b>: שה\"ש ב, יד."],["932","3","<b>הראיני את מראיך. . קולך. . תורה ומצות</b>: שה\"ש ב, יד. ראה מאמרי אדה\"ז תקס\"ט ע' צ ואילך. ע' צה. ע' ק ואילך. לעיל מאמר ד\"ה סוכה שחמתה מרובה מצלתה על יד הערה 53."],["933","4","<b>כמשי\"ת לקמן בס\"ד</b>: לפנינו לא נמצא — ההמשך לא נגמר כנ\"ל."],["934","5","<b>והרצון מנהיג הכנפים</b>: ראה גם לעיל בריש ההמשך."],["935","6","<b>שנמשלה כנס\"י ליונה</b>: שבת מט, א (צויין לעיל בפנים בריש ההמשך)."],["936","7","<b>שמה יונה כנפי' מגינות עלי'</b>: ראה הערה שלפנ\"ז."],["937","8","<b>זוג יונים. . מההסתכלות</b>: ראה מאמרי אדה\"ז תקס\"ד ע' קלז. לקו\"ת שה\"ש יד, ב. תו\"ח ח\"ש קלב, סע\"א ואילך ובהנסמן לשם. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תקפז."],["938","9","<b>ביום חתונתו זו מ\"ת</b>: תענית כו, ב (במשנה). ראה מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' לד. מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["939","10","<b>שהקב\"ה נק' בשם חתן וכנ\"י נק' כלה</b>: וכל שה\"ש מיוסד ע\"ז כידוע במדרשי רז\"ל. ראה גם מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. תו\"ח וארא ח\"א עב, ג ובהערה 7."],["940","11","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["941","12","<b>ישמח ישראל בעושיו</b>: תהלים קמט, ב."],["942","13","<b>ב' בחי' נשמות</b>: ראה תו\"א ותו\"ח ר\"פ משפטים. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 29."],["e107","*","ונדפס כאן כי כן סידורו ברשימת המאמרים שנדפס בספר התולדות אדמו\"ר מהר\"ש [קה\"ת — תש\"ז ע' 53]."]]],[2000480160,"ראיתי בני עלי'<sup data-n=\"943\">14</sup> והנה הם מועטי', ורוב הנשמות ובפרט בדורתינו<sup data-n=\"944\">15</sup> אלה בעקבות משיחא<sup data-n=\"945\">16</sup> הם נשמות הנק' זרע בהמה, וכדכתיב וזרעתי את ב\"י<sup data-n=\"946\">17</sup> זרע אדם וזרע בהמה, ותחלת זמן הזריעה היא כשגלו לבבל שעז\"נ וזרעתי' לי בארץ<sup data-n=\"947\">18</sup>, לא גלו אלא כדי להוסיף עליהם ניצוצות<sup data-n=\"948\">19</sup> שנפלו בשבה\"כ, וכמא' אלי' לבושין תקינת לון<sup data-n=\"949\">20</sup> דמנייהו פרחין נשמתין לבני נשא שהוא בחי' הלבושי' דמדו\"מ דבי\"ע שמהם רוב הנשמות כו', ואם<sup data-n=\"950\">21</sup> היות שגם מי שיש בו נשמה ממל' דמל' דעשי'<sup data-n=\"951\">22</sup>, עכ\"ז בתוכה מלובש מל' דיצי' כו' עד האצי' שבו א\"ס כמ\"ש בסש\"ב<sup data-n=\"952\">23</sup> עכ\"ז בכדי לבוא לבחי' ראי' צ\"ל תחילה ע\"י התבוננות דוקא, וענין ההתבוננות הוא כמ\"ש מה רבו מעשיך ה', וכתי' מה גדלו מעשיך ה' פי'<sup data-n=\"953\">24</sup> מה גדלו קאי על נבראי' הגדולים כמו השמים וארץ, דכתי' השמים מספרים כבוד אל וארז\"ל במד\"ת<sup data-n=\"954\">25</sup> משל לגבור שנכנס למדינה מאבנא דהוא מתעשית<sup data-n=\"955\">26</sup> בה אנן ידעין גבורתו, וכן כל צבא השמים השמש והירח שהשמש היא בערך קס\"ז פעמים גדול &lt;60&gt;\nּ מן הארץ<sup data-n=\"956\">27</sup>, והירח הוא בערך ארבעים פעמים<sup data-n=\"957\">28</sup>, וכן המלאכים משרתיו עושי רצונו נת' במ\"א שהמלאך בשליש העולם עומד<sup data-n=\"958\">29</sup> שיש בזה ב' פירושים<sup data-n=\"959\">30</sup> הא' שהמלאך הוא שליש מן כללות העולם ז\"ר וארץ",[["943","14","<b>ראיתי בני עלי'</b>: סוכה מה, ב."],["944","15","<b>בדורתינו</b>: אוצ\"ל: בדורותינו."],["945","16","<b>בדורותינו אלה בעקבות משיחא</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה עשה צדקה ומשפט על יד הערה 18. לעיל ח\"א (בחלק המאמרים) המשך מצה זו על יד הערה 1321. תו\"ח שמות ח\"א ל, א. וש\"נ. אוה\"ת שה\"ש כרך ב ע' תלח. סה\"מ תרל\"ח ע' שעט. וש\"נ."],["946","17","<b>וזרעתי את ב\"י</b>: ירמי' לא, כו [בדילוג]."],["947","18","<b>וזרעתי' לי בארץ</b>: הושע ב, כה."],["948","19","<b>לא גלו. . ניצוצות</b>: ראה פסחים פז, ב. תו\"ח שמות ח\"א מ, ג ואילך ובהנסמן שם. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 129."],["949","20","<b>לבושין תקינת לון</b>: ת\"ז בהקדמה יז, א."],["950","21","<b>ואם</b>: כ\"ה בכ\"מ — ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["951","22","<b>נשמה ממל' דמל' דעשי'</b>: ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 11."],["952","23","<b>בסש\"ב</b>: ראה לעיל המשך יונתי הערה 168."],["953","24","<b>מה רבו. . מה גדלו. . פי'</b>: תהלים קד, כד. שם צב, ו. ראה לעיל המשך יונתי פ\"ה ובהערה 120."],["954","25","<b>השמים מספרים. . במד\"ת</b>: תהלים יט, ב. שם ו [בדילוג ובשינוי]."],["955","26","<b>מתעשית</b>: ראה סה\"מ תרל\"ו ח\"ב ריש ע' רסז: ”מתעשש<sup data-n=\"e108\">א</sup>. . ובילקוט בתלים ע\"פ השמים מספרי' רמז תרע\"ב דצ\"ו ע\"ב הגירסא. . מתגושש<sup data-n=\"e109\">ב</sup> וזה עיקר\"."],["956","27","<b>שהשמש. . בערך קס\"ז. . הארץ</b>: ראה לעיל המשך יונתי פ\"ה ובהערה 123."],["957","28","<b>והירח הוא בערך ארבעים פעמים</b>: ראה לעיל המשך יונתי פ\"ה: והארץ גדולה מהירח כמו ארבעים פעמים — רמב\"ם הל' יסוה\"ת פ\"ג, ה\"ח. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה ד\"ה ואהבת את ה' אלקיך על יד הערה 34. ואולי גם כאן צ\"ל עד\"ז."],["958","29","<b>שהמלאך בשליש העולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 44."],["959","30","<b>שהמלאך בשליש העולם עומד. . ב' פירושים</b>: ראה גם סה\"מ תרל\"ג ח\"א ע' כד. תרמ\"ד מהדורת תשס\"ב ע' שיג. וש\"נ. סה\"מ ליקוט ח\"ב ע' פ [נדפס בסה\"מ] תרס\"ג ח\"א מהדורת תשנ\"ד ע' רט. סה\"מ תרצ\"ט ס\"ע 211 ואילך.\n\n<b>א</b>  וכ\"ה בילקוט המכירי תהלים שם. ראה גם הערת באבער הערה מד במד\"ת שם.\n\n<b>ב</b>  השווה אוה\"ת שבועות ע' ר. ראה גם המשך תרע\"ב ח\"א ע' קצב. אוה\"ת בראשית כרך ו ס\"ע 2086. (יהל אור) תהלים ע' סא. מאמרי אדמו\"ר הצ\"מ הנחות תרט\"ו ע' קלח. סה\"מ תרל\"ב ח\"א ע' רג. תרע\"ב ח\"ב ע' א'כב. סה\"מ תרפ\"ט ע' 109."]]],[2000480161,"ואויריהם, והב' שכלליות העולם הוא שליש מן המלאך, שזהו נבראי' הגדולי', ופי' מה רבו מעשיך הוא ריבוי התהוות הנבראים שנתהוו, מחנה מיכאל קפ\"ו אלף<sup data-n=\"960\">31</sup> מחנות כו' וכן כולם, וריבוי התהוות נבראים שנתהוו בדצח\"ם הגשמי' ריבוי מיני פרטי' עד אין שיעור מן דומם האבן הפשוט<sup data-n=\"961\">32</sup> עד פרטי מיני אבנים הטובות המבהיקים ומאירי' וכמארז\"ל ע\"פ צוהר תעשה לתיבה<sup data-n=\"962\">33</sup>, וכן בצומח פרטי' רבי' עד אין שיעור<sup data-n=\"963\">34</sup> בדשאי' ואילנות ותבואות, וכן בע\"ח למיניהם, וגם במדבר<sup data-n=\"964\">35</sup> יש מיני' רבי' כמ\"ש בספרי המדע והמחקר<sup data-n=\"965\">36</sup>, וכלליות התהוות כל הנבראי' כולם הם מהארה בעלמא, אשר לכן אני הוי' לא שניתי<sup data-n=\"966\">37</sup> שלא יש שום שינוי כלל וכלל, ואתה הוא קודם שנבה\"ע ואתה הוא לאחר שנבה\"ע<sup data-n=\"967\">38</sup> בלי שום שינוי כלל, והיינו מטעם הנ\"ל כו', ומצד בחי' זו הי' צ\"ל כליית הנפש בנש\"י להשתפך נפשם אל חיק אבינו שבשמי', וכמש\"צ<sup data-n=\"968\">39</sup> הנביא ואתם בני יעקב לא כליתם<sup data-n=\"969\">40</sup>, והיינו שמצד ההתבוננות איך שאני הוי' לא שניתי הצ\"ל בחי' כליית הנפש, אלא שמ\"מ אתם בני יעקב לא כליתם הוא מפני שנקרא' בני יעקב מל' עקב<sup data-n=\"970\">41</sup>, שעקב הלב מכל ואנוש הוא<sup data-n=\"971\">42</sup> פי' חלש הוא שמחמת חלישות כח הנפש שאין בכוחה לצאת מנרתקה ומאסרה, והוא מ\"ש כשל בעוני כחי<sup data-n=\"972\">43</sup> שע\"י העוונות נכשל ונחלש כח הנפש, וז\"ע עוונות שאדם דש בעקביו<sup data-n=\"973\">44</sup> מצד ההרגל מפני גסות הגוף וחומריותו כו', ולזה ניתנה תורה לישראל שהתו' נק' עוז ותושי'<sup data-n=\"974\">45</sup> עוז הוא לפי שנותנת כח לנה\"א, ותושי' שמתשת כח הנה\"ב עד שע\"י התבוננות בבחי' מה רבו ומה גדלו, ואשר כ\"ז הוא מהארה בעלמא לבד, תתפעל הנפש לבוא לבחי' תשוקה עכ\"פ להבטל ולכלל באוא\"ס ב\"ה כו'.\n<b></b>קיצור. יונים זיווגם הוא ע\"י הסתכלות, וכמו\"כ בכנס\"י שנמשלה ליונה ז\"ע לאסתכלא ביקרא דמלכא, אך מפני כי רוב הנשמות הם מבי\"ע, וזרע אדם",[["960","31","<b>מחנה מיכאל קפ\"ו אלף</b>: ראה זהר בהעלותך ס\"ע קנד ואילך. ולא קפיד להעתיק גם מספר המאות שבזהר שם. ראה גם סה\"מ תרל\"ח ע' קלא. וש\"נ."],["961","32","<b>ריבוי. . האבן הפשוט</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 37."],["962","33","<b>צוהר תעשה לתיבה</b>: נח ו, טז. ראה סנהדרין קח, ב. לקו\"ש נח כרך י ע' 19 ואילך ובהנסמן שם."],["963","34","<b>בצומח פרטי' רבי' עד אין שיעור</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 38."],["964","35","<b>בע\"ח למיניהם וגם במדבר</b>: ראה גם לעיל מאמר ואעשך לגוי גדול שם ובהערה 39."],["965","36","<b>בספרי המדע והמחקר</b>: ראה גם לעיל המשך יונתי הערה 128."],["966","37","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל המשך יונתי פ\"א. וש\"נ."],["967","38","<b>ואתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. ראה גם לעיל שם פ\"ו. וש\"נ."],["968","39","<b>וכמש\"צ</b>: וכמו שצועק."],["969","40","<b>ואתם בני יעקב לא כליתם</b>: ראה גם לעיל המשך יונתי ובהערה 663."],["970","41","<b>יעקב מל' עקב</b>: ראה תולדות כה, כו."],["971","42","<b>שעקב הלב מכל ואנוש הוא</b>: ירמי' יז, ט."],["972","43","<b>כשל בעוני כחי</b>: תהלים לא, יא."],["973","44","<b>עוונות שאדם דש בעקביו</b>: ראה ע\"ז יח, א. לעיל המשך יונתי ובהערה 666."],["974","45","<b>שהתו' נק' עוז ותושי'</b>: ראה מכילתא דרשב\"י יתרו פי\"ט, טז. לקו\"ת ויקרא ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקעח. וש\"נ. תו\"ח בשלח ח\"א קפד, א. וש\"נ."]]],[2000480162,"הם רק בני עלי' שמועטי' המה אפי' בדורות הראשונים, לכן צ\"ל תחילה התבוננות במ\"ש מה רבו, ומה גדלו, עד שתתפעל הנפש להיות בבחי' תשוקה עכ\"פ כו'.\n<b>ואמנם</b> לא די בבחי' התבוננות הנ\"ל לבד כ\"א שכאו\"א מישראל צריך לקיים כמ\"ש שאו מרום עיניכם<sup data-n=\"975\">46</sup> וראו מי ברא אלה שלא די בבחי' ההתבוננות הנ\"ל שבכלל שמיעה יחשב כ\"א צריך לבוא ולהגיע לבחי' ראי', וכמ\"ש וראו מי ברא אלה, והנה בחי' ראי' זו הוא בחי' ראיית השכל וזהו שארז\"ל הסתכל בשלשה דברי'<sup data-n=\"976\">47</sup> ואי<sup data-n=\"977\">48</sup> אתה בא כו', פי' הסתכל הוא הראי' בעין השכל שאדם חכם רואה את הנולד<sup data-n=\"978\">49</sup> בעין שכלו, שע\"י ראי' זו מתקרב הדבר מה שעדיין לא בא לידי פועל בגילוי כלל, כ\"א כאשר רואה בעין שכלו שכן יהי' נדמה לו כאילו כבר בא עליו בפועל ומתפחד אם רע הוא ושמח אם טוב הוא, שבחי' ראי' והכרה זו הוא מבחי' החכמה דוקא שלמעלה מהשגת הבינה, וקרוב לראיית העין &lt;61&gt;\nּ גשמי, וע\"ז אמרו איזהו חכם הרואה ובחי' ראי' זו יש גם בבחי' יחו\"ת ג\"כ, ולכן גם הנשמות דבי\"ע יכולים לבוא לבחי' וראו מי ברא אלה כו', שבחי' ראי' כזו מתייחס לבחי' חכמה דוקא קודם שבא לידי השגת הבינה, ולכן כאשר פועל בעצמו שיהי' בבחי' וראו מי ברא אלה, היינו לא בבחי' השגה בלבד שיתבונן וישיג איך שמבחי' מי נמשך להיות ברא אלה, כ\"א שיהי' ראיית השכל כאילו רואה ממש בעין הגשמי כו', וע\"י בחי' ראי' זו בא יבוא לבחי' אהבה בתענוגים שלמעלה מאה\"ר ואה\"ע, ושרשם<sup data-n=\"979\">50</sup> מש'<sup data-n=\"980\">51</sup> ע\"ב שלמעלה מש' מ\"ה וש' ס\"ג<sup data-n=\"981\">52</sup>.\n<b>ויובן</b> ד\"ז ממה שארז\"ל אינו דומה שמיעה לראי'<sup data-n=\"982\">53</sup>, ולכאו' א\"מ כלל שמאחר ששמע הדבר ומאמין שכן הוא מה מתחדש אצלו כשרואה אח\"כ הדבר ההוא כו' מאחר שכבר שמע הכל בפרטיות מהאיש המספר לו ומבאר לו הדבר איך שהוא ממש, שהרי בהכרח לומר שע\"י ראייתו שרואה אינו מתחדש אצלו בעצם מהות הדבר איזהו פרט חדש שלא סיפר לו המספר, שא\"כ אינו דומה שמיעה לשמיעה ג\"כ שהרי כשיבוא אחר ויספר לו בטוב יותר בשלימות הפרטי' יובן יותר, אלא מ\"ש רז\"ל שאינו דומה שמיעה לראי' היינו שע\"י הראי' שרואה לא מצא בדבר ההוא שום תוס'",[["975","46","<b>שאו מרום עיניכם</b>: ישעי' מ, כו."],["976","47","<b>הסתכל בשלשה דברי'</b>: אבות פ\"ב, מ\"א. פ\"ג, מ\"א. ראה תו\"א משפטים עה, א<sup data-n=\"e110\">ג</sup> [צויין אליו באוה\"ת שה\"ש כרך א ע' שיג<sup data-n=\"e111\">ד</sup>]. אוה\"ת פסח כרך ג' ע' תשצ<sup data-n=\"e112\">ה</sup>. סה\"מ תרכ\"ט ע' רסט ואילך. תרל\"ב ח\"א ע' י. ע' קצב."],["977","48","<b>ואי</b>: בסידור אדה\"ז: ואין. אבל כ\"ה הגי' במשניות."],["978","49","<b>חכם רואה את הנולד</b>: תמיד לב, א. ראה גם סה\"מ תרמ\"ג ע' פב."],["979","50","<b>ושרשם</b>: לקמן בהקיצור: ששרשה."],["980","51","<b>מש' ע\"ב שלמעלה מש' מ\"ה וש' ס\"ג</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. שער עקודים ש\"ו, פ\"ב."],["981","52","<b>ע\"ב. . מ\"ה. . ס\"ג</b>: ראה (לקמן הנחת כ\"ק אדמו\"ר מהורש\"ב — בחלק הנחותיו) הנחה ד\"ה לכל תכלה ראיתי קץ ובהערות 79-81."],["982","53","<b>אינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לק\"ט שלח יג, יח. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה ובהערה 17.\n\n<b>ג</b>  והוא מד\"ה אינו דומה שמיעה לראי' — מאמרי אדה\"ז הקצרים ע' תקנו.\n\n<b>ד</b>  ראה גם לעיל מאמר ד\"ה סוכה שחמתה מרובה מצלתה על יד הערה 60.\n\n<b>ה</b>  וכן צ\"ל בסה\"מ שבפנים ההערה — נדפס גם באוה\"ת שה\"ש ס\"ע רכא ואילך."]]],[2000480163,"פרט א' שלא סיפר לו המספר, כ\"א כל הפרטי' שרואה עתה בראיית העין הגשמי סיפר לו המספר תחילה בכיוון ממש כל פרטי פרטיות הנמצא בדבר ההוא עד שע\"י ראייתו לא ימצא שום דבר נוסף כלל בעצם שלא סיפר לו המספר כו', ועכ\"ז אינו דומה שמיעה לראי', והענין הוא שכאשר האדם שומע איזה דבר מזולתו המספר ומתאר לו איזהו ציור עד שיבינו על בוריו בעת שמיעת הדברי' מצייר השומע אותו הדבר, ומ\"מ כ\"ז בחי' ציור שמצייר הוא רק לפי ערך שמיעתו שאוזן מילין תבחן<sup data-n=\"983\">54</sup> עד שישיג אותו הדבר מכח תבונתו כו', ואמנם אח\"כ כשרואה הדבר ההוא בראיית העין שאם היות שג\"ז רק מה שמצטייר בכלי העינים שלו כמשנ\"ת מזה באריכות בד\"ה וככה, (בד' אלול וי\"נ)<sup data-n=\"984\">55</sup> עכ\"ז ההנחה מה שנקנה בנפשו ע\"י ראי' הוא באופן אחר לגמרי כו' ע\"ש, ולכן אינו דומה שמיעה לראי'. ועד\"ז יובן בענין הפרש בין ההתבוננות סתם בבחי' השגה לבחי' וראו מי ברא, שענין בחי' הראי' הוא הנחה אחרת לגמרי שנקנה בנפשו בבחי' ראיית השכל כאלו רואה בעיניו ממש.\n<b>ובעבודה</b> שרש ההפרש בין בחי' האהבה הבאה מהתבוננות השגת השכל והבנת הדבר בכח בינתו כו' לבחי' האהבה הבאה מבחי' וראו מי ברא אלה בבחי' ראי' דוקא, שהאהבה הבאה מצד בחי' ההשגה הנה לאחר שחולף ועובר ההתבוננות חולף ועובר האהבה ג\"כ שכאשר יסיר מחשבתו כרגע יכול לפנות לדרכי תאוותיה<sup data-n=\"985\">56</sup> כו', משא\"כ האהבה הבאה מבחי' ראי' שמבין אחדות ה' בבחי' הסתכלות חכמה שהוא מקור הבינה קודם שבא להתבוננות בהרחבה כו', הוא ממש כמו ראיית העינים, וא\"א לו בשו\"א להסיר מחשבתו וכל מדותיו מענין האחדות, ובכל עשיותיו ועניניו דבוק הוא בו ית', דביקות נפלא מפני &lt;62&gt;\nּ היותו רואה המלך מש\"ע<sup data-n=\"986\">57</sup> בעיניו, ולבחי' ומדריגת אהבה בתענוגי' זו זכו ישראל בזמן קבלת התורה בה\"ס עד שכל העם ראו את הקולות ראו את הנשמע<sup data-n=\"987\">58</sup>, הוא בחי' הבן שיש בחכמה כמ\"ש בס\"י הבן בחכמה<sup data-n=\"988\">59</sup> כמשנ\"ת מזה במ\"א כו'.\n<b></b>קיצור. שלא די בהתבוננות לבד אלא שצ\"ל וראו מי ברא אלה בבחי' ראיית השכל, הסתכל בג\"ד, שענין הסתכלות זו הוא קרוב לבחי' ראיית העין, ועי\"ז בא יבא לבחי' אהבה בתענוגי' כו' ששרשה מש' ע\"ב, כי אינו דומה שמיעה לראי', ובעבודה אהבה זו אינה חולפת ועוברת כו', ולבחי' זו זכו ישראל במעמד ה\"ס, ולכן הי' רואים את הנשמע ע\"י בחי' הבן בחכ' כו'.\nואמנם עיקר ענין מה שנמשלה כנס\"י ליונה שעיניך יונים<sup data-n=\"989\">61</sup> הוא כמו שהיונים מסתכלים תמיד זע\"ז ואינם שביעים בההסתכלות כלל מלהפסיק ממנו, כך",[["983","54","<b>שאוזן מילין תבחן</b>: איוב יב, יא."],["984","55","<b>בד\"ה וככה (בד' אלול וי\"נ)</b>: תרל\"ז. ראה שם פ' עקב פנ\"ז. פנ\"ח. וראה גם שם פל\"ג."],["985","56","<b>תאוותיה</b>: כ\"ה גם בתו\"א וסה\"מ תרל\"ב ע' קצב שבהערה 47. בסה\"מ תרכ\"ט שם: תאוותיו."],["986","57","<b>מש\"ע</b>: מלכו של עולם."],["987","58","<b>ראו את הקולות. . הנשמע</b>: יתרו כ, טו. מכילתא ורש\"י שם. תו\"ח נח נז, ד הערה 64."],["988","59","<b>בס\"י הבן בחכמה</b>: פ\"א, מ\"ד."],["989","61","<b>שעיניך יונים</b>: שה\"ש א, טו. ד, א."]]]]});
